window.QUIZ_LOCAL = (window.QUIZ_LOCAL||[]).concat([{"q":"○○○ 극락전내에 ○○○여래좌상을 중심으로 관음보살과 세지보살이 협시하고 있는 상태이다. ○○○여래좌상은 목이 짧고 움츠린 듯한 어깨에 허리가 약간 구부정한 자세를 취하고 있으며, 턱이 짧아지고 각이 져 딱딱해 보이는 얼굴은 눈을 가늘게 뜨고 입꼬리를 살짝 치켜올려 엷은 미소가 번져나는 듯 하다. 오똑한 코에 목에는 삼도가 뚜렷하며 법의는 통견의로서 왼쪽 팔로부터 흘러내린 소매자락은 대퇴부 쪽에서 발가락을 덮고 있다. 자연스러운 옷주름과 사실적 표현의 손으로 인하여 전체적인 분위기는 원만하며 높이 67cm, 무릎폭 43.5cm, 어깨폭 30cm 내외이다.","a":"안국사 목조아미타삼존불상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639750.jpg"},{"q":"○○시 세병관(국보 제305호) 경내 수항루 뒤편 팔작지붕 비각안에 있는 비로, 제6대 수군통제사였던 이경준이 수군 본영을 이곳에 건설한 것을 기념하기 위해 세운 것이다. 비는 받침돌 위에 비몸을 세우고 머릿돌을 올린 형태로, 머릿돌에는 구름과 두 마리의 용이 여의주를 물어서 받치고 있는 모습이 조각되어 있다. 비문의 내용은 이 비를 세우게 된 경위와 이경준 통제사의 가문과 약력, 통제영을 ○○○로 옮기게 된 이유, 이경준의 인간됨과 업적 등이 실려있다.","a":"통영 두룡포 기사비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641594.jpg"},{"q":"영모정은 임붕(1486∼?)이 중종 15년(1520)에 지은 정자로 처음에는 그의 호를 따서 귀래정이라 하였으나 명종 10년(1555)에 후손이 다시 지으면서 영모정이라 이름을 바꾸었다 한다. 또한 임붕의 손자인 조선시대 명문장가 백호 임제가 시를 짓고 사람을 사귀었던 곳이기도 하다. 지금 있는 건물은 1982년 다시 고쳐 지은 것이다. 건물은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 왼쪽 1칸은 온돌방, 오른쪽 2칸은 마루로 되어 있다. 영모정은 비교적 오래 전에 지었고 정자의 건축 규범을 보여 주고 있다.","a":"나주영모정","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654272.jpg"},{"q":"○○○은 조선 영조 12년(1736)에 용궁 전씨의 시조인 전섭의 47대손인 전후회가 세웠다. 율곡 선생의 학덕을 흠모하여 자신의 호를 경율이라 하고, 서당 이름도 ○○○이라 했다. 후손들의 학문 연수와 인격 수양의 장소로 훌륭한 인재가 많이 배출됐다. 앞면 4칸·옆면 2칸으로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕으로 되어있고 4면 모두 마루가 있어 전형적인 서당의 구조형식을 보여주고 있다. 지붕 마루 끝에 있는 기와에 ‘옹정30년을유’라는 글이 있어 1730년대의 건물임을 알 수 있다. 현재는 해마다 전씨 문중의 제사를 지내는데 이용되고 있다.","a":"옥천 경율당","c":"시도유형문화유산","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638695.jpg"},{"q":"대연사는 백제 의자왕 16년(656) 나·당연합군과 싸우다 전사한 장병들을 기리기 위해 도참선사가 창건한 사찰이다. 대연사 경내에 자리하고 있는 이 석탑은 2층 기단(基壇) 위로 탑신(塔身)을 올린 모습이다. 아래층 기단은 1매의 네모진 널돌로 하여 바닥돌과 겸하고 있는 단순한 형태이다. 위층 기단 윗면에는 탑신의 1층 몸돌을 괴기위한 받침을 두었다. 탑신의 몸돌은 각 층마다 모서리에 기둥 모양의 조각을 두었다.","a":"대련사삼층석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661185.jpg"},{"q":"○○○는 탐라(지금의 제주)의 시조인 고·양·부 삼신인(三神人)이 지금의 온평리 바닷가에 떠밀려 온 나무상자 속에서 나온 벽랑국의 세 공주를 각각 맞이하여 혼인을 올렸다는 조그마한 연못이다. 삼신인은 수렵생활을 하고 가죽옷을 입고 고기를 먹으며 살다가, 나무상자 속에서 나온 송아지와 망아지를 기르고 오곡의 씨를 뿌려 태평한 생활을 누렸으며, 이때부터 농경생활이 시작되었다고 한다. 나무상자가 발견된 해안을 황루알이라고 부르는데, 황루알에는 세 공주가 바위에 디딘 발자국이 남아있다고 한다.","a":"혼인지","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657772.jpg"},{"q":"본 사경은 감색의 저지(楮紙)에 은니(銀泥)로 쓴 권자본(두루마리) 형식의 ○○○ 사경으로 역시 동아대학교박물관에 소장된 소조보살좌상의 복장유물 중 하나라고 전해진다. 본 사경은 권수(卷首, 사경의 첫 부분) 부분이 결실되어 사성기(寫成記)가 없어 사성연도를 알 수 없으나, 경기도 안성 청원사(淸源寺)의 본존불에서 복장유물로 출토되어 동국대학교박물관에 소장된 감지은니○○○ 권제41과 1행 17자 형식에 자경의 크기도 비슷하며 서체도 거의 같다.","a":"대방광불화엄경 권41","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636756.jpg"},{"q":"광주광역시 광산구 박호동에 있는 ○○○○○은 충민공 양산숙 일가 7명을 기리기 위해 인조 13년(1635)에 세운 정려문(旌閭門)이다. 정려문은 충신, 효자, 열녀 등을 표창하기 위해 나라에서 그 동네에 세워주는 문을 뜻한다. ○○○○○은 정면 5칸·측면 1칸짜리 맞배지붕의 평범한 건물이다. 원래는 양산숙을 비롯하여 효자, 열녀, 절부 각 2명씩을 모셨으나, 회진임씨 문중으로 출가한 양산룡의 딸은 임씨문중에서 모시고 있어 현재는 6분의 정려만을 모시고 있다.","a":"양씨삼강문","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645750.jpg"},{"q":"내변산 천왕봉 아래 있었던 ○○○터이다. ○○○는 통일신라 신문왕 9년(689)에 초의선사가 세운 절로 조선시대에 양녕대군이 고쳐지었다고 전하나 한국전쟁으로 불타버렸다. 내변산의 4대 사찰 중의 하나였고, 현재는 절터 내에서 조선시대 것으로 추정되는 기와조각이 출토되고 있으며, 고승의 사리나 유골을 넣어두던 둥근 돌탑의 석조부도가 3기 남아있다. 3기의 부도 중 2기는 종 모양으로 비교적 양호한 상태이다.","a":"부안실상사지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653584.jpg"},{"q":"부산광역시 기장의 ○○○ 마을 해안 가까이에 있는 구릉을 이용하여, 임진왜란 때 왜군의 장수 구로다가 조선·명나라 연합군의 공격을 방어하고 남해안에 장기간 머물기 위해 쌓은 성이다. 돌로 쌓았으며 둘레는 약 960m, 성벽높이는 약 4m이다. 왜성은 대개 강이나 바다에 가까운 구릉을 택하여 수송·통신 등에 자유롭고 선박의 출입이 편리한 장소에 성을 쌓는다. 이 성은 부산왜성과 형태가 비슷하며 일본에서는 기장성이라고도 불리어지고 있다.","a":"기장죽성리왜성","c":"시도기념물","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645206.jpg"},{"q":"사월(沙月) 조임(趙任 1573~1644)이 1621년에 건립한 정자인데, 1889년에 후손인 조언겸(趙彦謙)이 중수하였다. 정자는 정면 4칸, 측면 2칸 규모의 팔작기와집이다. 정자의 주위에는 방형의 토석담장을 둘렀는데 전면 담장사이에는 사주문을 세워 정자로 출입케 하였으며, 정자의 우측에는 조임의 신도비각이 배치되어 있다. 평면은 2칸 대청을 중심으로 좌우에 온돌방 1칸씩을 연접시킨 중당협실형(中堂挾室形)인데, 전면에는 평난간을 세운 헌함을 설치하였다.","a":"영양 숙운정","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663549.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 중종 12년(1517)에 처음 세운 것으로 선조 24년(1591)과 광해군 2년(1610)에 고쳐 지었다. 인조 21년(1643)에 향교의 위치가 너무 높아 평지인 지금 있는 자리로 옮겼다. 건물 배치는 앞쪽에 배우는 공간으로 강당인 명륜당이 있고, 뒤쪽에 제사 공간인 대성전이 있어 전학후묘의 구조로 되어 있다. 명륜당은 앞면 5칸·옆면 2칸 규모로 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"홍산향교","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652969.jpg"},{"q":"○○○ Reiner가 살던 집으로 1910년경에 지어진 것으로 보인다. Reiner 후로 Chamness, Sawtell 등의 ○○○가 살았고, (1984~1993)까지는 동산병원 의료원장인 H.F Moffett가 거주 하였었다. 현재는 의료박물관으로 활용되고 있다. 남북으로 뻗은 긴 네모형으로 1층 내부에는 거실·서재·부엌·식당·계단 등이 있고, 2층에는 2개의 침실이 있다. 외부에는 나무로 된 현관과 베란다를 설치했으며, 지붕에는 2개의 붉은 벽돌로 된 굴뚝이 솟아있다. 당시 우리나라에 거주했던 미국인의 건축·주거·생활 양식을 살펴볼 수 있는 건물이다.","a":"선교사챔니스주택","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636883.jpg"},{"q":"○○○는 조선 전기까지도 전국에서 가장 큰 절이었다. 1997년부터 약 20년에 걸친 발굴 조사가 이루어졌는데, 수많은 건물지와 유물이 드러났다. 고려 시대부터 조선 중기까지 왕실과 밀접하게 관계를 유지하며 전국최대의 가람으로 조영되었던 만큼 이곳에서 발굴된 유적과 유물들이 높은 가치를 갖고 있다. ○○○○ 맷돌은 ○○○○ 영역의 동쪽 지역에 위치하는 건물지 내부에서 2기가 남북으로 나란히 발굴되었다. 건물지 내부에는 맷돌뿐 아니라 서쪽 전면에서 대형수조 2기도 함께 발굴되어 이곳의 용도는 주로 취사와 관련된 시설일 것으로 추정하게 되었다.","a":"회암사지맷돌","c":"시도민속문화유산","nc":"","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658160.jpg"},{"q":"○○○에 보존되어 있는 그림으로, 제석천(帝釋天)을 비롯한 여러 권속들을 그린 ○○○이다. ○○○는 대승불교에서 호법선신(護法善神)으로 봉안되어 신앙의 대상이 된 신중(神衆)을 알기 쉽게 그림으로 나타낸 예배용 불화이다. 이 ○○○○○는 비단 바탕에 채색하여 그려진 것으로, 화면은 크게 상하 2단으로 구분하여 상단에는 제석천을 중심으로 좌우에 천동·천녀·일궁천자·월궁천자가 각각 배치되어 있고, 하단에는 깃털 투구를 쓴 위태천(韋태天)을 중심으로 좌우 8금강(金剛)(우측에 5명, 좌측에 3명)이 배열되어 있다.","a":"범어사 제석신중도","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636695.jpg"},{"q":"원적산 능선 위에 있는 조선시대의 암자로 내원사 계곡에 있었다는 89암자 중의 하나이다. 선덕여왕 15년(646)에 원효대사가 지었으며, 인조 24년(1646)에 영훈대사가 다시 지었다. 그 후 여러 차례의 수리를 거쳐 오늘에 이르고 있다. 법당의 현판은 ○○○으로 되어있으며, 앞면 6칸·옆면 3칸 규모이다. 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕이며, 기둥 위에서 지붕 처마를 받치는 공포가 기둥 위에만 있는 주심포 양식의 건물이다. 조선 후기 건축양식을 잘 갖추고 있으며, 비교적 변형없이 잘 보존되어 있어 불교건축사에 중요한 연구자료로 이용되고 있다.","a":"양산 안적암 대웅전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641617.jpg"},{"q":"통정대부를 지낸 바 있던 정래영이 정극후(1577∼1658)을 추모하기 위해 순조 14년(1814)에 세운 사우와 서사(書社)였다. 사우는 흥선대원군의 서원철폐령으로 폐쇄되고, 지금은 서사만 남아 있다. 최근에 서사를 서당으로 이름을 바꿨다. 정극후은 조선 중기의 문신으로 거의 60의 나이에 벼슬길에 올랐으나 곧 사퇴하고 후학양성에 전념하였다. 저서로는 『문묘사향지』, 『역년통고』, 『서악지』 등이 있다. 서당 규모는 앞면 5칸·옆면 2칸으로, 가운데에 마루를 두고 양쪽 칸에 방을 두었다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"성산서당","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662734.jpg"},{"q":"○○○는 지리산 남쪽 기슭에 있는 절로 통일신라 성덕왕 23년(723)에 삼법이 지었으며, 문성왕 2년(840)에 진감국사가 다시 지었다. 원래 이름은 옥천사였으나 정강왕(재위 886∼887) 때 ○○○로 이름을 바꾸었다. 임진왜란 때 불타 없어진 것을 벽암이 조선 인조 10년(1632)에 다시 지어 오늘에 이르고 있다. ○○○은 일주문 다음에 통과하는 문으로 천왕문과 함께 절에 들어오는 공간으로 불법을 수호하고, 속세의 더러움을 씻어내는 의미있는 장소이다.","a":"하동 쌍계사 금강문","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641665.jpg"},{"q":"이 건물은 고령 박씨의 중시조인 청하공(淸河公)의 묘소를 지키고, 문중 회의를 열기 위해 조선 현종(顯宗) 11년(1670)에 건립되었다. 만대산(萬代山)아래 평지리 새미실 부락의 방형 일곽 안에 대문채와 강당이 남동향으로 자리잡고 있다. ○○○는 낮은 막돌기단 위에 정면 4칸, 측면 2칸으로 홑처마 팔짝지붕이다. 평면은 가운데 2칸의 대청을 두고 양측에 온돌방을 두었으며 온돌방 전면에 툇마루를 설치하였다. 건물 양 측면에는 쪽마루를 부설하였다.","a":"만남재","c":"시도유형문화유산","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640313.jpg"},{"q":"조선 단종 때의 충신인 절재(節齋) ○○○○○의 묘소이다. 태종 5년(1405) 문과에 급제한 후 함길도 도절제사 등 여러 관직을 역임하였다. 세종 16년(1434)에 6진을 개척하여 국토 확장의 위업을 이룩하여 현재 두만강을 경계로 하는 우리나라의 국경선이 이때에 확정되었다. 또『고려사』,『고려사절요』,『세종실록』등의 편찬에 참여하여 학자적인 면모도 보여주었다. 단종이 12세로 왕위에 오르자 좌의정으로 어린 왕을 보필하다 왕위를 노리던 수양대군(뒤의 세조)에 의해 단종 1년(1453) 두 아들과 함께 죽음을 당했다.","a":"김종서 장군 묘","c":"시도기념물","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1658030.jpg"},{"q":"동강변의 바위 위에 있던 정자로, 1913년에 짓고 영락정이라 하였다. 1940년 신응인이 인수하여 ○○○으로 이름을 바꾸었으며, 1975년 안동댐 건설공사로 인하여 지금의 위치로 옮겨졌다. 앞면 3칸·옆면 2칸의 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다.","a":"용암정","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640300.jpg"},{"q":"일선리 마을에 자리잡고 있는 개의 무덤이다. 주인을 구하려 목숨을 바친 개의 충직함을 기리고 있는데, 충성스런 개의 행적을 그린 의구도(義狗圖) 4폭이 함께 보존되어 있다. 전하는 이야기에 따르면, 해평면 산양리에 사는 김성발이라는 사람이 기르는 개가 있었는데, 매우 영리하여 늘 주인 곁을 떠나지 않았다. 하루는 주인이 이웃마을에 갔다가 돌아오는 길에 술에 취해 그만 길가에서 잠이 들었다. 마침 들에 불이나 주인이 위험하게 되자 개는 놀라 멀리 떨어져 있는 낙강으로 뛰어가 꼬리를 물에 적셔 불을 끄기를 여러 번 하다가 지쳐서 그만 죽고 말았다.","a":"의구총","c":"시도민속문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658825.jpg"},{"q":"‘○○○○○’는 조선 중기의 문신 ○○○의 영정을 모신 사당이다. ○○○은 선조~인조 대까지 영의정을 여섯번이나 지냈지만, 소박한 성품으로 청빈하게 살았다. 일반적으로 사당에는 위패만 모시지만, 이곳 영우 내부에는 감실(龕室; 위패, 초상화 등을 봉안하기 위하여 만든 건조물)을 따로 만들어 영정을 모시고 있다. 사당은 1693년(숙종 19)에 지어졌으며, 숙종이 오리영우(梧里影宇)라는 현판을 내려주었다. 현판은 이관징(李觀徵, 1618~1695)에 의해 작성되었고, 1693년 인조가 하사한 관감당 옛터에 이 사우를 건립한다는 내용을 담고 있다.","a":"오리이원익영우","c":"시도유형문화유산","nc":"","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637687.jpg"},{"q":"설악산 ○○○에 소장되어 있는 경판은 불경을 찍어 내던 각판(刻板)으로, 나무 판에 도장 새기듯 불경을 새긴 것이다. 경판은 ‘불설대보부모은중경(佛說大報父母恩重經)’을 비롯하여 법화경(法華經) 경판 일부, 다라니경 경판 일부와 기타 흩어져 있는 몇 매의 경판 등 모두 225매가 소장되어 있다. 이 가운데 ‘불설대보부모은중경’은 3·4쪽과 13·14쪽의 경판 두 장이 빠져 있고, 한문 원문에 한글 번역문까지 함께 싣고 있으며 중요한 부분은 그림까지 그려 넣었다.","a":"속초 신흥사 목판","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"속초시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637891.jpg"},{"q":"○○○는 전북특별자치도 김제시 황산동에 위치한 사찰로, 백제 무왕 25년(624) 혜덕선사가 꿈에서 문수보살을 보고 이 절을 지었다고 전해온다. 950년 불에 타고 현판만이 지금의 장소로 날아와 고려 광종 8년(957)에 다시 절을 지었다고 한다. 대웅전에 모셔진 ○○○○○은 당당한 어깨와 건강하면서도 균형 있는 신체 표현을 보여주고 있다. 얼굴은 사각형에 가까우면서 미간이 넓고 코가 유난히 큰 특징을 보여준다. 기록에 의해 조선 숙종 41년(1715)에 만들었음을 알 수 있다.","a":"문수사목조아미타여래좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639659.jpg"},{"q":"○○○○○에 보관되어 있는 불교그림으로, 인도의 재래적인 토속신인 신중을 그린 것이다. 비단 바탕에 적색과 녹색, 갈색을 주로 사용하여 채색하였으며, 크기는 가로 198㎝, 세로 149㎝ 이다. 화면에는 천룡과 범천, 제석 등을 중심으로 비교적 많은 권속들을 그려넣었는데, 좌우 대칭구도와 천룡과 제석 등이 이루는 역삼각형의 구도가 다소 복잡한 화면구성을 보이고 있다. 특히 천녀들이 20여 종에 달한는 각종의 악기를 연주하는 다양한 모습은 매우 뛰어나다.","a":"지장사 대웅전 신중도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2588037.png"},{"q":"근처의 가까운 골짜기에 있던 것을 1927년에 현재 위치로 옮겨와 불당을 세우고 모시고 있다. 넓적한 화강암에 높이 2.73m의 보살상 돋을새김했는데, ○○○○을 표현한 것으로 보인다. 머리에는 보관(寶冠)을 썼고, 얼굴에는 눈·코·입 등이 도식적으로 표현되었지만 온화한 표정을 짓고 있다. 머리에 비하여 몸통이 짧아 균형을 잃었으며, 양 어깨를 감싸고 있는 옷은 옷주름선이 간결하게 처리되었다. 광배(光背)는 가장자리에 불꽃무늬를 새기고 안쪽에는 꽃무늬를 장식하였다.","a":"금릉덕천리석조관음보살입상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640792.jpg"},{"q":"고을을 다스리는 수령과 관리들이 집무를 보던 관청건물이다. 조선 영조 41년(1765)에 지어진 것으로 보이는데, 고흥군청 안에 관아의 정문인 아문과 본채인 ○○○이 남아있다. 본채인 ○○○은 앞면 5칸·옆면 3칸 규모로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 정문인 아문은 3칸인 3문 형식으로, 가운데 칸의 지붕이 양쪽 칸의 지붕보다 높으며 3칸 모두에는 2짝씩의 널판장문을 달았다.","a":"고흥존심당및아문","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639888.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔두는 곳이다. ○○○에 마련된 이 부도밭에는 모두 12기의 부도가 자리하고 있으며, 4기의 비석도 함께 남아있다. 12기의 부도 중에서 7기는 3단을 이루는 기단(基壇) 위로 탑몸돌 및 지붕돌을 갖추었는데, 사각의 바닥돌과 둥근 탑몸돌을 제외한 각 부분이 8각을 이루고 있다. 나머지 5기는 받침돌 위로 종 모양의 탑몸돌을 올린 모습으로, 꼭대기에는 꽃봉오리 모양의 큼지막한 머리장식을 두었다. 4기의 비는 낮은 사각받침위로 비몸을 세우고 지붕돌을 갖춘 구조이다.","a":"양양명주사부도군","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660552.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 광무 1년(1897)에 향토 유사 김광선이 향교 건립을 추진하여 지었다. 그 뒤 여러 번 보수를 거쳐 오늘에 이르고 있다. 건물 배치는 전학후묘 형식을 따르고 있다. 3층 계단식으로 맨 아래에는 학생들이 모여 공부하는 강당인 명륜당, 그 다음에 학생의 기숙사인 동재·서재, 맨 위쪽에는 제사를 지내는 공간인 대성전이 있다. 대성전은 앞면 3칸·옆면 3칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"완도향교","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662044.jpg"},{"q":"○○○은 봉황산과 제봉산 사이에 아늑하게 자리잡은 오동촌 입구에 있다. 물이 방울처럼 솟아오른다 하여 ○○○ 또는 방울 시암 즉 영천(鈴泉)이라는 이름을 얻었는데 이 샘에 얽힌 이야기가 많이 전해온다. 동네 공동 우물인 이 샘은 500여 년 전 용이 승천한 늪이였다고 한다. 옛 기록을 살펴 보면 이 샘이 영험하여 가뭄이 들면 이 샘에 기우제를 지냈고 물 색깔의 붉기도 하고 뜬물 같이 희기도 하여 이것으로서 세상일을 예측해 주기도 했다고 한다.","a":"장성 영천리 방울샘","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020121609240600.JPG"},{"q":"향교는 공자와 여러 성현께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. 금산향교는 조선 태조 1년(1392) 처음 지었으며, 임진왜란 때 불타 없어졌다. 인조 12년(1634) 대성전과 명륜당을 다시 지었고 동재·서재, 동무·서무, 묘문(廟門) 등을 복원하였다. 지금의 건물은 그 당시에 지은 것이다. 제사지내는 공간인 5칸의 대성전과 동무, 교육 기능을 수행하는 강당인 7칸의 명륜당, 학생들의 기숙사인 동재·서재, 내삼문, 외삼문 등이 남아 있다. 대성전에는 공자를 비롯한 그 제자와 우리나라 성현들의 위패를 모시고 있다.","a":"김산향교","c":"시도유형문화유산","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641275.jpg"},{"q":"경주 금오산 정상에서 서쪽으로 바로 쏟아져 내린 골짜기를 산호곡 또는 ○○○○이라 한다. 이 계곡의 바위면에 높이가 8.6m나 되는 거대한 불상이 새겨져 있는데, 현재는 머리 부분이 없어지고 어깨 아래 부분만 남아 있다. 머리는 따로 만들어 붙인 듯 목부분에 머리를 고정시켰던 구멍이 뚫려 있다. 바위면의 양 옆을 30㎝ 이상 파내어 불상이 매우 도드라지게 보이며, 손이나 옷주름 표현에서도 10㎝ 정도로 깊게 돋을새김하여 입체감이 뛰어나다. 왼손은 굽혀 가슴에 대고 오른손은 내려서 허리 부분에 두었는데, 모두 엄지, 검지, 약지를 맞대고 있다.","a":"경주약수계곡마애입불상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640457.jpg"},{"q":"서울역사박물관에 소장된 이 불상은 높이가 58.8cm에 이르는 고려 말～ 조선 초 시기의 ○○○○○이다. 전체적으로 단정하고 아담하며 균형잡힌 체구에 두 눈을 지그시 감아 깊은 명상에 잠긴 듯한 표정을 하고있는데 통통하게 살이 붙은 얼굴에는 입가에 약간 미소가 떠올라 있다. 이 불상의 경우 머리에서 늘어진 머리카락이 귀를 감아 내려와 어깨에서 한 번 매듭이 지어진 뒤 어깨 아래로 치렁치렁하게 늘어진 모습을 하고 있는데 이러한 머리카락 표현은 고려시대 불화를 비롯하여 고려 후기 금동불좌상에 흔히 나타나는 형식으로 조선시대 불상에 이르기까지 이어졌다.","a":"금동보살좌상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590286.png"},{"q":"풍호라는 호수를 끼고 바다를 바라보고 있는 얕은 언덕에 위치한 무덤이다. 무덤의 내부구조를 보면 돌덧널(석곽)을 만들고 시신을 위에서 아래로 넣은 구덩식돌덧널무덤(수혈식석곽묘)이다. 돌덧널 안에는 시신을 안치하는 으뜸덧널(주곽)과 껴묻거리(부장품)만 넣는 딸린덧널(부곽)로 구분된다. 출토 유물로는 목긴항아리(장경호)·굽다리접시(고배) 등이 있다. ○○○ 무덤들은 그 구조와 유물을 종합해 볼 때 삼국시대에 만들어진 것으로 생각되는 곳이다.","a":"하시동고분군","c":"시도기념물","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647752.jpg"},{"q":"○○○○○ 사당은 임진왜란 5년 전인 1587년에 침입한 왜구를 당시 녹도수군만호진의 책임자였던 ○○○수군만호가 격전을 벌이다 왜적을 물리치고 전사한 곳으로 섬 주민들에 의해 세워진 사당이다. 1919년과 1923년에 중수를 거쳐 1983년 마을 주민의 정성으로 현재 사당 건물을 중창하여 이때부터 충렬사라 하였다. ○○○ 장군의 행적을 통하여 국난을 극복한 역사적 현장이고 육지부에 멀리 떨어진 섬 지방의 호국유적지로서 선현 현창의 의미를 살려 역사성과 장소성에서 가치가 있다.","a":"여수 손죽도이대원사당","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662271.jpg"},{"q":"□ 材質形狀 : ○○, 도금, 대좌별조 □ 規 格 : 總高 55.7 cm 像高(촉포함) 44.0 cm 頭高 16.0 cm 이마선～턱 8.5 cm 面幅 10.0 cm 耳～耳 13.5 cm 肩幅 20.0 cm 胸厚 12.3 cm 腹厚 13.4 cm 膝幅 27.3 cm 膝高 7.0 cm 像底前後最大徑 24.3 cm 像底左右最大徑 29.3 cm 像底腹藏孔前後徑 8.3 cm 像底腹藏孔左右徑 8.3 cm 現 狀 본 조사 불상은 ○○○ 주법당에 삼존불의 형태로 봉안되어 있으며, 삼존불중 본존상이다.","a":"김해 모은암 석조 아미타여래좌상","c":"문화유산자료","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666592.jpg"},{"q":"신라말 구산선문의 하나인 사굴산파의 개산조 범일의 진영으로서 의자에 앉아 있는 전신교의 좌안칠분면상으로 조선후기 진영의 전형적인 형태를 갖고 있는 작품이며, ○○○○의 진영은 현존하는 유례가 드물고 조사의 진영도로서는 드물게 화기를 남기고 있어 정확한 제작연대를 알 수 있어 보존가치가 크다. 이 진영은 삼척시 근덕면 궁촌리 ○○○의 칠성각에 봉안되어 있던 것인데, 1999년 6월 18일 월정사성보박물관으로 옮겨 전시중에 있다. 그림 하단 중앙에 있는 화기(畵記)에 의해 1788년(乾隆 53년)에 신겸(信謙) 등에 의해 제작되었음을 알 수 있다.","a":"영은사범일국사진영","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638266.jpg"},{"q":"○○○○○의 ○○○에 있는 조선시대의 ○○이다. ○○○는 「태화산 ○○○ 사적 입안(泰華山 麻谷寺 事蹟 立案)」에 따르면 640년(신라 선덕여왕 9)에 자장율사(慈藏律師)가 창건하였고, 고려 중기에 보조국사 지눌(知訥)에 의해 중건되었다. ○○○○○은 신라이래의 전형적인 종의 형식을 따르고 있으며, 보존상태도 매우 좋고 문양의 표현도 매우 사실적이다. 종신(鐘身)의 꼭대기에는 등을 크게 구부리고 있는 한 마리의 용이 종신을 들어 올리는 모양의 용누(龍鈕)가 있는데, 용의 꼬리는 음통(音筒)을 휘감고 있다.","a":"공주 마곡사 포교당 범종","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639301.jpg"},{"q":"조선 전기 문신이며 시인인 송강 정철(1536∼1593) 선생의 위패를 모시고 있는 사당이다. 선생은 정치인보다 시인으로서 천부적인 재질을 나타냈는데, 관찰사로 재직하면서 『관동별곡』, 『훈민가』, 『성산별곡』 등을 지었고 낙향한 뒤에는 『사미인곡』, 『속미인곡』 등 많은 가사와 단가를 남겼다. 이 사당은 경기도 고양에 있던 정철의 묘를, 현종 6년(1665) 송시열 선생이 정한 현 자리로 옮기면서 지은 건물이다. 지금 있는 것은 규모가 너무 작아 1979년 새로 지은 것이다.","a":"진천 정송강사","c":"시도기념물","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649197.jpg"},{"q":"원래 정화사라는 절터였다고 전하는데 조선 철종 3년(1852) 고재극 씨가 지어 오늘에 이르고 있다. 남부지방에서 흔히 볼 수 있는 一자형 구조를 이루고 있다. 경사가 급해 건물은 3단으로 나누어 구성하였다. 제일 아랫단에 대문과 하인방을, 그 다음 단에 마당·창고·관리사를 두고, 맨 윗단에 본채와 양옥을 배치하였다. 안채는 앞면 5칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양의 팔작지붕으로 꾸몄다. 주변에는 소나무와 느티나무, 배롱나무, 대나무 등이 한데 어울려 한옥의 운치를 더해주고 있다.","a":"장흥 무계고택","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662137.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔두는 곳이다. ○○초등학교 내에 있는 이 부도는 전체가 마치 연꽃봉오리 모양을 하고 있다. 원래는 ○○○의 옛 절터에 있던 것을 이곳으로 옮겨 놓은 것이다. 부도의 형태는 안상(眼象)을 새긴 네모난 바닥돌 위에 연꽃 받침과 연꽃 봉오리 모양의 탑신(塔身)을 올린 간결한 형태이다. 탑신은 모양 자체도 연꽃봉오리 모양일 뿐만 아니라 표면 전체에도 연꽃잎을 가득 새겨 놓았다. 바닥돌에 새긴 안상무늬와 탑신의 연꽃무늬조각 등으로 보아 고려 전기의 작품으로 추정된다.","a":"영동 심원리 승탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638583.jpg"},{"q":"조선 전기 문신이었던 ○○○과 그의 아버지 판서공 변옥란, 친형인 춘당 변중량의 행적을 기록해 놓은 비를 보호하고 있는 ○○이다. ○○○은 조선 건국 초기에 예조판서 등의 여러 중요한 관직을 거쳤으며, 특히 문장에 뛰어나 20여년간 대제학을 맡아 외교문서를 작성하였다. 세종(재위 1418∼1450) 때에는 『태조실록』의 편찬과 『고려사』수정 작업에 참여하였다. 변옥란(1322∼1395)은 고려말에 3판서를 지내고, 이성계를 추대하여 조선 개국의 공신이 되었다. 변중량(1352∼1398)은 조선 태조 때 좌승지를 지냈으며 시문(詩文)에 능하였다.","a":"밀양 변계량 비각","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663846.jpg"},{"q":"○○○○○는 ○○○가 매년 인종의 기일(忌日)인 7월 1일 맥동마을 난산(卵山)에 올라 북망통곡(北望慟哭)한 것을 기리기 위하여 세운 비이다. 호패형의 일반형 석비로 전면 상단에 전서로 횡서로 ‘난산지비(卵山之碑)’, 첫줄에 종서로 ‘○○○’라 제하고, 이어 찬자(윤행임)와 서자(이익회)를 쓰고 비문을 적고 있다. 비문은 비의 제목을 포함하여 모두 31행(전 10행, 좌 5행, 후 10행, 우 6행), 1행 26자이다. 비문은 석재 윤행임(1762∼1801)이 짓고, 이익회(1767∼1843)가 글씨를 썼다.","a":"장성 김인후 난산비","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2022101214072400.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 경상남도 ○○시 ○○○ 고인돌은 와룡산에서 서쪽으로 뻗어내린 능선 끝자락 구릉지역에 있다. 이곳에는 현재 김해 김씨의 문중 무덤이 있는데, 이 무덤 주위에 모두 5기의 고인돌이 일정한 간격으로 늘어서 있다.","a":"사천 신벽동 지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654923.jpg"},{"q":"○○○라는 마을 위쪽의 밭에 서 있는 3층 석탑이다. 3면이 산으로 둘러싸인 탑 주변은 기와조각이 흩어져 있을 뿐 다른 유물은 없다. 탑은 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올렸는데, 현재 세번째 탑신은 없어졌다. 1 ·2층 기단과 탑신의 몸돌에는 기둥 모양을 새겼다. 지붕돌은 네 귀퉁이가 살짝 치켜올라 갔고, 밑면에는 4단의 받침을 두었다. 전체적으로 기단과 탑신 몸돌에 새긴 기둥조각 등은 정교하나, 1층 몸돌에 비해 2층 몸돌이 급격히 줄어들어 균형을 이루지 못하고, 또한 3층 몸돌을 잃어버려 아쉬운 감이 있다.","a":"공주동원리석탑","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639085.jpg"},{"q":"○○○ 절터는 대동여지도를 비롯한 여러 기록과 유물들을 종합해 볼 때 신라의 돈각사라는 절이 있었던 곳으로 추정된다. 절터 주변에는 탑과 석등 등의 석재들이 흩어져 있다. 탑은 전형적인 통일신라 석탑의 양식을 잘 따르고 있으나, 기단부(基壇部)가 3층으로 되어 있어 보기드문 형태이다. 현재 무너져 있긴 하지만 대부분의 부재들이 깨지지 않은 상태로 거의 완벽하게 남아있다. 통일신라 후기에 세운 탑의 부재들로 추측된다.","a":"삼척흥전리삼층석탑재","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638193.jpg"},{"q":"이 서당은 조선 명종 때 육현신의 한 사람으로 광주목사를 지낸 갈천 임훈이 후학 양성을 위하여 그의 아우 임운과 1573년에 건립하였음. 그 후 1878년에 후손들이 중건한 목조와가건물임. 건물구성은 강당과 대문으로 되어 있는데, 강당은 정면 5칸,측면 1칸 반의 맞배지붕 홑처마이고 양측 면에 풍판을 달았음. 처마 밑에는 그 당시 사용하던 큰북의 외통이 걸려있음. 대문은 맞배지붕 솟을 대문이며 뜰에는 후손들이 세운 두 형제의 신도비가 나란히 세워져 있음.","a":"거창 갈천서당","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642177.jpg"},{"q":"○○○은 고려말 이래 영호남에서 조세로 내는 곡식을 실어나르는 조운선이 통과하는 지역으로, 이를 약탈하려는 왜구를 방어하기 위해 연산군 5년(1499)에 진성을 쌓게 되었다. 그리고 이곳에는 종4품의 무관직인 만호를 배치하였다. 『여지도서』에 따르면 이 성의 둘레는 890척(약 270m), 높이는 1척(약 3.7m)이라고 기록되어 있다. 현재 성벽의 총 연장길이는 730m 정도이며, 정사각형 또는 직사각형의 커다란 돌로 만든 기단 위에 가로 30㎝, 세로 20㎝ 정도되는 작은 돌들을 이용하여 쌓아올렸다.","a":"강진마도진만호성지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654335.jpg"},{"q":"조선 중기의 무신인 만운(晩雲) 정충신(1576∼1636) 장군의 묘소이다. 선조 25년(1592)에 임진왜란이 일어나자 17세에 권율 장군의 휘하에서 종군하였으며, 병조판서 이항복에게 학문을 배워 같은 해 가을에 무과에 합격하였다. 1624년에 일어난 이괄의 난을 평정하여 진무공신 1등으로 금남군에 봉해졌으며, 1627년 정묘호란 때에는 팔도부원사로 중국 청나라 군대를 철군시켰다. 1630년 평안도에서 일어난 유흥치의 난을 평정한 후 오위도총관, 포도대장 등을 거쳐 경상도 병마절도사를 역임하였다.","a":"정충신묘","c":"문화유산자료","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661259.jpg"},{"q":"이중환의 택리지에 ‘조선인재반재영남(朝鮮人材半在嶺南)’이라는 대목이 나온다. ‘조선 인재의 반이 영남에서 태어났다’는 뜻이다. 특히 진주는 강․하․정씨가 본관을 두고 있을 정도로 많은 인물들이 탄생하였으니, 진주지역에도 인명록 출판이 성행하였다. 곧, 연계안(蓮桂案)이나 향안(鄕案)이 그것들이다. 연계안은 진주출신으로서 과거에 급제한 인물들의 이름을 적은 명부이고, 향안은 진주에서 학식과 덕행을 두루 갖춘 선비의 이름을 적은 인명록이다.","a":"계방안(1910년)","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642562.jpg"},{"q":"제주시 봉개동 동회천 마을의 본향당이다. 이당은 '○○○○○또' 를 모시는 전형적인 산신당이다. 이 당은 제주시 지역에서는 드물게 당굿이 전승되는 곳이며, 당굿을 할 때 산신놀이를 벌이는 곳이기도 하다. 제장 한가운데 보호수로 지정된 늙은 팽나무가 있어 이를 신목으로 삼는다. 신목 왼쪽에 시멘트로 나지막한 정방형의 제단을 꾸몄다. 주위에는 대나무가 자라고 있다. 주위 밭담이 자연스럽게 담장을 이룬다. 형태적인 면에서도 원형을 잘 유지하고 있다.","a":"새미하로산당","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659284.jpg"},{"q":"○○○○은 고려 공민왕(재위 1351~1374) 때의 연저수종공신(燕邸隨從功臣)에 책봉된 문목공(文穆公) 차포온(車蒲溫)선생과 두문동 72현의 한분인 문절공(文節公) 차원부(車原頫) 선생, 조선 세조(재위 1417~1468)때 발발한 이시애 난 당시 선봉장으로 활약하다가 전사하여 적개공신에 오른 강열공 차운혁(剛烈公 車云革)선생 등 3위를 배양하고 있다. 1806년(순조6) 성태리 궁동에 처음 창건된 건물은 대원군의 서원철폐령으로 자진 훼철하였으며, 지금의 서원은 유림에 의하여 1960년에 복원된 것이다.","a":"합천 덕원서원","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664158.jpg"},{"q":"○○○·대적광전 앞에 자리하고 있는 탑으로, 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올리고 있다. 위층 기단은 네 면마다 모서리에 기둥 모양을 새겨 놓았고, 그 위 지붕모양의 덮개돌은 윗면에 비스듬한 경사가 있는데, 두 모서리가 크게 부서진 상태이다. 탑신부는 1층 몸돌이 아래의 기단과 거의 같은 크기이고, 2층 몸돌은 그에 비해 크게 줄어들어 있으며, 3층의 몸돌은 없어진 상태이다. 3층 지붕돌 위로는 머리장식을 받치던 낮은 받침돌이 남아있고, 그 위에는 머리장식 대신 막돌이 하나 놓여있다.","a":"일락사삼층석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661243.jpg"},{"q":"이 불상은 머리 부분이 깨어져 있고, 두발은 나선형 머리카락으로 표현되어 있다. 얼굴은 양 옆이 납작하고 통통하며, 눈썹 사이에는 백호(白毫) 구멍이 남아 있고 눈 • 코 • 입 부분은 마모가 심하다. 목에는 삼도(三道)를 표현하고 어깨는 당당하게, 가슴은 풍만하게, 허리는 잘룩하게 표현하여 크고 넓은 무릎과 잘 어울리게 하였다. 옷은 오른쪽 어깨를 드러내고 있으며, 왼손은 손바닥이 위로 오도록 하여 무릎에 얹고 오른손은 땅으로 내린 형태를 취하고 있다. 대좌의 하대석에는 1면에 2개씩의 안상이 있으며, 특히 상대석에는 3중으로 연꽃이 조각되어 있다.","a":"경주안계리석조석가여래좌상","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662546.jpg"},{"q":"개암 ○○의 문집을 널리 간행하기 위해 만든 책판이다. ○○은 남명 조식의 문인으로, 명종 4년(1549)에 진사를 지냈으며, 명종 21년(1566)에 정여창의 신원을 회복하기 위해 상소를 올렸다. 평생 학문과 후진양성을 위해 노력하였으며, 남계서원에 봉향되어 있다. 이것은 상하 1책으로 되어 있는데, 상권에는 시(詩)·서(書)·기(記)·추록(追錄)이 있고, 하권에는 세계(世系)·연보(年譜)·행장(行狀)·제문 (祭文) 등이 수록되어 있다.","a":"강익 개암문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641769.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 세종 2년(1420)에 처음 지었는데, 임진왜란과 정유재란을 거치면서 화재로 불타 없어졌다. 그 뒤 헌종 8년(1842)에 다시 지어 오늘에 이르고 있다. 지금 남아 있는 건물로는 ○○○, 명륜당, 동재, 서재, 홍살문 등이다. 공자를 중심으로 그의 제자들과 중국과 우리나라 성현의 위패를 모시고 제사지내는 ○○○은 앞면 3칸·옆면 2칸 규모이다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다.","a":"무장향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661720.jpg"},{"q":"○○○ 청자 가마터는 2014년과 2016년에 발굴조사 되었다. 조사결과 청자 가마 1기와 관련 구상유구, 폐기물 퇴적층 등이 확인되었다. ○○○ 가마터 1호 가마는 바닥을 얕게 굴착한 후 점토와 석재를 이용해 벽을 만든 토축요(土築窯) 계통의 반지하식 오름가마[登窯]이다. 조사를 통해 출토된 유물은 자기류와 도기류, 요도구류로 분류된다. 자기류는 청자 발생기의 표식적 기종인 선해무리굽과 과도기(중국식) 해무리굽 완을 비롯하여 발, 접시, 병, 호, 주자, 뚜껑, 잔탁 등 다양한 기종이 출토되었다.","a":"장흥풍길리청자요지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020022815324600.JPG"},{"q":"한음(漢陰) ○○○ 선생은 임진왜란 때 정주까지 왕을 호종했고, 청원사(請援使)로 명나라에 파견되어 파병을 성사시켰다. 광해군 때 이이첨의 사주를 받은 삼사(三司)에서 영창대군(永昌大君)의 처형과 폐모론을 들고 나오자, 이항복과 함께 이를 적극 반대했다. 이에 삼사가 모두 ○○○을 모함하며 처형을 주장했으나, 광해군이 관직을 삭탈해 이를 수습하였다. ○○○○○ 묘는 부인 한산이씨(韓山李氏)와 합장(合葬) 단분(單墳)이다. 봉분 앞에 원수방부(圓首方趺; 둥근 머릿돌과 사각 받침돌의 비석 형태)의 묘표, 혼유석, 석상, 향로석이 차례로 설치되어 있다.","a":"한음이덕형선생묘및신도비","c":"시도기념물","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646297.jpg"},{"q":"대은(大隱) ○○○은 원(元)나라 출신 무장(武將)으로 본관이 황주(黃州)이며, 1351년에 공민왕(恭愍王)을 따라 고려로 왔다. 공민왕은 ○○○에게 판추밀부사 원개(元顗)의 딸과 혼인을 주선하고, 본관을 원주(原州)로 바꾸게 하였는데, 이 일을 계기로 ○○○은 원주변씨의 시조가 되었다. ‘○○○ 묘’는 양주(楊州) 주엽산(注葉山)에 있었는데 인근에 조선 세조(世祖) 광릉(光陵)이 조영되면서 현재 위치인 풍양(豊壤) 오리동(吾利洞)으로 옮겼다. 이후 ○○○ 묘소가 실전되었다가 다시 찾은 뒤에 1571년 묘표(墓表)를 건립했다.","a":"대은변안렬묘역","c":"문화유산자료","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660242.jpg"},{"q":"임진왜란 때 나라를 위해 싸우다 죽은 제말(諸沫)과 그의 조카인 제홍록(諸弘錄)의 공적을 기리기 위해 세운 비이다. 임진왜란이 일어나자 당시 성주목사로 있던 제말은 의병을 모아 왜군에 맞서 싸우다 제홍록과 함께 전사하였다. 선조는 그의 공을 치하하여 병조판서로 벼슬을 높이고 이 비를 세우도록 하였다. 비의 형태는 네모난 바닥돌 위에 비몸을 세우고 용을 조각한 머릿돌을 얹은 모습이다. 정조 16년(1792)에 세운 것으로, 비문은 서유린이 글을 짓고 이병모가 글씨를 썼으며, 조윤정이 비의 제목을 새겼다.","a":"쌍충사적비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640354.jpg"},{"q":"탑선 마을에 자리하고 있는 3층 석탑으로, 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올려 놓은 모습이다. 기단은 직육면체의 돌을 2단으로 짜 놓은 후 그 위로 판돌을 얹어 마무리하였고, 탑신은 각 층의 몸돌과 지붕돌을 각각 다른 돌로 새겨 차례대로 올려 놓았다. 탑신의 각 층 몸돌에는 모서리마다 기둥 모양을 새겨 놓았는데, 현재 1층 몸돌은 세로로 기둥 조각의 폭만큼 잘려진 채 옆으로 뉘여 있다. 지붕돌은 네 귀퉁이가 위로 가볍게 들려 있으며, 밑면에는 3단씩의 받침을 두었다.","a":"탑선리석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661444.jpg"},{"q":"○○○○는 사찰 입구에 설치하는 것으로, 절에 행사나 의식이 있을 때는 이곳에 당이라는 깃발을 달아두는데, 이 깃발을 걸어두는 길쭉한 장대를 당간이라 하며, 당간의 양쪽에 서서 이를 지탱해주는 두 돌기둥을 ○○○○라 한다. 드물게 당간이 있으나 대부분 두 기둥만 남아 있다. 이 ○○○○는 ○○○ 천왕문 동쪽에 남아 있는 것으로, 두 개의 길다란 돌기둥이 서로 마주보고 있다. 기둥 끝은 안쪽면에서 바깥쪽으로 둥글게 다듬었고, 앞뒷면의 가장자리에는 테두리 선을 돌렸으며, 양 옆면 가운데에는 세로로 돌출된 띠를 새겼다.","a":"무량사당간지주","c":"시도유형문화유산","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639099.jpg"},{"q":"1905년 을사조약 강제 체결에 항거하여 자결한 ○○○ 선생의 묘이다. 일본이 을사조약을 체결하여 외교권을 박탈하자 의정대신 조병세 등과 함께 조약에 찬동한 5적(五賊)의 처형과 조약의 파기를 요구하였으나 뜻을 이루지 못하였다. 이에 죽음으로 항거하기 위해 국민과 각국 공사 그리고 황제에게 고하는 유서를 남기고 자택에서 자결하였다. 묘역은 원래 용인 수지면 풍덕천리에 조성되었다가 1942년 현재의 위치로 이장한 것이고, 그때 부인과 합장하면서 하나의 봉분으로 조성하였다.","a":"민영환선생묘","c":"시도기념물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645959.jpg"},{"q":"○○○는 옛 선현의 자취를 살피어 후세에 전하고 그를 기리고자 세워두는 것으로, 이 비는 임진왜란 때의 의병장인 ○○○의 공적을 기리고 있다. ○○○는 호가 ○○○이며 선조 18년(1585) 34세의 나이에 별시에 뽑혔으나 지은 글이 왕의 뜻에 거슬린다 하여 무효가 되자, 일찌감치 과거에 나갈 뜻을 포기하였다. 그러던 중 임진왜란이 일어나 관군이 크게 패하자 의령 등지에서 의병을 일으켜 관군을 대신하여 적과 싸웠다. 그 공으로 유곡찰방에 임명된 후 여러 관직을 거쳤으나 곧 벼슬을 버리고 현풍으로 돌아갔다.","a":"창녕 망우당 곽재우 유허비","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663830.jpg"},{"q":"와룡산 중턱에 있는 ○○○는 통일신라 문무왕 16년(676)에 의상대사가 처음 지었다고 전한다. 그 뒤의 역사는 전하지 않지만, 임진왜란(1592) 때 사명대사가 승병을 이끌고 이곳에서 왜적과 싸웠다고 하며, ○○○은 이 때 불타없어졌다. 그 뒤 영조 7년(1731)에 다시 지어져 오늘에 이르고 있다. ○○○○○은 앞면 5칸·옆면 3칸의 규모이며, 지붕 옆면이 사람 인(人)자 모양인 단순한 맞배지붕집이다. 지붕을 받치면서 장식을 하는 공포가 복잡한 다포식으로 기둥 위와 기둥 사이에도 포가 배치되어 있다.","a":"고성 운흥사 대웅전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641520.jpg"},{"q":"○○○에 보존되어 있는 ○○○인데, ○○○라 함은 사람이 죽어서 3일 만에 만나서 심판을 받게 된다는 지옥의 왕과 그의 권속들을 그림으로 표현한 것을 말한다. 이 ○○○는 비단 바탕에 채색하여 그려진 것으로, 화면은 3폭 산수화 병풍을 배경으로 중앙에 현왕 1구가 책상을 앞에 두고 양손에 홀을 쥔채 정면을 향하여 의자에 앉아 있고, 그 좌우에 재관집홀상(載官執笏狀)의 녹사 6명이 현왕을 향해 각각 배치되어 있다. 현왕의 앞에 놓여진 책상은 황색 바탕에 나무결 무늬가 표현되어 있고, 그 위에 네권의 경책·붓·연적 등이 가지런히 놓여 있다.","a":"마하사 현왕도","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636697.jpg"},{"q":"우효중의 효행과 우명식의 충성심을 기리며, 광리에 거주하는 단양 우씨들의 교육을 위해 세운 건물이다. ○○○이라는 이름은 우명식 선생의 묘소가 있는 ‘백밭골을 우러러보는 집’이라는 뜻에서 붙인 이름이다. 고종 33년(1896)에 지었고 1924년 새롭게 고친 적이 있다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이고, 집 가운데는 대청마루가 있는데 양쪽 툇마루보다 높게 놓여 있는 것이 특징이다. 툇마루에는 난간을 아담하게 둘러 놓았다.","a":"첨백당","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659470.jpg"},{"q":"○○○란 옛 선현의 자취가 있는 곳을 후세에 알리고 이를 계기로 그를 추모하고자 세워두는 비로, 이 비는 조선 중기 때의 유학자인 표은 김시온(1598∼1669) 선생의 행적을 적고 있다. 선생은 어려서부터 재주가 뛰어났으나 벼슬에는 큰 뜻을 두지 않았으며, 병자호란이 일어나자 이를 슬퍼하며 더욱 학문에만 힘썼다. 도연(陶淵)에 머물며 일체 출입을 삼가하던 그는 조정에서 그에게 관직을 내려주어도 끝내 응하지 않고 스스로 ‘○○○○’라 칭하여 제자양성에만 힘을 기울였다.","a":"숭정처사유허비","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662466.jpg"},{"q":"○○○○○는 금어 금곡당 영환(金魚 金谷堂 永煥)을 비롯하여 응륜(應崙), 응훈 (應訓)이 조성하였으며, 1902년에 ○○○ 가사도를 그린 명응 윤감(明應 允鑑)이 시주로 참여하기도 하였다. 상단에는 범천과 위태천, 하단에는 위태천을 중심으로 묘사하는 형식은 ○○○ 형식 중 가장 애용되었던 것으로 현존하는 ○○○ 가운데 가장 많은 수를 차지하고 있는데, ○○○○○에서 보듯이 뒤에 배경으로 병풍을 두르고 범천과 제석천이 직사각형에 가까운 신광을 두른 도상은 특히 19세기 후반 서울, 경기 지역의 ○○○에 나타나는 특징 가운데 하나로, 봉은사 ○○○, 사자암 ○○○에서도…","a":"청룡사 신중도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018110815571400.JPG"},{"q":"인천광역시 중구 용동 능인교당에 봉안된 일제 강점기 ○○○로 2009년 3월 2일에 인천광역시 유형문화유산으로 지정되었다. 세로 108.5㎝, 가로 110㎝의 크기의 비단 바탕에 채색으로 불보살을 외호하는 신중들의 모임을 그린것으로, 그림 아래 붉은 칸을 마련하고 먹으로 그림에 대한 기록을 적었다.","a":"능인사 신중도","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2017121115080600.jpg"},{"q":"○○○이 생긴 지 100년에 가깝다는 사실만으로도 충분히 기념적 가치 이상의 역사성을 내포하고 있으며, 건축물의 내·외부가 거의 온전히 보존되어 있고, 건축 외관의 형태를 배모양으로 고안하기 위해 수평적 가로줄을 많이 강조했기 때문에 르네상스적 기풍이 보이고 있다. 건물 전체를 콘크리트 거푸집으로 시공한 흔적이 보이며, 전면의 타일은 뒤에 다시 시공한 것으로 짐작된다. 특히 내부 수직창의 기술적 여닫이 처리와 천장 몰딩 문양의 거푸집처리는 이 건물의 돋보이는 특징으로 문화유산으로서의 가치가 있는 건물이다.","a":"부산지방기상청","c":"시도기념물","nc":"","r":"부산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645226.jpg"},{"q":"○○○○는 우리나라를 비롯하여 일본, 대만, 중국 등의 따뜻한 지방에 분포하고 있다. 가지가 사방으로 퍼져 자라서 둥근 형태로 보이며, 꽃은 5월에 피고 열매는 원반모양으로 10월에 익는다. 줄기가 굵고 수명이 길어서 쉼터역할을 하는 정자나무로 이용되거나 마을을 보호하고 지켜주는 당산나무로 보호를 받아왔다. 마을 남쪽의 왕대나무숲 한쪽에서 자라고 있는 담양 ○○○의 ○○○○는 나이가 500년 정도로 추정된다. 높이 35m, 둘레 7.89m의 크기로 건강하게 잘 자라고 있다.","a":"담양경상리느티나무","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654300.jpg"},{"q":"임진왜란 때의 의병장인 ○○○ 장군의 묘이다. ○○○은 임진왜란이 일어나자 고향인 안성에서 외삼촌 홍자수와 함께 의병을 일으켜 북진하는 왜적을 수차례 격퇴하였다. 그 뒤 용인·죽산·양지에 진을 구축하는 동시에 서운산성에 토성을 쌓아 경기·충청 지방의 의병들과 합세하여 왜적을 무찌르다 전사하였다. 1718년(숙종 44)에는 묘소에서 1㎞ 떨어진 장군의 생가에 정문(旌門; 충신, 효자, 열녀 등을 표창하고자 그 집 앞에 세우던 붉은 문)이 세워지고 병조참의의 벼슬이 내려졌다. 묘역은 부인과 함께 매장된 쌍분(雙墳 ; 두개의 봉분)의 형태이다.","a":"이덕남장군묘","c":"시도기념물","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645978.jpg"},{"q":"조선 영조 때 사간원 사간, 사헌부 집의 등을 지낸 이석구 선생이 지은 집이다. ○○○이라 한 것은 홍문관 교리를 역임했기 때문이라 한다. 서향의 대문채를 들어서면 곧바로 사랑마당이 있고, 사랑 왼쪽에 서재가 있으며 뒤쪽에 사당이 있다. 안채는 중문채를 사이에 두고 사랑채와 떨어져 있다. 안채는 앞면 7칸·옆면 1칸 집으로 중앙에 2칸의 대청이 있고 대청 양쪽에 방이 2칸씩 있으며, 동쪽에 부엌이 배치되어 있다. 사랑채는 앞면 5칸·옆면 2칸 집으로 왼쪽 대청 2칸은 문을 달아서 자유롭게 열고 닫을 수 있게 하였다.","a":"대산동교리댁","c":"시도민속문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658612.jpg"},{"q":"1868년(고종 5)에 제작되어 연대는 오래되지 않았지만 필선과 구도, 본존과 보살상의 얼굴모습, 산처럼 높이 솟아 있는 육계와 계주의 표현, 전체의 색조가 붉은 색과 파란색이 주조를 이루고 있는 점 등 19세기 중엽 이후 불화의 전형적인 특징을 모두 갖추고 있으며, 보존상태가 매우 양호한 작품으로 그 보존가치가 크다. 이 탱화는 영월군 영월읍 영흥리 ○○○의 ○○○에 봉안되어 있던 것인데, 1998년 9월 2일 월정사 성보박물관으로 옮겨져 전시중에 있다.","a":"보덕사사성전후불탱화및복장유물","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638252.jpg"},{"q":"○○○은 조선 중기의 문신이다. 관향은 창녕(昌寧)이며 자는 선백(善伯), 호는 도촌(陶村)이다. 내암 정인홍의 문하에 입문하여 수학하였으며 임란에 창의하였다. 선조 32년(1599)에 상의원 별제에 임명되었으나 부임하지 않다가 선조 40년(1607) 왕자사부(王子師傅)에 임명되기도 하였다. 그 뒤 공조좌랑, 온양군수 등을 역임하였다. 이 논서는 ○○○이 온양군수로 재직할 당시 관찰사 이춘원의 보고에 의하여 광해군이 내린 것이다. 논서는 한지로 현재 상태는 양호한 편이다.","a":"도촌조응인선생유서","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664527.jpg"},{"q":"이 불상은 하나의 떼어진 장판돌에 불상의 머리와 몸을 양각하고 장판돌은 광배의 역할을 하고 있다. 그러나 광배는 워낙 결실이 심하고 닳아 없어진 부분이 많아서 세부적인 파악이 어려우나 거신광배로 추정되며, 광배의 내부에는 화염문과 같은 내부 장식이 없는 것으로 보인다. 석불의 전체 높이 142cm, 너비 52cm이다. 전체적으로 고려시대 지방 불교, 민간신앙적인 영향 하에서 조성된 불상의 특성이 잘 나타나 있다.","a":"삼척임원리석불입상","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660661.jpg"},{"q":"임진왜란 때 의병장으로 활약한 김천일 선생의 충절을 기리기 위해 세운 비이다. 김천일(1537∼1593)은 이항 선생 아래에서 학문을 배웠으며, 22세 때 학문이 뛰어나 벼슬길에 오른 후 여러 관직을 두루 거쳤다. 임진왜란 때 나주에 있다가 고경명, 박광옥, 최경희 등과 함께 의병을 일으켰고, 왜적이 남쪽으로 물러나기 시작하자 적을 따라가 진주성에서 치열한 싸움을 벌였으나 성이 함락당하여 아들 상건과 함께 스스로 목숨을 끊었다. 비는 거북받침돌 위에 비몸을 세우고 네모난 형태의 머릿돌을 올린 모습이다.","a":"정열사비","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654115.jpg"},{"q":"○○○○○은 구석기시대의 동굴유적으로 우리나라에서는 매우 드물게 동굴의 외형과 내부가 거의 완전하게 보존되어 있는 유적이다. 1986년부터 3차례에 걸쳐 이루어진 발굴조사에 의해 전체 8개층으로 구성된 구석기시대의 유적임이 확인되었다. 특히 제3층에서는 많은 유물과 짐승화석이 집중적으로 발견되어 이곳이 주된 문화층이었음을 알 수 있다. 동굴의 입구는 남동 방향으로 되어있고 규모는 입구 너비 5.5m, 전체 길이 140m로 규모가 큰 편이다.","a":"단양 구낭굴 유적","c":"시도기념물","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650441.jpg"},{"q":"○○○○○은 선교사로 광주에서 활동하다 순교한 오웬과 그 할아버지를 기념하기 위해 세워졌다. 2층의 회색 벽돌건물로 평면은 정방형이지만 모서리에 있는 설교단을 중심으로 좌우가 대칭되는 구조이다. 이 건물의 특징은 객석에서 설교단을 내려다 볼 수 있도록 1층 바닥과 2층 발코니를 모서리의 설교단을 향해 약간 경사지게 한 것이다.","a":"오웬기념각","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637168.jpg"},{"q":"이 石造觀音菩薩坐像은 통도사 ○○○○○ 3층 極樂寶殿의 향우측 佛壇에 봉안되어 있는데, 結跏趺坐한 모습의 이 보살상은 일명 沸石으로도 불리는 석재로 조각하여 도금된 상태이다. 전체적으로 얼굴에 비해 寶冠이 높은 편이며 또한 결가부좌한 하부는 몸체에 비해 빈약하다. 보살상의 地髮은 검은 안료로 채색하고 눈썹과 입술은 녹색과 적색 안료로 채색되어 있으며 눈은 點眼되어 있는 상태이다. 하부에 개금이 벗겨져 붉은 옻칠 흔적이 드러나 있으나 전체적으로는 보존상태가 양호하며, 대좌는 후대에 銅으로 별조한 것인데 伏·仰 연화대좌이다.","a":"양산 포교당 석조관음보살좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643102.jpg"},{"q":"○○○은 강태형(姜泰馨, 1843년~1911년), 강내형(姜乃馨, 1853년~ 1919년), 강재형(姜載馨, 1863년~1897년) 삼형제의 지극한 효성을 향리와 유림들이 여러 차례에 걸쳐 널리 알려 삼형제 모두가 조정으로부터 정려를 받은 사실을 기리기 위해 1916년에 건립되었으며 당호를 ○○○이라 했다. 삼형제는 양친을 섬김에 있어 살아생전 혼정신성(昏定晨省)을 다하였는데 부친이 종기병을 앓자 이를 빨아서 낫게 하였다고 하는 일화도 전해지고 있다.","a":"창원 삼효각","c":"문화유산자료","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666728.jpg"},{"q":"○○읍 평곡리 탑정이라는 옛 절터에 있던 탑으로, 1934년 경호정(옛 연풍정) 앞으로 옮겨 세웠다. 형태는 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 기단의 네 모서리와 탑신부의 각 몸돌에는 기둥 모양을 조각하였다. 지붕돌은 밑면에 3단의 받침을 두었고, 네 귀퉁이에서 살짝 들려있다. 꼭대기에는 연꽃 봉우리 모양의 머리장식을 얹어 놓았다. 전체적으로 통일신라 전성기의 석탑 양식에 비교할 때, 기단이 2층에서 1층으로 줄어들고, 기단의 가운데기둥 조각이 생략되었으며, 지붕돌 받침은 3단의 줄어 들었다.","a":"음성 읍내리 삼층석탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638592.jpg"},{"q":"이 서원은 조선시대 학자였던 윤황(尹惶)의 위패를 모시고 제사지내는 곳이다. 윤황은 병자호란 때 끝까지 싸울 것을 주장하는 상소를 올린 강직한 신하로 유명하다. 윤황은 글씨에 능해 당대의 명필로 이름을 드높였으며, 인조 때에는 전주부윤이라는 벼슬을 맡기도 했다. ○○○○은 윤황의 위패를 가운데 모시고, 조선시대 학자인 이영선(李榮先)과 서필원(徐必遠)을 함께 모셨다. 이 서원은 고종 5년(1868)의 서원철폐령에 따라 헐렸다가, 고종 15년(1878)에 다시 지어졌다.","a":"반곡서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661622.jpg"},{"q":"◦ 조선시대 보령읍성의 남문(南門)임. 장초석(長礎石) 위에 기둥을 한 정면 3칸 측면 2칸의 2층 누각 건물이며, 조선왕조의 중앙집권을 상징하기 위해 당시 전국에 똑같이 만들어진 관아문 양식을 충실히 따르고 있으며, 정면에는 해산루(海山樓)라는 현판이 걸려있는데 조선 선조 때 영의정을 지낸 이산해(李山海)의 친필로 전해옴. ◦ 보령현(保寧縣)은 고려초부터 붙여진 이름이며 1413년(태종13)부터 현감이 파견되었고, 1652년(효종3)에는 보령부(保寧府)로 승격되기도 했으나 다시(1655) 보령현으로 강등되었음.","a":"보령관아문","c":"시도유형문화유산","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639063.jpg"},{"q":"만든 때와 만든 이를 알 수 있는 조선 후기 보살상이다. 보살상 속에서는 후령통(候鈴筒; 여러 종류의 복장물을 넣은 원통형 용기로 부처의 목소리를 상징)과 발원문(發願文; 바라고 원하는 것을 적은 글) 두 장이 발견되었다. 발원문에는 1755년 4월에 용화암이라는 절에 모시기 위해 ○○○○상을 만들었다는 사실과 함께 당시 불상 제작에 참여했던 조각승의 이름이 등장한다. 불상 조성을 총 지휘한 금어(金魚)는 상정(尙淨) 스님이며, 불상을 색칠한 화사(畵師)는 색민(色旻) 스님이다.","a":"부천석왕사목조관음보살좌상","c":"시도유형문화유산","nc":"","r":"경기도","s":"부천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637766.jpg"},{"q":"이 유물은 ○○○ 중창공사의 진행 중에 발굴된 사지(寺址)에 남아 있던 여러 종류의 불교유물들로서, 석조불상대좌(石造佛像臺座)·신방석(信枋石)·석탑기단갑석(石塔基壇甲石) 등이다. ○○○○은 대부분 화강암으로 되어 있고 석조비로자나불좌상이 높이 47㎝·어깨폭 40.5㎝·최대폭 43.5㎝, 불상광배가 136.5×110㎝, 석조불상대좌가 73.2×17.4㎝, 석탑기단갑석이 101.8×102.2㎝, 신방석이 지름 74㎝·높이 16.8㎝의 규모로 되어 있다.","a":"성주 심원사 석조유물","c":"문화유산자료","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018103020193600.jpg"},{"q":"영양 남씨 집성촌인 호지마을에 있는 가옥으로 조선 영조 52년(1776)에 남준형 선생이 세웠다고 전한다. 신해(辛亥)에 중수되었다는 기록이 남아 있지만 정확한 연대를 추정하기는 어렵다. 앞면 4칸·옆면 6칸 반 규모의 건물이다.","a":"영덕 괴시동 대남댁","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658965.jpg"},{"q":"전북특별자치도 김제시 금구면 선암리와 월전리의 경계를 이루는 봉두산 봉우리를 둘러싼 테뫼식 산성으로, 전체 둘레는 900m가량이다. 산의 서북쪽 급경사 지역은 석재 채취로 인해 원형에 손상이 있으나, 동남쪽은 원형이 잘 보존되어 있고 석축도 잘 남아있다. 성벽은 높이가 2m 내외로 자연 경사면을 이용했으며, 동쪽에는 자연석을 이용하여 쌓은 성벽 100m 정도가 남아있다. 이곳에서는 통일신라시대의 토기조각과 조선시대의 기와조각이 골고루 출토되고 있으나, 성이 언제 쌓였는지는 알 수 없다.","a":"금구산성","c":"시도기념물","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653626.jpg"},{"q":"○○○는 조선 고종 때 병인양요와 신미양요를 승리로 이끈 흥선대원군이 백성들에게 서양 오랑캐에 대한 경계심을 드높이고자 전국 곳곳에 세운 비이다. 이 비는 원래 부산진의 성지에 세웠던 것이지만, 용두산 공원에 옮겼다가, 1978년 지금 자리로 옮긴 것이다. 네모난 받침돌 위에 글을 새긴 비몸을 얹고 지붕돌을 올린 모습으로, 비문의 내용은 ‘서양 오랑캐가 침범할 때에 싸우지 않는 것은 곧 화친을 하자는 것이요, 화친을 하자는 것은 나라를 파는 것이다’라는 강한 어투의 경고문구를 담고 있다.","a":"척화비","c":"시도기념물","nc":"","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645018.jpg"},{"q":"내포 교회의 초기 공소가 있었던 곳으로, 병인박해 때 ○○○ 주교, 오메트르 신부, 위앵 신부, 황석두 등이 체포되어 순교한 곳으로 손자손을 비롯한 천주교의 성인 5명이 관련된 유적이다. ○○○ 주교는 제5대 조선교구장으로 신리공소는 실질적인 조선교구청이었던 셈이다. 공소 건물은 원래 손자손의 생가로 보수공사 때 확인된 건축연대는 1815년인데, 1964년 새롭게 복원되었다. 병인박해 때 순교한 32인의 순교자가 안장되어 있다. 최근 천주교단의 정비사업이 활발하게 진행되면서 순례관광의 명소가 되었다.","a":"당진신리다블뤼주교유적지","c":"시도기념물","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653219.jpg"},{"q":"○○○ 나한전 앞에 자리하고 있는 탑으로, 1층 기단(基壇) 위에 9층의 탑신(塔身)을 올린 모습이다. 기단은 네 모서리와 가운데에, 탑신은 몸돌의 모서리에 각각 기둥 모양을 본 떠 새겼다. 탑신의 2층 몸돌은 1층에 비해 높이가 급격히 줄어들고 있으며, 4층 부터는 몸돌이 없어진 채 지붕돌만 포개져 있어 옛 탑이 지니고 있었을 아름다움을 많이 잃고 있다. 얇고 넓적한 지붕돌은 밑면에 4단씩의 받침을 두고 있으며, 처마의 선이 양쪽 가에서 부드럽게 위로 들려 우아한 곡선을 이루는데, 위층으로 올라갈수록 파손된 부분들이 눈에 띠어 아쉬움을 준다.","a":"향천사구층석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661174.jpg"},{"q":"전라남도 남원시 이백면 효기리는 통일신라 후기에 도선국사가 ○○○을 창건하였다고 전해지는 곳이다. 현재 이곳에는 1946년에 건립된 연화사가 있다. 이 ○○○○은 둥글 넓적한 얼굴에 코는 납작하게 표현되어 있다. 귀는 긴 편으로 뒤쪽에 치우쳐 붙어 있으며, 긴 목에는 3개의 주름인 삼도(三道)가 뚜렷하다 옷은 양쪽 어깨에 걸쳐져 있고, 양손 부분에는 구멍이 뚫려 있다. 전체적으로 볼 때 어깨에 비하여 몸이 간략하게 처리된 느낌이 든다. 연꽃 무늬가 새겨져 있는 대좌(臺座)는 불상과 분리되어 있다.","a":"미륵암석불입상","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661680.jpg"},{"q":"당나라 현각(玄覺)스님*이 법문을 찬술하고 송나라 행정(行靖)이 주석한 책으로 상하 2권 1책의 목판본이다. 선종의 요결(要訣)로서 우리나라 선림(禪林)에서 많이 이용했던 책이다. 그 내용은 모도지의(慕道志義) ․ 계교사의(戒奢意) ․ 정수삼업(淨脩三業) ․ 사마타송(奢摩他頌) ․ 비바사나(毗婆舍那) ․ 우필차송(優畢叉頌) ․ 삼승점차(三乘漸次) ․ 이사불이(理事不二) ․ 권우인서(勸友人書) ․ 발원문(發願文) 등 모두 10개의 문(門)으로 구성되어 있다.","a":"선종영가집","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638891.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 처음 지은 연대는 전하지 않고 임진왜란 때 불탄 것을 선조 27년(1594)에 다시 지었다. 그 후 여러 차례의 수리가 있었으며, 한국전쟁으로 불탄 것을 1960년에 복원하였다. 지금 남아있는 건물은 대성전과 명륜당·장수루·동재·서재·동무·서무·내삼문 등이다. 대성전은 사당으로 공자를 비롯하여 중국과 우리나라 유학자의 위패를 모시고 있다. 명륜당은 학생들이 모여서 공부하는 강당으로 교화의 원천이 되기도 하였다.","a":"춘천향교","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638102.jpg"},{"q":"일제강점기 때 영양지역에서 막대한 부(富)를 축적하여 자선사업을 크게 베풀었던 대은(大隱) 권영성(權永成, 1881-1959)이 1934년(甲戌年 9월 초파일)에 건립한 정자이다. 권영성은 영양향교, 김천중학교, 대구의학전문학교, 영양초.중.고등학교, 화천초등학교, 대구농림학교 등에 각종 육영사업을 베풀었으며, 수재와 극빈 구제를 위해서는 양곡을 기부하였으므로, 그를 기리는 공덕비들이 곳곳에 세워져 있다.","a":"영양사정","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663499.jpg"},{"q":"○○○ 김열의 별당이다. ○○○은 이율곡(1536∼1584)과 같은 시대의 사람으로 학문과 덕행이 뛰어났다. 평소에 친하게 지내던 율곡은 집 주변에 소나무를 심고 가꾸면서 청빈하게 살아가던 ○○○을 높이 칭송하면서 선물로 호송설(護松說)을 지어 주기도 하였다. 앞면 3칸·옆면 2칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 화려한 팔작지붕집이다. 소나무 숲을 배경으로 하여 2단의 장대석 위에 지어진 집으로, 별당 이름은 김열의 호를 따서 지은 것이다. ○○○의 뒷쪽에 위치한 ㅁ자형 집은 본채로서 ○○○과 함께 수 차례의 수리를 거쳐 오늘날에 이르고 있다.","a":"임경당","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637972.jpg"},{"q":"○○읍에서 북쪽으로 약 1㎞ 떨어진 국도변 민가 안마당에 서 있는 석탑으로, 전해지는 기록이 없어 탑이 속해 있던 사찰에 대해서는 알 수 없다. 기단부(基壇部)는 땅속에 묻혀있어 구조를 알 수 없고, 그 위로 5층의 탑신(塔身)이 쌓여 있다. 탑신의 몸돌에는 모서리마다 기둥 모양의 조각을 두었다. 지붕돌은 낙수면의 경사가 급하고 처마는 수평을 이루다가 네 귀퉁이에서 바짝 치켜올라 갔으며, 밑면에 1·2·3층은 4단, 4·5층은 3단의 받침을 두었다. 꼭대기에는 노반(露盤:머리장식 받침)과 보주(寶珠:연꽃 봉오리 모양의 장식)가 남아 머리장식을 하고 있다.","a":"장성 수산리 오층석탑","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2022101211421300.jpg"},{"q":"○○○에 소장되어 있는 ○○○○ 좌상으로 높이 39㎝, 어깨폭 13㎝, 무릎폭 21.7㎝이다. 조선후기 18세기 이후에 조성된 ○○○로서 윤왕좌의 자세에 머리에서부터 백의 같은 천을 덮어 쓴 형식의 백의관음으로서 그 예가 매우 드문 작품이며 양식적으로 특이성을 지니고 있어 불교미술사적인 측면에서 중요한 가치가 있다.","a":"수덕사소장소조불상좌상","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661561.jpg"},{"q":"조선 후기에 지은 이 지방 부농의 집으로 고봉산 지맥이 지네와 같은 형상을 이루는 지형의 가장 중요한 곳에 자리잡고 있다. 안채는 철종 11년(1860)에 지었고 사당은 1901년에 지었다. 원래는 건물이 여러 채 있었으나 현재는 안채, 사랑채, 사당만이 남아있다. 비탈진 지형때문에 기단을 이중으로 쌓았으며, 북쪽 전면에 대문간, ㄷ자형의 사랑채가 있고 그 뒤에 一자형 안채가 있다. 건물 규모가 커지고 툇마루가 각 방을 연결하면서 길게 이어지는 등 조선 후기 주택의 특징을 잘 보여 주는 가옥이다.","a":"채원병가옥","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658313.jpg"},{"q":"정려란 나라에서 충신·효자·열녀를 칭찬하기 위해 그들이 살던 고을 입구에 세우던 비석 또는 문을 가리킨다 이것은 들을 위해 세운 것이다. 이 각은 선조 30년(1597) 정유재란 때 영광군에 피신해 있다가 왜군의 추적을 받자 칠산 앞바다에 뛰어들어 정절을 지킨, 동래 정씨와 진주 정씨 문중의 아홉 부인을 기리기 위해 숙종 7년(1681)에 세웠다. 처음에는 8분을 모신 정려를 함평에 세우고 정등의 부인인 밀양 박씨는 따로 그녀의 고향인 영광군에 세웠으나 한국전쟁으로 모두 소실되어 그 후손들이 1960년 지금 있는 자리에 다시 세웠다","a":"영광정렬각","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654013.jpg"},{"q":"이 ○○○은 15세기 초반~19세기 초반에 걸쳐 ○○○ 및 ○○○의 고승들을 모신 묘원(墓園)의 성격을 띠고 있다. 경북 동해안 지역에서 이와 같이 10기(基)가 넘는 부도가 한 장소에 보존되어 있는 경우는 없을 뿐 아니라 완형(完型)이고, 양식적으로 볼 때 영남지역의 부도양식을 대변하고 있는 것으로 파악된다.","a":"포항 보경사 서운암 부도군","c":"시도유형문화유산","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641326.jpg"},{"q":"이치는 완주와 금산의 경계를 이루는 고개로, 선조 25년(1592) 임진왜란 때 광주목사 권율(權慄)과 동복현감 황진(黃進)이 관군 1,500명과 함께 적장 고바야카와가 이끄는 부대를 격퇴함으로써 임진왜란의 첫 승리를 장식한 전적지이다. 이치전투는 이순신의 한산도대첩, 권율의 행주대첩과 함께 임진왜란의 3대 대첩으로 손꼽히고 있다.","a":"이치전적지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653390.jpg"},{"q":"○○○는 ○○목 관아의 부속 누정으로 원래 이름은 취경루 이다. 고려 공민왕 10년(1361)에 홍건적의 침입을 물리치고 개경으로 돌아오는 길에 기념으로 ○○에서 과거시험을 치르고 이곳에 방을 써붙였다는 기록이 있다. 세조 7년(1461)에 수리하였고 한명회가 현판을 ‘○○○’라 하였다고 한다. 일제강점기 일제의 무덕전(일본 헌병대 유도연습장) 신축으로 철거될 위기에 놓였으나, 김태희의 주선으로 1923년에 제일교회로 이건되었으며, 2000년 12월 중앙공원으로 옮겨 세웠다. 앞면 5칸·옆면 3칸이며, 나무로 지은 2층 건물이다.","a":"청주 망선루","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638567.jpg"},{"q":"\"무등산 서쪽 기슭에 있는 절로, 기록에 따르면 철감선사 도윤(798∼868)이 신라 헌안왕 4년(860)에 지었다고 한다. 한국전쟁으로 대부분의 건물이 불타버려 1970년 대웅전을 시작으로 각종 부속 건물들을 차례로 복원하여 오늘에 이르고 있다. 현존하는 건물로는 대웅전, 오백전, 지장전, 비로전을 비롯하여 스님들이 기거하는 요사채가 있다. 이 중 오백전을 제외한 나머지 건물들은 역사가 그리 오래되지 않았다. 오백전은 대웅전 뒤에 있는 건물로 앞면 3칸·옆면 1칸 규모이다.","a":"증심사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659593.jpg"},{"q":"임진왜란 때 의병장으로 활약한 최경회(1532∼1593)와 문홍헌, 을묘왜변 때 순국한 조현 등 3분의 충신을 추모하기 위해 세운 누각이다. 최경회는 선조 원년(1567)에 문과에 급제하고 영해군수를 지냈는데, 상(喪)을 당해 고향인 전라남도 화순에 내려와 있을 때 임진왜란이 일어났다. 그는 형들과 고을 사람들을 규합하여 의병을 모집하였고, 탁월한 용병술과 용장으로 진주 1차 싸움을 승리로 이끌었으며 공로가 인정되어 경상우병사로 임명되었다.","a":"화순능주삼충각","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654209.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 조선 세종(재위 1418∼1450) 때 처음 세워지고 그 후 여러 차례 다시 짓고 보수하였으며, 지금 남아있는 건물들은 18세기 이후에 지은 것이다. 명륜당은 학생들이 모여서 공부하는 강당으로 고종 8년(1871) 대원군의 서원철폐령으로 문을 닫은 상현서원의 강당을 옮겨지은 것이다. 앞면 5칸·옆면 2칸의 규모이며, 지붕 옆면이 사람 인(人)자 모양인 단순한 맞배지붕집이다. 사당인 대성전에는 공자를 비롯하여 중국과 우리나라 유학자의 위패가 모셔져 있다.","a":"보은향교","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638535.jpg"},{"q":"○○○○○은 고려 공민왕(재위 1351∼1374) 때 병부상서를 지낸 전신민이 고려가 망하자 두 임금을 섬길 수 없다며 은거하면서 지었다는 독수정이라는 정자 주위의 숲을 가리킨다. 독수정이란 이름은 이태백의 시에서 따온 것으로 은거하며 생활하는 선비의 고결한 뜻을 나타낸 것이다. 이곳에는 느티나무, 회화나무, 왕버들, 소나무, 참나무, 서어나무 등의 오래 된 나무들이 심어져 있고, 독수정 앞뜰에는 자미나무, 매화나무, 살구나무, 산수유나무 등이 심어져 있어 속세를 떠난 느낌을 준다. 전해 내려오는 말에 의하면 전신민은 대나무와 소나무를 심어 수절을 다짐했다고 한다.","a":"독수정원림","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654160.jpg"},{"q":"되재성당은 1895년 한국 천주교회에서 서울 약현성당에 이어 두 번째로 완공된 성당으로 한강 이남에서는 처음 세워진 성당이며, 최초의 한옥성당으로 추정하고 있다. 그러나 한국전쟁 때 성당건물이 전소되었고 그 자리에는 1954년에 다시 세운 공소건물이 자리하고 있다. 이 성당은 서양의 바실리카식 교회건축양식을 한식 목구조로 번안한 한옥성당으로서 새로운 문화의 토착화 과정을 보여주는 최초의 한옥성당으로 추정하고 있다.","a":"되재성당지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653828.jpg"},{"q":"○○○○○은 가야산의 정상인 칠불봉(해발 1433m)의 동남쪽에 위치하며, 용기골의 좌·우로 상아덤과 재골산의 능선을 따라 축성된 포곡식(包谷式) 산성이다. 처음 축성한 연대에 대해서는 확실하지 않으나,『세종실록지리지』,『신증동국여지승람』등의 문헌자료에 기록이 남아 있다. 대가야의 이궁(離宮)으로 추정되고 있는 곳이다. 임진왜란시 체찰사(體察使) 이원익(李元翼)이 조정의 명을 받아 승장(僧將) 신열(信悅)을 시켜 개축하였으며, 난중에는 인근 백성들의 피난처로 이용되었던 곳으로 전하고 있다.","a":"가야산산성","c":"시도기념물","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654656.jpg"},{"q":"○○○는 신라 진평왕 25년(603)에 진나라에서 유학하고 돌아온 대덕 지명법사가 세운 절이다. 이 절의 중심 건물인 ○○○은 지은 시기를 알 수 없고 다만 조선 숙종 3년(1677)에 중건한 것으로 그 후 몇 차례 중수가 더 있었다. 현재의 건물에는 1932년의 대대적인 중수에 의한 양식적 특징이 주로 남아 있다. 이 건물은 조선후기 목조불전으로 정면 3칸·측면 2칸의 다포계 팔작지붕이며, 바닥에는 마루를 깔았다. 천장은 우물 정(井)자 모양으로 꾸며 천장 속을 가리고 있는 형태이다. 가운데칸 뒷부분에는 불단을 마련하여 삼존불상을 모셔 놓았다.","a":"포항 보경사 대웅전","c":"시도유형문화유산","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641271.jpg"},{"q":"묵헌 이만운이 죽은 뒤 유림의 뜻에 따라 조선 순조 20년(1820)에 세운 건물이다. 묵헌 이만운(1736∼1820)은 퇴계, 한강, 문익공을 잇는 정통 성리학자로 우리 국학 연구에 귀중한 자료가 되는 『증보동국문헌비고』를 편찬하였다. 원래 이 집은 대문채와 방앗간채도 있었으나 지금은 사랑채와 정침, 사당이 남아 있다. 정침과 사랑채는 문익공 이원정의 아들인 이한명(1651∼1681)이 조선 현종11년(1670)에 세웠고, 사당은 순조 20년(1820)에 유림에서 세웠다.","a":"묵헌종택","c":"문화유산자료","nc":"","r":"경상북도","s":"칠곡군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662945.jpg"},{"q":"부도는 승탑 또는 사리탑으로 불리는데, 스님의 유골이나 사리를 모셔 놓은 일종의 무덤이다. ○○○는 금강산의 네 개의 큰 사찰중의 하나인 유점사(楡岾寺)에 속한 사찰로 석대암(石臺庵), 성주암(聖住庵), 지장암(地藏庵), 남암(南庵) 등 4개 암자를 관할했던 큰절이었다. 『신증동국여지승람(新增東國輿地勝覽)』에 따르면 보개산(寶蓋山)에 있으며 흥림사(興林寺)라고 했다는 기록이 전한다.","a":"연천군심원사지부도군","c":"시도유형문화유산","nc":"","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637626.jpg"},{"q":"조선 전기의 학자인 격재 ○○○ 선생의 문집을 새긴 ○○이다. ○○○는 집현전학자, 병조정랑, 봉산군수를 역임하였던 학자로서, 단종의 왕위를 찬탈한 세조의 행위에 분개하여 모든 벼슬을 버리고 고향으로 돌아와 충의와 정절로서 두문분출하며 오직 도학에만 전념하였다. 대구 청호서원에서 제사를 지내고 있다.","a":"손조서 격재문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642189.jpg"},{"q":"장승은 마을입구나 길가에 세워 그 마을의 수문신·수호신 등의 구실을 하는 민간신앙의 한 형태이다. ○○○ 당산거리에 자리하고 있는 이 2기의 장승은 당산나무 밑의 할아버지와 할머니로 불리는데, 3m 거리를 두고 각각 북쪽과 남쪽으로 등을 돌린 채 서 있다. 북쪽을 바라보는 할아버지 장생은 대강 다듬은 자연석을 사용하였으며 전체적으로 우직한 인상을 풍기고 있다. 동그란 안경을 쓴 듯한 눈, 동그란 코, 초승달 같은 입술, 턱 아래 두줄의 수염 등 소박한 시골 할아버지의 얼굴 모습이다. 앞면에는 ‘동방대장’이라는 글씨를 새겨 넣었다.","a":"영광도동리석장승","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662203.jpg"},{"q":"신라시대 만고 충신 ○○○의 생가로 구성되고 있으며, 사당 안에는 ○○○공과 그의 아들 백결선생의 초상화가 모셔져 있다. 사당 앞에는 ○○○의 업적을 적은 ○○○ 석비가 세워져 있다. ○○○의 호는 관설당(觀雪堂)이며 신라 시조 박혁거세의 후손으로 눌지왕 2년(418)에 고구려에 들어가 볼모로 잡혀 있던 왕제(王弟) 복호(卜好)를 데려오고, 다시 일본으로 건너가 역시 볼모로 잡혀 있던 왕제(王弟) 미사흔(味斯欣)을 계교로 탈출시키고 자신은 스스로 잡히는 몸이 되었다.","a":"양산 박제상 유적. 효충사","c":"시도기념물","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655301.jpg"},{"q":"현재 보광사 경내에 건립되어 있다. 석탑의 명칭은 과거의 보광사 주소지가 시흥군 과천면 ○○○였던 데서 명명된 것이다. 이 석탑은 단층 기단과 3층 탑신을 갖추고, 시멘트로 된 1단의 기단 위에 놓여 있다. 기단 하대석에는 각 면 2구씩 장방형의 액(額)을 형성한 후 내부에 안상(眼象)을 조각했다. 기단 중대 각 면에는 양 우주(隅柱)를 모각했다. 중대 면석은 흡사 탑신석과 가깝게 치석(治石)되어, 다른 석탑의 탑신석을 사용했을 가능성도 있다. 갑석(甲石)은 하면에 부연을 생략해 편평하지만, 상면에는 3단의 받침이 있어 초층 탑신을 받치고 있다.","a":"시흥문원리삼층석탑","c":"문화유산자료","nc":"","r":"경기도","s":"과천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659979.jpg"},{"q":"조선시대 곡식을 운반하기 전에 쌓아두던 창고의 하나로 ‘공진창’이 처음 명칭이다. 성종 9년(1478) 『경국대전』에 의하여 모든 제도가 정비되면서 충청도에서 세금으로 거둔 곡식은 모두 이곳으로 모았다가 일정한 시기에 서울의 창고로 운송하도록 하였다. 지금은 창고터 주변에 만든 성지(城地)가 약 680m 정도 남아 있는데, 겨우 터만을 알아 볼 정도이다. 처음에는 창고가 없어 한데 쌓아 두었으나, 중종 18년(1523)에 비로소 창고 80칸을 건축하였다고 한다. 이곳에서 충청도 지방 39개 목·군·현의 조세로 바친 쌀을 모아 두고 배로 수도까지 운반하였다.","a":"아산공세곶고지","c":"시도기념물","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651940.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 처음 지은 연대는 알 수 없고, 조선 선조 8년(1575) 아산리 동쪽 향교골에서 지금 있는 자리로 옮겨 지었고, 고종 1년(1864)에 수리하였다. 지금 남아 있는 건물은 대성전, 명륜당, 내삼문, 외삼문 등이다. 대성전은 제사지내는 공간으로 앞면 3칸·옆면 2칸 규모이다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이고, 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양인 익공 양식으로 꾸몄다.","a":"아산향교","c":"시도기념물","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652898.jpg"},{"q":"삼척 노곡리 마을 옛 국도변에 서 있는 비로, ‘○○○’위에 놓여 있다. 조선 세종 5년(1423) 이곳 일대에는 대흉년이 들어 백성들이 거의 굶주림에 고통받고 있었다. 조정에서는 이들을 구하고자 황희 선생을 강원도 관찰사로 파견하였고, 이곳으로 부임해 온 황희는 정성을 다해 이들을 도와 마침내 어려움에서 벗어나게 되었다. 백성들은 그 은혜를 잊지 않고 당시 황희가 가끔 쉬곤 하던 와현(瓦峴)이라는 고개에 돌을 모아 단을 쌓고 ‘○○○’라 이름하여 그의 공적을 기리고자 하였다.","a":"삼척소공대비","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660534.jpg"},{"q":"신라시대에 축조된 수리시설중 현존하며 관개수리시설로 이용되고 있는 못으로는 우리나라에서 유일한 것으로 법흥왕 23년 이전 476년 또는 536년에 축조된 것으로 추정하고 있으며 청제 축조시 동원된 인원이 7,000명이라는 것으로 보아 국가적인 차원의 사업이었음을 추정할 수 있고, 목책이나 말뚝으로 제방을 견고히 보강하는 기술이 사용되었고 나무 수문이 설치되었다고 하므로 청제의 기능을 추정해 볼 수 있고 그 당시 수리시설의 실태 파악이 가능해지며 농업생산성을 추측하여 볼 수 있는 귀중한 사료임","a":"영천청제","c":"시도기념물","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654666.jpg"},{"q":"○○○은 태안읍성 밖에 지어진 관아 건물로 안흥항에 들어온 중국의 사신이 휴식을 취하거나 방어사가 군사 명령을 내리던 장소이다. ‘경이憬夷’라는 이름은 “오랑캐를 경계하라”라는 뜻으로 고려 말부터 왜구에 의한 피해가 극심했던 태안지역의 상황을 반영하여 지은 것으로 보인다. 이후 왜구의 침략이 점차 줄어들고 ○○○이 중국 사신의 휴식 장소로 이용되면서 “항해하는 사신의 평안을 빈다”라는 뜻으로 의미가 바뀌어 전해진다.","a":"경이정","c":"시도유형문화유산","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639210.jpg"},{"q":"이 범종은 건륭32년명 ○○과 형태가 거의 비슷하지만 주조명이 없다. 그러나 구조적인 양식은 우수하며 중후하다. 조성기법으로 보아 그 연대가 앞설 가능성도 배제할 수 없다. 다만 당좌 위치에 약간의 균열이 있는 상태이다. 쌍룡뉴와 천판은 비슷하며 원권 내에 범문 여덟 자를 배치하고 있다. 동체에는 연곽을 사방에 배치하고 연곽과 연곽 사이에는 역시 사방에 보살상을 표현하여 조화를 이루게 하였다. 또한 하대에는 당초문으로 마감된 조선 후기 범종 연구에 자료적 가치가 있다.","a":"남해 화방사 동종","c":"시도유형문화유산","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020041114153400.jpg"},{"q":"張潭 忠臣閣은 인동장씨 집성촌에 세운 忠臣門으로 李麟佐의 난을 진압하는데 공을 세운 張潭의 정려이다. 1729년(영조 5년) 청안면 청룡리의 논으로 경작되는 들판에 세웠던 것을 조천리로 이건한 것이다. ○○○○○은 약 40년 전(1969년대 후반)에 이곳으로 이전하였다고 하나 높은 석주형 주초 위에 짧은 원주를 세운 맞배 목조와가로 전통적인 모습을 잘 간직하고 있다. 높은 석주형 주초 위에 짧은 원주를 세운 정면 1칸, 측면 1칸의 맞배지붕 목조기와집이다. 석주형 주초나 이익공계통의 공포 등은 정려로서의 격식을 갖추고 잇는 특징을 보이고 있다.","a":"괴산 장담 충신각","c":"문화유산자료","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660846.jpg"},{"q":"부소산 북쪽기슭의 백마강 좌안(左岸)에 자리한 ○○○는 정면 7칸, 측면 4칸의 법당과 요사(窯舍)의 건물로 이루어진 조그마한 사찰이다. 이 사찰은 불적(佛跡)보다는 고란초에 의해 널리 알려져 있는데 법당 뒤편에서 나오는 약수와 함께 이 사찰의 명물을 이루고 있다. ○○○는 백제멸망과 관련된 여러 가지 전설이 저하나 정확한 유적이나 유물은 없고, 현재의 ○○○는 고려시대에 창건되었는데 현 사찰건물(寺刹建物)은 은산(恩山) 승각사(乘角寺)를 이건(移建)한 것으로 전하고 있다.","a":"고란사","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661042.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태조 7년(1398) 처음 지었으며 임진왜란 때 불타 없어졌다. 광해군 2년(1610) 지금 있는 자리에 복원하여, 1898년·1924년·1935년에 각각 수리하였다. 임진왜란 때는 이 지역 사람인 손복이 향교의 위패를 산중 굴속에 숨겨 무사히 피해를 면했다고 전한다. 지금 남아 있는 건물로는 제사 공간인 대성전과 동무·서무, 교육 기능을 수행하는 강당인 명륜당, 삼문 등이다. 대성전에는 공자를 비롯한 그 제자와 우리나라 성현들의 위패를 모시고 있다.","a":"비안향교","c":"문화유산자료","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662991.jpg"},{"q":"○○○ 석조여래삼존존상은 우협시 지장보살상의 복장물에서 발견된 개분기를 통해 1786년 이전에 제작되었음을 알 수 있다. 특히 우협시 지장보살상의 경우, 착의와 지물 등을 통해 조선중기 17세기 이후 불상제작이 지방화가 이루어지면서 나타나는 현상으로 볼 수 있어, 향후 각 지역간의 불상의 도상적 흐름을 살펴보는데 자료적 가치가 있으므로 경상남도 유형문화유산으로 지정함.","a":"의령 수도사 석조아미타여래삼존상과 복장유물","c":"시도유형문화유산","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642467.jpg"},{"q":"○○○은 약천 금희성의 정자로 그의 후손들이 100여 년 전에 세웠다. 금희성은 경학과 문장이 뛰어났으며, 옥산서당에서 오랫동안 많은 문인 후배 양성에 전념하였다. 계단이 있는 자리를 제외하고는 난간이 사방으로 둘렀으며, 앞면과 중간이 마루이고 좌우가 방이다. 안쪽에는 정기회가 지은 약천중기, 이유승이 지은 정시중건기 등 정자에 대한 기록과 초대 부통령을 지낸 이시영의 친필로 된 ‘○○○’, ‘반곡정사’라는 현판을 보관하고 있다. ○○○ 안에는 한 그루가 향나무가 삿갓 모양을 이루고 있으며 주위에는 노송이 둘러있어 더 한층 경관을 운치 있게 하고 있다.","a":"약천정","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662515.jpg"},{"q":"○○○ 1구 장복실 동편에 있는 석탑으로 현재 지반위에 2개의 반석을 세워 지대석으로 삼고 그위에 하대갑석<下臺甲石> 상대중석<上臺中石> 등의 순서로 기단부를 조성하였고 위로는 2층의 탑신이 남아 있다. 기단중석은 원래 4개의 반석으로 조립되었던 것이나 현재 2개만 남아있고 나머지는 없다.","a":"장복리삼층석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661178.jpg"},{"q":"이 지석묘는 개석식 지석묘로 본래의 모습을 잘 유지하고 있으며 덮개돌 윗면에 크고 작은 굼<性穴>이 141개 분포하고 있어 선사시대 거석문화 연구, 특히 매장행위와 관련된 중요한 자료이다","a":"충주 신청리 고인돌","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651341.jpg"},{"q":"○○은 전동면 송성리에 위치하고 전체둘레 790m, 폭 2m, 높이 2∼5m이며, 성벽은 거의 무너져 있으나 남쪽 성벽만 원형을 보존하고 있다. 전설에 의하면 전의이씨(全義李氏) 시조인 이도가 성을 쌓고 살던 곳이라는 전설이 있어 ○○이라고 한다. 성내에서 백제 말기에 속하는 기와편들이 출토되고 있어 금○○과 함께 백제시대 조성된 산성으로 추정된다.","a":"이성","c":"시도기념물","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2023050113232000.JPG"},{"q":"초상을 치를 때 묘소까지 시신을 운반하던 기구이다. 간략하면서도 화려한 색채가 눈에 띄는 이 상여는 오색 천을 띠 모양으로 잘라 몸체를 감싸고 쇠붙이장식을 매달았다. 네 귀에는 ‘요령’이라는 방울을 달아 상여가 움직일 때마다 저절로 울리게 하였고 지붕에는 민화풍의 화려한 그림을 그려 넣었다. 옛 문서의 기록에 의하면, 조선 영조 39년(1763)에 이 상여를 만들었다 한다. 서귀포시의 신효·하효 마을에서 공동으로 자금을 모아 어렵게 마련한 것으로, 두 마을에서 사용해 오다, 지금은 제주도민속자연사박물관에 소장, 전시하고 있다.","a":"제구","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659232.jpg"},{"q":"○○는 동검과 함께 우리나라 청동기시대를 대표하는 유물로, 적을 찌르는데 쓰는 무기이다. 생긴 모양은 검과 비슷하지만 창날과 자루집 2부분으로 나뉘어 있고, 긴 나무를 꽂아 쓸 수 있도록 끼우는 부분의 속은 비어있다. 제작시기는 세형동검 후기인 BC. 3세기∼AD. 1세기 사이로, 그 출현시기가 검보다 매우 늦고 양도 많지 않아 최초의 유형을 밝히는데 어려움이 있다. 우리나라 ○○의 특징은 자루집이 둥글거나, 그대로 몸통까지 연장되어 등대를 이루고 솟아 있다는 점이다.","a":"동모","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"부산진구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636651.jpg"},{"q":"○○○는 조선 고종 때 병인양요와 신미양요를 승리로 이끈 흥선대원군이 백성들에게 서양 세력에 대한 경계심을 드높이고자 전국 곳곳에 세우도록 한 비이다. 이 비는 건축공사 도중 발견되어 선창마을회의 소유지에 세웠 두었다가 1995년 천가초등학교 교정으로 옮긴 것이다. 비의 모습은 네모난 받침돌 위에 비몸을 세운 간단한 형태이다. 비문에는 ‘서양 오랑캐가 침범할 때 싸우지 않는 것은 곧 화친을 하자는 것이요, 화친을 하자는 것은 나라를 파는 것이다’라는 경고 섞인 내용의 글을 적고 있다.","a":"가덕도 척화비","c":"시도기념물","nc":"","r":"부산광역시","s":"강서구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645110.jpg"},{"q":"이 가옥은 1908년 현 소유주 ○○○의 조부인 이달승에 의하여 건축되었다고 하나 정확한 건축연도의 확인은 어려운 실정이다. 그러나 이전에 가옥이 있었던 것을 1924년 중수된 것으로 추정되며, 안채, 사랑채, 사당, 광채, 외양간, 대문 등으로 구성되어 전통적인 ○○의 형식을 띠고 있다. 남북방향의 장방형 대지 위에 가옥의 전체적인 배치는 튼ㅁ자 형식을 이루고 있다. 문간채와 대문을 지나 행랑채와 사랑채가 서로 문으로 연결되어 곱은자로 꺾이고 一字形의 광채가 있다.","a":"괴산 이창훈 고가","c":"시도민속문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658238.jpg"},{"q":"부여 ○○○ 명부전에는 중앙 불단 위의 ○○○○을 중심으로 그 측면에 무독귀왕(無毒鬼王)과 도명존자(道明尊者)의 삼존상이 있고 시왕(十王)이 각각 좌우에 5왕씩 대칭으로 모셔져 있다. 그 옆으로 판관(判官)과 사자(使者), 인왕(仁王) 등이 있다. 각기 다양한 모양의 존상들은 색채가 화려하고 옷에 새겨진 문양 등이 섬세하며 각기 17∼18세기에 유행했던 시대적 조각양식과 조선후기에 성행했던 명부신앙을 잘 보여주고 있는 바, ○○○의 불교유물들과 관련하여 생각해 볼 때 17세기 중엽에 조성된 것으로 추정되며 명부전의 모든 존상들을 잘 갖추고 있다.","a":"부여무량사지장보살및시왕상일괄","c":"시도유형문화유산","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019052011081200.jpg"},{"q":"이 책은 야은(冶隱) ○○의 언행 가운데 이전까지 수습하지 못했던 것을 추가로 수습한 것이다. 내제(內題)는 『○○○○○』로 되어 있으며, 판심제(版心題)는 『야은○○○○』로 되어 있고, 표제(表題)가 『야은집(冶隱集)』으로 되어 있다. 목판본 1책이며, 1615년 여헌(旅軒) 장현광(張顯光, 1554∼1637)이 지은 발문(跋文)이 들어 있다. 참고로 이 책의 초간본은 1573년에 간행되었으며, 이 책은 그 중간본(重刊本)이다.","a":"길재 야은선생언행습유","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665017.jpg"},{"q":"○○○는 통일신라 경문왕 8년(868)에 철감선사가 중국에서 귀국하여 절터의 경치가 좋은 것을 보고 세웠다고 한다. ○○○은 앞면 3칸·옆면 3칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포 양식으로 꾸몄다. 천장은 우물 정(井)자 모양으로 천장 속을 가린 우물천장이고, 바닥에는 마루를 깔았다. 창문은 2짝 여닫이문을 달았다.","a":"쌍봉사극락전","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662000.jpg"},{"q":"조선 선조 때의 무관 박홍장이 살던 집이다. 박홍장(1558∼1598)은 임진왜란 때 활약한 장수로 유성룡이 추천하여 왜란을 수습하기 위해 일본에 통신사로 파견되었다. 도요토미가 사절일행을 멸시하였으나 조금도 굴하지 않고 나라를 위해 의지를 굽히지 않았다. 이 가옥은 선조 3년(1570)에 세워 전하다가 숙종 46년(1720) 건물의 일부가 소실되었다. 앞면 4칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 이루는 팔작지붕이다. 천장에 초가집이 까치구멍집과 비슷한 형태인 투창이 있다는 점이 특이하다.","a":"영덕 농아당 종택","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663137.jpg"},{"q":"고려 후기의 문신인 익재 ○○○ 선생의 ○○화로, 현재 국립중앙박물관에서 보관하고 있는 선생의 영정(국보 제110호)과 형식이 같은데, 조선시대에 옮겨 그린 것으로 보인다. 약간 오른쪽으로 앉아 두 손을 앞으로 모으고 있는 전신좌상으로, 가로 96㎝, 세로 165㎝의 크기이다. 인물을 중심으로 윗부분에 그림의 제작에 관한 내용과 그림을 찬하는 글을 적고 오른편에 몇 권의 책이 놓인 책상을 배치하여 재미있는 화면 구성을 보이고 있다. 또한 의자의 손잡이는 앞으로, 책이 있는 책상은 인물의 뒤로 자연스럽게 두어 인물의 자태가 안정감이 있다.","a":"이제현 초상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638499.jpg"},{"q":"조선 초기의 문신인 ○○ 선생과 부인 ○○ 이씨, 아들 어변갑(1380∼1435) 선생의 묘소이다. ○○ 선생은 태종 9년(1409)에 충주판관이 되고 이후 대구 현령이 되었으며, 세종 11년(1429)에 84세로 생을 마쳤다. 어변갑 선생은 태종 8년(1408) 문과에 장원급제한 후 세종 2년(1420) 새로 발족한 집현전의 응교로서 세자 시강원 좌문학 및 춘추관의 가주관을 역임하였으며, 태종실록 편찬에 참여하였다. 세종 6년(1424)에 집현전 직제학에 올랐으며, 세종 17년(1435) 향년 55세로 돌아가신 후 자헌대부 병조판서 겸 지의금부사로 관직이 높여졌다.","a":"함안 어연 묘역","c":"문화유산자료","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664369.jpg"},{"q":"○○○는 경남 ○○에 있었던 관개용 저수지로서 원삼국시대에 축조되었다고 추측된다. 『세종실록지리지』·『신동국여지승람』을 보면 후대에도 여러 번 제방을 고쳐 쌓은 기록이 나타나는데, 임진왜란(1592) 이후에 황폐하여 이용하지 못하였다고 한다. 1928년까지 황토흙으로 된 제방의 일부가 남아 있었으나 지금은 없어지고 저수지는 논으로 변하였다. 이곳의 제방은 낙동강의 지류인 용진강이 범람해 오는 것을 막기 위해 쌓은 것으로, 양수와 배수를 위해 수산리 산 524-1번지 부근 자연암반 밑으로 ○○을 내었는데 그 ○○의 흔적이 흙 속에 묻힌 채 지금도 남아있다.","a":"밀양 수산제 수문","c":"시도기념물","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655462.jpg"},{"q":"세운 시기를 정확하게 알 수 없으나 기록에 따르면 약 90여년 전에 지은 것으로 추정한다. 건물은 안채, 사랑채, 곳간채, 헛간채, 솟을대문 등으로 구성되어 있다. 안채는 앞면 6칸·옆면 2칸 규모이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양의 팔작지붕이다. 사랑채는 앞면 5칸·옆면 2칸 규모로 지붕은 팔작지붕으로 꾸몄다. 곳간채와 헛간채는 앞면 5칸·옆면 2칸 크기인데 헛간채는 방앗간과 창고를 겸하고 있다.","a":"고성송계리이씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664217.jpg"},{"q":"장승은 마을입구나 길가에 자리하여 그 마을의 수문신·수호신 등의 구실을 하는 민간신앙의 한 형태이다. 이 ○○○은 남·여 한쌍의 모습으로, 마을 입구 길 양 쪽에 1구씩 놓여 있다. 오른쪽 높은 곳의 돌담사이로 서 있는 것이 ‘상원주장군’이고, 길 건너 낮게 서 있는 것이 ‘하원당장군’이다. 상원주 장군은 여자의 형상으로, 민머리에 얼굴은 거의 평면이다. 생김새는 주름진 이마에 갈매기 모양의 눈썹을 가지고 있으며 동그란 눈, 방망이 모양 코, 뚜렷한 콧구멍 등이 표현되어 있다.","a":"해평리석장승","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661987.jpg"},{"q":"이희맹·김제민·최안·김지수를 비롯하여 김제안·김흔·김섬·김습 등을 기리고 있는 서원이다. 이희맹은 조선 전기 문신이며 김종직의 제자로 성균관 재학시절부터 문장과 인품으로 인정을 받았다. 성종 23년(1492)에 장원 급제하여 등용되었으며 이후 여러 벼슬자리를 거쳤다. 김제민(1527∼1599)은 이항의 제자로 과거에 급제하여 벼슬길에 올랐으며 임진왜란 때에는 의병을 모아 왜군과 싸워 공을 세웠다. 이 서원은 현종 14년(1673)에 이희맹, 김제민과 더불어 조선 중기 의병장 최안과 조선 중기 문신 김지수를 모시기 위해 세웠다.","a":"도계서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661695.jpg"},{"q":"○○○○○ 석불좌상은 목이 절단된 것을 새로 붙여 두는 등 군데군데 시멘트로 두텁게 보수하기는 하였지만, 그나마 상호와 상반신의 전면이 그대로 남겨져 있다. 특히 상호와 입가의 미소는 인근 명주지역의 신복사지, 월정사지 석조보살좌상과 유사한 모습이어서 이들과 동일시기인 고려 초에 제작된 것으로 판단된다. 광배는 舟形인데 상단의 일부분이 깨진 것을 제외하고는 상태가 비교적 양호하다. 함께 반출된 대좌의 중대석은 원래 3개의 돌로 이루어져 있었으나 현재 2점만이 남겨져 있다.","a":"강릉 청학사 소장 청동보살입상","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660656.jpg"},{"q":"파두는 동검이나 철검의 손잡이 끝에 부착하는 특이한 형태의 장식으로, 그 용도에 대해서는 칼자루 끝을 무겁게 하여 손에 쥐었을 때 균형을 잡을 수 있게 하기 위한 것이라는 것이 일반적인 의견이다. 파두의 대부분이 십자형의 조그만 것인데 비해 이 ○○○는 십자형 2개를 옆으로 나란히 연결한 쌍십자 모양이다. 축의 끝부분에는 각각 한마리씩 모두 4마리의 말을 세웠고, 십자의 중심에는 커다란 사각기둥의 꼭지를 두었다. 우리나라에서는 칼자루 끝장식의 형식이나 연대를 밝힐 유물의 양이 극히 적고 그나마 정리가 안 된 상태여서 앞으로 이 부분에 대한 연구가 절실히 필요하다.","a":"동파두","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"부산진구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636654.jpg"},{"q":"조선시대 ○○현의 관아 건물로, 태종 5년(1405)에 지어졌다고 전한다. 그 후 여러 차례의 수리를 거쳤으며 지금 남아있는 건물을 19세기 후반의 것으로 보인다. 1915년에도 수리가 있었고, 한때 ○○지서로 사용되어 변형이 있었으나 1981년 복원하였다. 앞면 6칸·옆면 3칸의 규모이며, 지붕의 옆선이 여덟 팔(八)자 모양인 팔작지붕집으로 홑처마에 공포를 짜지 않은 민도리집이다. 낮은 돌 기단 위에 지었는데, 주춧돌은 다듬은 돌과 자연돌을 함께 사용하였고, 둥근 기둥에 일부 네모 기둥을 세우기도 하였다.","a":"괴산 청안 안민헌","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638532.jpg"},{"q":"이 교회는 전라남도 지역이 광주교구로 승격되던 1937년 광주성당의 4대 주임신부로 부임한 구< 具 >신부(Rev. Thomas Quinlan)가 계획을 세워서 지은 것이다. 구신부는 교회를 신축하기 위해서 성당건축에 경험이 많은 중국인 가요셉에게 설계와 공사를 맡겨서 1937년 10월에 착공하여 이듬해 6월에 낙성하였다. 건물의 평면은 가늘고 긴 사각형으로 정면에 종탑을 배치하고 좌측면에만 제의실과 고해실을 배치하였다. 외벽은 고막이돌을 놓고 붉은색 벽돌을 쌓았으며, 종탑과 측면에 있는 창틀과 문에는 화강석으로 인방을 설치하였다.","a":"광주북동천주교회","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645773.jpg"},{"q":"○○○○○은 대웅전 내 수미단 위에 본존 우측에 봉안되어 있다. ○○○○○은 머리에 나발이 있고, 이마 위에 타원형의 중앙계주가 그려져 있다. 계란형의 얼굴에 지긋하게 감은 눈, 이마 중앙에 커다란 백호, 삼각형의 오뚝한 코, 붉은 입을 표현하였다. 목에 삼도와 어깨까지 늘어진 귀가 부자연스럽다. 법의는 대의 안쪽에 편삼을 걸친 변형우견편단으로, 왼쪽 어깨에서 팔꿈치까지 완만하게 대의 자락이 늘어져 있고, 오른쪽 어깨에서 완만하게 내려온 대의자락과 편삼이 복부에서 겹쳐있다. 하반신을 덮은 대의자락은 앞치마를 입은 듯이 반원형을 그리고, 양 발바닥이 모두 드러나 있다.","a":"평택 서천사석조여래좌상","c":"문화유산자료","nc":"","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660278.jpg"},{"q":"1788년(정조12)에 조성된 조선후기의 ○○으로, 현재 무주 ○○○○○각 내 후면에 안치되어 있다. 천판(天板)위에는 용뉴(龍紐)가 남아 있지 않아 원래 어떠한 모습이었는지 알 수 없지만 천판 위에 3개의 구멍이 뚫려있는 것으로 볼 때 아마도 쌍룡(雙龍)의 용뉴가 있었던 것으로 추정된다. 용뉴를 제외한 전체높이가 83cm에 달하는 중형의 종으로 보존상태는 양호한 편이다. 천판은 나즈막하며 위에는 3개의 구멍이 뚫려 있다. 이 가운데 2개는 쌍용의 용뉴를 고정하기 위한 것이며, 하나는 音筒 대신 종소리를 위하여 뚫어놓은 것으로 보인다.","a":"안국사 소장 범종","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661888.jpg"},{"q":"○○○은 1920년대 일제초기에 창건된 전통사찰로서 목포시에 인접한 해안가에 위치하고 있었다. 그러나 이 일대가 1990년대초 한라조선소 조성단지로 편입되면서 원래 위치에서 남쪽으로 1.5㎞ 떨어진 현 장소로 1994년 이전하였다. 한지에 묵서한 조성발원문(가로 118㎝×세로 26㎝)에 따르면 1700년(숙종 26) 해남 성도암에서 조성하였음을 알 수 있다. ○○○○○은 소발의 머리에 상호는 원만하며, 눈과 코 입 등이 사실적으로 표현하였고, 수인은 선정인을 취하였다. 표면의 채색은 주로 적색과 녹색이 주류를 이루고 있어 고풍스럽게 보인다.","a":"영암축성암목조나반존자상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662242.jpg"},{"q":"대아고등학교 교정에 자리하고 있는 탑으로, 높게 마련된 기단(基壇) 위로 3층의 탑신(塔身)을 올린 모습이다. 기단은 각 면의 모서리마다 기둥 모양을 본 떠 새기고, 면의 가운데에도 2개씩의 기둥 조각을 두었다. 탑신의 각 몸돌은 2단의 괴임조각 위에 놓여 있으며, 지붕돌은 밑면에 3단씩의 받침을 새겨놓았다. 3층 지붕돌 위로는 꽃봉오리 모양의 머리장식이 놓여 있는데, 이는 원래의 것이라기보다 훗날에 만들어 얹어 두었을 것으로 보인다.","a":"진주 이현동 삼층석탑","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664583.jpg"},{"q":"대한제국 때 활약했던 김봉선(1856∼1909)이 남긴 문서와 국가의 중대한 의식이 있을 때 입던 대례복을 비롯한 여러 유물들이다. 김봉선은 전북특별자치도 남원 출신으로 을사보호조약 이후 고종의 밀명을 수행하였다. 을사보호조약으로 실추된 국권회복 방안의 연구와 이와 관련된 정보수집, 헤이그 만국평화회에 보낼 밀사의 추천과 파견에 대한 일을 하였다. 문서에는 고품서와 고종의 밀명이 담긴 편지·칙명·이력서·증서를 비롯하여 48점이 있으며, 보존상태는 양호하다. 대례복은 하의가 없어져 상의와 허리에 차는 검·대례모·호패·인장이 남아 있다.","a":"김봉선유품","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659611.jpg"},{"q":"김만기金萬基(1633-1687)는 조선 17세기인 효종, 현종, 숙종 연간에 활약한 문신이다. 김만기의 증조할아버지는 예학의 대가 김장생金長生이고, 그의 스승을 송시열宋時烈로 그는 조선 후기 예학의 확산과 관련이 깊다. 그의 동생은 소설 구운몽을 지은 김만중이고, 그의 딸은 숙종의 비 인경왕후로, 김만기는 숙종이 왕위에 오른 후 왕의 장인이 되어 광성부원군光城府院君에 봉해졌다. 김만기 일가 묘역은 네 개의 구역으로 구분되는데, 상단에는 김만기 부부가 안치되어 있다.","a":"김만기선생묘 및 신도비","c":"시도기념물","nc":"","r":"경기도","s":"군포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646635.jpg"},{"q":"귀신사 3층 석탑 앞쪽에 놓여 있는 것으로, 웅크리고 있는 사자상 등 위로 남근석(남성의 생식기 모양으로 다듬은 돌)이 놓여 있다. 사자상은 머리를 치켜들고 앞을 바라보고 있는데 매우 사실적으로 표현되었다. 남근석은 2단으로 구성되어 있는데, 아랫부분은 대나무에서와 같은 옅은 마디를 두었다. 사찰 내에서 이러한 조각상을 찾아보기란 매우 드문 것으로, 이에 대해서는 두가지의 설이 제기되고 있다.","a":"귀신사석수","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639465.jpg"},{"q":"전라남도 장흥군 부산면 ○○○ 자미 마을 뒤편 높이 20m가량 되는 병풍 바위에 새긴 마애불이다. 지상에서 약 6m 높이에 선으로 새겨 표현하였는데, 바위면이 평평하지 않아 전체 윤곽을 파악하기 힘들다. 민머리의 정수리 부근에는 상투 모양의 머리묶음이 높이 솟아 있고, 얼굴에는 콧등만이 유난히 돌출되어 있어 인상적이다. 옷은 양 어깨에 걸치고 있는데 무릎 밑으로 옷주름이 흘러 내려와 있다. 아랫부분으로 내려오면서 마모가 심해 정확한 윤곽을 알 수 없다. 오른손은 손등을 보이며 손끝이 땅을 향하게 하고 있고, 왼손은 손바닥을 위로 한 채 무릎 위에 얹혀 있다.","a":"장흥구룡리마애여래좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640130.jpg"},{"q":"동헌은 옛 관청인 관아에서 업무를 처리하던 중심 건물을 가리킨다. ○○동헌은 원래 현종 4년(1663) 현감 성희위가 처음 지었다고 한다. 지금 있는 건물은 영조 42년(1766)에 이전 건물이 낡아 당시 현감 이덕부가 남쪽에 새로 지어 ○○○이라 이름 지은 건물이다. 1920년부터 당시 ○○보통학교 건물로 사용했으며 1972년 현 위치로 옮겨 ○○초등학교에서 관리하고 있다. 규모는 앞면 5칸·옆면 3칸이며 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 기둥 윗부분에 설치한 공포는 새 날개모양의 익공 양식으로 꾸몄다.","a":"괴산 연풍 풍락헌","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638649.jpg"},{"q":"이 건물은 1932년에 일제가 이 지역 16개 동을 관할하기 위해 지은 ○○○로 1937년부터 ○○○○○로 사용해 오고 있으며, 1979년 이 건물 뒤쪽에 붙여 철근 콘크리트조 2층 사무실을 증축하였다. ○○○○○는 읍내 중심 가로에 면하여 동서로 약간 길게 남향 배치된 붉은 벽돌쌓기 2층 건물로 모임지붕을 이엇으며, 정면 중앙의 현관 포치(Porch)를 중심으로 좌우대칭을 이루고 있다. 평면은 동서가 약간 긴 장방형으로 1·2층 모두 통간(通間) 구성이었으나 현재 칸막이벽을 설치하여 1층은 민원봉사실과 창고, 2층은 읍장실과 사무실로 사용하고 있다.","a":"예천읍사무소","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663311.jpg"},{"q":"○○○는『삼국유사, 三國遺事』 등의 기록에 나오는 자추사(刺楸寺)일 것이라 한다. 자추사가 맞다면 신라 법흥왕(法興王) 14년(527)에 불교를 나라의 종교로 삼도록 순교(殉敎)한 이차돈(異次頓)을 기리기 위한 절이다. 이 건물은 임진왜란 때 불타고 그 후 다시 지었다. 단층의 목조 기와집으로 옆에서 보면 ‘사람 인(人)’자 모양을 한 맞배지붕이다. 정면 3칸, 측면 3칸의 다포(多包)집으로 좌우 협칸에 쌍여닫이문을 두었다. 기단부는 일부 신라시대 양식을 지니고 있다.","a":"백률사대웅전","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662351.jpg"},{"q":"청화로 칠보문과 길상문을 그린 백자항아리이다. 직립한 구연에, 어깨는 팽창하였고 동체는 중간 아래로 가면서 잘록한 곡선을 그리며 굽으로 이어진다. 은은한 푸른빛이 감도는 유색에 짙은 청색 문양이 활달하고 조화롭다. 청화로 어깨 부분에 이중의 원권을 네 곳에 배치하고 그 안에 각각 도안화된 ‘수복’(壽福)자를 써 넣었다. 원권문 사이에는 칠보문을 그려 문양의 변화와 조화를 꾀하였다. 동체아래 굽 바로 위쪽으로는 두 줄의 청화선을 돌리고, 그 위로 네 곳에 초화문(난초)을 시문하였다.","a":"백자청화칠보수복문호","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636463.jpg"},{"q":"○○○○○ 소장 책판은 광주노씨(光州盧氏)문중 여러 선인들의 문집을 인출(印出)하기 위해 제작된 것으로 시기는 1800년∼1900년대에 걸치는 것이다. 이들 문집 책판은 광주노씨○○문중의 여러 세대에 걸쳐 생몰시기가 다른 일가 20여명 제선생(諸先生)의 문집 원판으로서 이것이 흩어지지 않고 모두 한곳에 일괄 보관되어 오고 있는 점은 매우 의미가 있는 일이다. 이들 문집 책판은 조선시대 지방 선비들의 학문세계, 문학성, 사회성, 사상성과 지방의 역사, 판각사, 출판사 연구에 훌륭한 자료가 되므로 역사자료로서의 가치는 물론 문화유산적 가치가 높다.","a":"창녕 동산서당 목판","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665389.jpg"},{"q":"담양 ○○○ 고택은 고하 ○○○의 성장했던 곳으로 한말 호남의병의 영수인 성재 기삼연이 1차 의병을 일으켰다가 조정의 해산조치에 반항하여 체포된 후 감옥에서 탈출하여 은거했던 곳이다. 이곳에서 기삼연은 ○○○를 교육하였고 후일의 의병활동을 구상하여 한말의병의 중핵인 3차의병의 중심역을 했던 호남의병을 일으킬 수 있게 하였다. ○○○는 항일운동과 교육활동, 그리고 해방 전의 활동이 국가 민족에게 공헌한 바 컸으므로 1963년 3월 1일에 건국 공로훈장이 추서되었다.","a":"담양송진우고택","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662303.jpg"},{"q":"전라남도 보성군 조성면 봉릉리 신방 마을 저수지 둑 밑의 논두렁에 서 있는 ○○○이다. 이 일대에 옛 기와조각들과 탑의 몸체부 등이 흩어져 있는 것으로 보아 원래는 절터였음을 알 수 있다. 기둥 모양의 돌을 다듬어 앞면만을 조각하고 뒷면은 평평하게 처리하였다. 대개 ○○○은 석탑의 기단부에 돋을새김을 하는데 이처럼 단독상으로 만드는 일은 드물다. 머리 위에는 상투 모양의 머리묶음이 솟아 있고, 눈을 부릅뜨고 있는 얼굴은 돌이 많이 닳아 있다. 코와 입은 형식적이며 귀는 짧게 처리하였다. 오른손은 위로 들고 있고, 왼팔은 구부려 가볍게 허리쪽에 대고 있다.","a":"보성봉능리석조인왕상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662084.jpg"},{"q":"○○○은 조선시대 ○○현의 객사이다. 객사는 전패(殿牌)를 안치하고 초하루 보름으로 대궐을 향하여 절을 하는 의식을 거행하는 한편, 중앙에서 내려온 사신의 숙소로도 사용한 관아건축이다. 건물구조는 지붕이 좀더 높은 3칸의 정당이 중앙에 있고 그 좌측에 4칸, 우측에 3칸의 익실(翼室)을 두었으며, 전면에 중문․외문, 측면에 무랑 등이 부속되었고, 정당은 벽돌을 깔고 좌․우익실은 한국식 우물마루로 되어 있다.","a":"청주 문의 문산관","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638467.jpg"},{"q":"높이 3.7m의 일반형 석탑으로 높직한 지대석 위에 2층 기단을 갖추고 있다. 하층 기단은 불상의 대좌와 같이 하대석·중대석·상대석으로 구성되어 있다. 상·하대석의 판내에 연화문(蓮花文)과 장방형의 액(額)이 공통적으로 조각되어 있는데, 중대석에는 측면 기둥인 우주(隅柱)와 가운데 기둥인 탱주(撑柱)가 표현되었다. 상층기단의 면석(面石)에는 양 우주와 탱주가 있는데, 기둥의 사이에는 장방형의 액을 모각하였고, 그 위에 옥개석(석탑이나 석등 따위의 위에 지붕처럼 덮은 돌) 형태의 갑석(甲石)을 놓았다.","a":"현등사삼층석탑","c":"시도유형문화유산","nc":"","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2227402.jpg"},{"q":"조숙기, ○○○의 부부묘 4기는 봉분이 흘러내려서 평면 형태는 분명하게 확인되지는 않으나 전면은 ㄷ자형을 이루고, 후면 즉 산의 높은 쪽은 원형에 가까운 형태의 아주 잘 만들어진 무덤이다며 무덤의 면석과 月石 등은 아주 정교하게 만들어진 수작들이다 봉분의 전면에는 잘 다듬은 면석을 붙이고 가운데에 月石을 세웠는데, 면석에는 초화문, 월석에는 청룡과 주작이 새겨져 있으며 상석은 사암을 이용하여 1매로 잘 다듬어 놓았으며, 축대는 치석한 돌을 臥垂積과 縱平積을 혼용하여 쌓았다. 부부묘의 사이에는 작은 돌을 쌓아서 흙의 흘러내림을 방지하고 있다.","a":"진주 조윤손 묘역","c":"시도기념물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657545.jpg"},{"q":"광주광역시 서구 ○○○에 있는 불상으로 원래 쌍촌동 운천사에 있던 것으로 1939년 지금의 위치로 옮겨 왔다. 전하는 이야기에 의하면 당시 극락면이었던 ○○○은 사람의 왕래가 많고 주민들도 많이 살았는데 마땅히 소원을 빌 만한 대상이 없어 운천사에 있던 불상을 지금의 위치로 옮겼다고 한다. 부처님의 코를 먹으면 아들을 낳는다는 소문이 퍼져 주민 뿐만 아니라 지나가는 행인들까지 코를 깎아가는 바람에 현재 얼굴 윤곽이 명확하지 않다. 머리 뒤쪽에 일부 남아있는 무늬, 상투 모양의 머리묶음, 엄지와 검지를 가볍게 쥐고 있는 오른손의 모습 등은 뚜렷하게 남아 있다.","a":"유촌동석조여래좌상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659675.jpg"},{"q":"장충단 공원 입구에 놓여있는 돌다리로, 원래는 청계천 2가에 있었으나 1959년 청계천 복개공사를 하면서 지금의 자리로 옮겨왔다. 화강암을 짜맞추어 만들어 놓은 것으로, 아래의 돌기둥이 특이하게도 2단을 이루고 있다. 그 중 윗단의 돌은 모서리를 물의 흐름과 마주하게 하여 물의 저항을 덜 받도록 하였다. 난간은 연꽃봉오리, 연잎 등을 주제로 설계해 놓았는데 그 조각들이 매우 아름답다. 조선 세종 2년(1420)에 세운 다리로, 당시에는 이곳에 소시장이 있었다 하여 ‘마전교 ’라 불리웠다.","a":"수표교","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636095.jpg"},{"q":"권준(權蹲)이 1444년(세종 26) 4월 18일에 한성부의 무오년(1438) 호적에서 등사하여 발급받은 ○○○이다. 이때 권준이 살았던 곳은 한성부(漢城府) 북부(北部) 양덕방(陽德坊)이었다. ○○○ 아버지는 양촌(陽村) 권근(權近)이다. ○○○ 내용에 의하면 권준은 ○○○를 발급받을 당시 35세로 조봉대부(朝奉大夫) 군기감부정(軍器監副正)이었다. 부인 해주정씨는 37세로 그의 아버지는 판중군도총제부사(判中軍都總制府事) 정역(鄭易)이었다. 큰아들 권혜(惠)는 15세이고, 자부는 최저(崔渚)의 딸이다. 둘째아들 권응(應)은 13세였다.","a":"권준의 준호구","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637195.jpg"},{"q":"타원형의 평평한 돌에 새긴 것으로 마애불과 비슷한 형식의 불상이다. 둥글넓적한 얼굴에 눈과 입을 가는 선으로 작게 표현했지만 미소를 띠고 있다. 몸은 입체감 없이 평면적이며 양 어깨는 둥글게 처리되었다. 양 어깨에 걸쳐 입은 옷에는 계단식의 옷주름을 투박하게 나타냈고, 가슴과 배 아래에 띠매듭이 있다. 앉은 자세는 양 발을 무릎 위에 올리고 발바닥이 하늘을 향한 모습인데, 오른발의 처리가 조금은 어색하다. 부처의 몸에서 나오는 빛을 형상화한 광배(光背)는 선으로 표현하고 있다.","a":"예산상항리석불","c":"시도유형문화유산","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639119.jpg"},{"q":"이 작품은 20세기 초 동래 전역 즉, 현재의 부산광역시역을 그린 회화에 지명을 부기한 10폭 병풍으로, ○○○의 각 면과 부산부(釜山府)의 부산면(釜山面)을 망라하고 있다. 지도라기보다는 일련의 산수화로서 느낌이 강하고 산수의 형상, 성곽 주변의 경물, 사원, 항만, 선박 등을 능숙하게 묘사하였으며 색감을 조화롭게 사용하였다. 구성은 전체적인 구도를 미리 생각하지 않고 한 폭 마다 구도를 잡아서 화면을 구성하였으며 각각의 위치에 지명을 적고 있다.","a":"동래부산도병","c":"문화유산자료","nc":"","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020082718251800.jpg"},{"q":"경상도 관찰사가 살림채로 쓰던 건물이다. 조선 선조 34년(1601)에 선화당, 응향당 등 여러 건물과 함께 지었으며 그 뒤 여러 차례 고쳐 지어 오늘에 이르고 있다. 앞면 8칸·옆면 4칸으로 넓이가 무려 227㎡나 되며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. ○○○은 선화당과 함께 대구시내에 남아있는 유일한 관아건물로 중요한 국가유산이다.","a":"징청각","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636841.jpg"},{"q":"현재 ○○○ 경내에 비각을 세워 보호하고 있는데 비신 앞뒤면에 총 1,420 여자가 새겨져 있다. 전면 상단에 좌행으로'어제달천○○○○'라 전각(篆刻)하였는데 비제 다음 바로 본문을 쓰고 끝에 이 비문의 서자와 전자를 쓴사람을 밝히고 있다. 자헌대부 예조판서겸 직제학 이병모(李秉模)가 글을 쓰고 이조판서 윤동섬(尹東暹)이 전자를 썼다.","a":"충주 충렬사비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638908.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태조 7년(1398)에 지금 위치 북쪽에 처음 지었다. 호랑이로 인한 피해가 심해지자 숙종 18년(1692)에 향로산 서쪽으로 옮겼으나 지대가 습하여 순조 34년(1834) 이후 지금 있는 자리로 다시 옮겼다. 현재의 향교 건물들은 그 후 몇 차례의 보수를 한 것이다. ○○○은 공자를 비롯하여 중국 유학자의 위패를 모시고 제사를 지내는 곳으로 규모는 앞면 3칸·옆면 2칸이다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다.","a":"무주향교 대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661717.jpg"},{"q":"이 교회는 1906년 영국인 주교 조마가(Mark N. Trollope)가 지은 ○○ 건물로 우리나라의 초기 서양 기독교 교회양식의 건물이다. ○○은 정면 3칸 측면 1칸이며 중앙 1칸을 2층 종루로 삼은 문루와 정면 9칸 측면 3칸의 본당으로 이루어진 건물인데 한국의 전통적인 건축기법을 활용하여 종교적인 ○○건축 방법과 공간 구성을 확립한 동서 절충식 강당형의 목조건물이다. 지붕은 팔작지붕으로 되어 있고, 용마루 양끝에는 연꽃 모양으로 된 곡선미를 살린 돌십자가가 달려 있다.","a":"강화 온수리 성공회 성당","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637123.jpg"},{"q":"◦ ○○○○은 1610년(광해군2)에 충청관찰사 정엽(鄭曄)과 이지함의 문인인 구계우(具繼禹)가 주도하여 건립하였으며, 1686년(숙종12)에 ○○○○으로 사액(賜額)되었음. 흥성대원군의 서원철폐령으로 1868년(고종5) 철폐되었다가 1922년 다시 복설되었고, 청천저수지 축조로 1959년에 현 위치로 옮겨 세워졌음. ◦ 처음에는 토정 이지함(土亭 李之菡)과 명곡 이산보(鳴谷 李山甫)를 모셨고, 이어서 1723년에는 천휴당 이몽규(天休堂 李夢奎), 고종조에는 퇴우당 이정암(退優堂 李廷馣), 1971년에는 수암 구계우 등 5분의 위패를 모셨음.","a":"화암서원","c":"문화유산자료","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661120.jpg"},{"q":"김상헌(金尙憲, 1570~1652)은 1626년(인조 4) 5월에 성절겸사은진주사(聖節兼謝恩陳奏使)에 임명되어 북경을 갔다가 1627년(인조 5) 5월에 돌아왔다. 이 사행 때에 김상헌이 서장관(書狀官)으로 동행했던 김지수(金地粹)에게 시를 지어주었는데, 이를 모아 장첩한 것이「○○○○」이다. 이 책은 뒤에 김상헌의 문집인『청음집』을 간행할 시에「조천록(朝天錄)」이란 편명으로 수록되었다.『청음집』의 「조천록」에는 시(詩) 136수와 문(文) 14편이 수록되어 있으나「○○○○」에 실린 김상헌의 시는 약 30수이다.","a":"조천신장","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023032116183300.JPG"},{"q":"○○○는 망해산에 있는 절로 백제 의자왕(재위 641∼660) 때 지어졌다고는 하나 그 뒤의 역사가 전해지지 않고 있다. ○○○○○은 석가모니를 모시는 법당으로 높은 기단 위에 세워진 앞면 3칸·옆면 2칸 규모의 건물이다. 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕이다. 기둥 위에서 지붕 처마를 받치는 공포가 기둥 위에만 있는 주심포 양식인데 반해 건축양식은 다포식 계통의 수법을 따르고 있다. 기단 위의 기둥은 가운데만 굵게 한 배흘림 형식이며, 앞면 가운데칸은 3짝으로 亞자형 문이고, 양 끝칸은 2짝문으로 되어있다.","a":"불주사대웅전","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639544.jpg"},{"q":"조선시대 아산군 관아 입구에 세웠던 문루건물로, 사방을 트고 마루를 한층 높게 지은 다락형식의 집이다. 조선 태종 11년(1411) 현감 최안정이 낡은 객사를 고쳤다고 하는데, 태종 13년 백성들의 도움을 얻어 객사 동편에 지었다고 한다. 앞면 3칸·옆면 2칸 규모로, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새날개 모양인 익공양식이다. 기둥 사이에는 꽃받침 모양의 건축 재료를 가운데 칸에 3개, 나머지 칸에는 2개씩 만들어 처마를 받치면서 건물의 무게 균형을 맞추고 있다.","a":"여민루","c":"시도유형문화유산","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639024.jpg"},{"q":"○○○의 ○○○ 안에 있는 목조각상으로 도명존자와 무독귀왕을 비롯하여 시왕 등이다. 도명존자는 지옥보살의 지팡이를 들고 있고 무독귀왕은 문관차림이다. 시왕은 삼존의 양 옆으로 나란히 배치되어 있는데, 그 사이사이로 사자, 판관, 동자상 등이 있다. ○○○의 입구에는 인왕상이 있다. 조선 후기에 만들어진 이 목조각상들은 불교미술사 연구에 매우 중요한 자료이다.","a":"고성운흥사명부전 목조지장보살권속상","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664664.jpg"},{"q":"병조호란 때 순절한 윤계(尹棨, 1603~1636)의 행적을 새긴 비이다. 본관은 남원(南原)이고 호는 신곡(薪谷)이다. 병자호란이 일어나자 항전을 준비하였고, 휘하의 군병들이 청병(淸兵)에 의해 모두 궤멸되자 남양부 청사에서 끝까지 항전하다가 순절하였다. 1668년(현종 9)에 읍민들이 윤계의 충의를 기리고자 ○○○를 건립하였다. ○○○는 사각형의 받침돌에 윗면이 둥근 비신(碑身; 글씨를 새기는 부분)을 세운 방부원수(方趺圓首) 양식이다.","a":"윤계선생순절비","c":"시도유형문화유산","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637484.jpg"},{"q":"조선 중기 학자인 정극후(1577∼1658)의 별장이라 전한다. 조선 광해군 12년(1620)에 세웠으며 영조 4년(1728)에 다시 지었다. 높은 석축 위에 자리잡은 3칸 규모의 정자로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 가운데 칸에 마루를 두고 좌우에 방을 두었으며, 건물 앞면 전체에 툇마루를 내어 난간을 두른 누각형 정자이다. 건축 기법에서는 조선 중기 양식과 후기 양식이 섞여 있어 그동안 여러 차례 보수가 있었음을 알 수 있는데, 지금 있는 건물은 대체로 조선 영조(재위 1724∼1776) 때의 양식을 취하고 있다.","a":"수재정","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662733.jpg"},{"q":"○○○터는 철을 생산하던 곳이다. 이 곳 ○○○○○는 ‘깊은골’로 불리는 동대산의 작은 개울을 앞을 둔 산중턱에 위치하고 있다. 이 유적은 노(爐 : 높이 1m, 지름2m)의 일부가 잘 남아 있고, 그 양쪽으로 약 3m 길이의 축대가 남아 있는 등 보존상태가 양호하다. ○○○○○도 조선시대 영남지역의 최대 철산지였던 인근 달천철장의 토철을 이용하여 쇠를 생산하였던 곳으로 짐작된다. ○○○○의 주변에는 숯을 구웠던 흔적과 ○○○작업 당시 생긴 쇠똥(슬래그) 등이 남아 있어 제련 작업이 이루어졌음을 증명하여 주고 있다.","a":"대안동쇠부리터","c":"시도기념물","nc":"","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645926.jpg"},{"q":"지방 양반들이 행정업무를 도우면서 향촌의 사회·정치적 지위를 유지하기 위하여 모였던 건물이다. 서울과 지방의 연결고리 구실을 하기도 했다. 1500년대 말에 현감 벼슬을 지내던 한순이 처음 세웠으나 임진왜란 때 없어졌고, 광해군 2년(1610)에 손자인 한진이 다시 세웠다고 한다. 그 뒤 여러 차례 고쳐 지었고 일제시대에는 일본군이 업무를 처리하던 곳으로 이용하였다. 1995년까지 상주시에서 업무를 처리하는 곳으로 사용하였다. 앞면 5칸·옆면 2칸 규모인데 건물 자체는 많이 훼손되었다.","a":"상주향청","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663163.jpg"},{"q":"『 망○○○○○』책판은 임진왜란 때 최초로 의병을 일으켜 전공을 세운 곽재우의 시문과 연보 및 부록 등을 판각한 것이다. 이 책판은 3차에 걸쳐 내용을 고치고 첨가하여 간행되었는데, 이것은 3차에 해당되는 것으로 영조 47년(1771)에 간행된 것이다. 부록인 ○○○○○은 임진왜란 당시 곽재우가 의령에서 의병을 일으킬 때 함께 참여한 사람들의 명단인 『용미음미록』 과 정유재란 때 곽재우와 함께 창녕의 화왕산입성을 방어했던 경상도 의사들의 명단인 『화왕산성동고록』 및 『화왕수성각』등을 판각한 책판이다.","a":"망우당선생문집책판(부)창의록책판","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636916.jpg"},{"q":"이 건물은 임진왜란 후 이곳 유림들이 고운(孤雲) 최치원(崔致遠)의 정신을 기리고 유생들을 교육하기 위해 건립한 정자이다. 원래 이 정자는 최치원이 가야산 해인사에 기거하면서 자주 왕림하였다고 전하는 봉진 마을 앞 안림천 변에 있었다. 그러나 1920년 대홍수로 일부 훼손된 것을 이 곳으로 이건 중수하였다. ○○○은 신촌리 마을 뒷산인 학산 기슭에 남서향으로 자리잡고 있다. 2단으로 축조된 기단위에 정면 3칸, 측면 2칸의 홑처마 팔작집이다. 평면은 6칸 규모의 넓은 마루로 구성되어있으며, 온돌방은 설치되어 있지 않다.","a":"벽송정","c":"문화유산자료","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662589.jpg"},{"q":"정충각은 임진왜란 때 풍천(豊川) 구담(九潭)에서 의병 700여명을 이끌고 왜군을 방어하다가 전사한 농은(農隱) 이홍인(李洪仁, 1525­1594)에게 내려진 정려(旌閭)를 게시한 건물로 1811년(순조 11)에 건립되었다. ○○○은 이홍인의 8대손인 용눌재(?訥齋) 이한오(李漢伍, 1719­1793)의 효행에대해 내려진 정려를 게시한 건물로 1812년(순조 12)에 건립되었다. 이한오는 전통적인 유가의 후예로서 충과 효가 생활의 기본임을 깨닫고, 오직 효성으로 부모님을 봉양하여 주변의 칭송이 자자하였던 분이다.","a":"예안이씨정충·정효각","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663478.jpg"},{"q":"영은정사는 연안이씨의 집성촌인 웅양면 동호마을에 위치하며 도 문화유산자료인 동호리이씨고가의 아래쪽으로 담장을 공유하는 집으로 1884년 참봉이준학 선생이 차남인 영은 이현석선생에게 분재해 준 집임. 안채와 사랑채 그리고 곳간채의 3동으로 구성되어 있는데, 동서로 긴 장방형의 대지에 대문과 사랑채, 그리고 곳간채를 병렬로 배치하고 사랑채 곳간채 중앙에 두 건물과 직각되게 안채를 배치하였음.","a":"거창영은고택","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665469.jpg"},{"q":"조선후기의 동화백자로 둥글게 성형한 후 동체를 깎아내어 10개의 면으로 구성한 각호(角壺)이다. 구연은 직립하였으며 구연 아래 어깨부분에는 당초문 띠를 둘렀다. 전반적으로 회백색의 어두운 태토에 동화안료로 장식하였는데 동화의 발색이 자줏빛으로 또렷하다. 동체 전면에는 10면에 걸쳐 간격을 맞추어 4곳에 이중 원 권을 두르고 그 안에 새 또는 식물을 그려 장식하였다. 동화의 발색이 좋은 편이며 동체 전면에 시문한 점이 독특하다. 굽은 수직굽이며, 흙물을 바르고 그 위에 모래를 받쳐 구운 흔적이 접지면과 굽바닥에 있다.","a":"백자동화원형문각호","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636467.jpg"},{"q":"본 불상은 ○○○○○ 대웅전의 본존불로 안치되어 있으며, 좌우 협시보살상은 1991년 현재의 대웅전을 신축하면서 새로 조성된 것이다. 별조된 대좌는 후대에 제작된 것으로 대좌는 가운데가 뚫려 비워져 있으며, 그 구멍 아래에는 현대 제작의 축원문을 적은 다량의 다라니가 납입되어 있다. 불상의 상태는 부분적으로 도금과 나발의 채색이 조금씩 벗겨졌을 뿐 전체적으로 매우 양호하다. ○○○○○ 석조여래좌상은 지발과 육계의 경계 없이 완만하게 처리된 머리, 방형의 얼굴, 수평의 승각기 등의 특징을 지니고 있다.","a":"창녕 도성암 석조아미타여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642646.jpg"},{"q":"이 건물은 1789년(정조 13년) ○○○ 선생의 효행을 기리기 위해 세운 ○○○으로 옻골(둔산동)의 마을 안길 우측에 동계를 끼고 서향으로 좌정하고 있다. 서쪽 정면 중앙의 사주문과 마주하여 단칸 규모의 비각을 두고, 주위에 한식 토석담장을 방형으로 둘러 일곽을 형성하였다. 비각은 단칸 규모의 겹처마 맞배집으로 얕은 기단 위에 화강석 다듬돌 초석을 놓고 원주를 세워 벽면을 구성하였는데 벽면의 상부에는 모두 홍살을 설치하였다. 원주 위에는 이익공을 올리고, 창방과 도리 사이는 원형화반을 놓아 장식하였다.","a":"최흥원정려각","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659501.jpg"},{"q":"○○○○은 삼족당 김대유와 소요당 박하담을 모신 서원으로 선조 원년(1567)에 매전면 동산동 운수정에 두분의 위패를 모시고 향현사라 하다가, 선조 10년(1577)에 지금의 위치로 옮기고 ○○○○이라 하였다. 숙종 2년(1676)에 다시 지었으나, 고종 5년(1868) 흥선대원군의 서원철폐령으로 훼철되었다. 지금의 건물들은 고종 15년(1878)에 박하담의 후손들이 다시 지은 것이다. 대문을 들어서면, 안채와 득월정·행랑채가 ㄷ자 형을 이루고 그 뒤쪽으로는 선암서당이 있다.","a":"선암서원","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640377.jpg"},{"q":"조선 숙종∼영조 때 학자 유승현(1680∼1746) 선생의 종택이며 ○○○은 강학의 장소였다. 유승현 선생은 숙종 45년 문과에 급제한 분으로 이인좌의 난 뒤 여러 벼슬을 거쳐 공조참의와 풍기 군수를 역임하였다. 지금 건물은 숙종 36년(1710) 세운 것을 1987년 임하댐 건설로 현재 있는 자리로 옮긴 것이다.","a":"용와종택및침간정","c":"시도민속문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658469.jpg"},{"q":"『광주노씨세보(光州盧氏世譜)』는 조선후기 선남후녀로 기록방식이 바뀌어지기 전의 모습을 잘 보여주고 있으며, 족보로서의 객관적 진실성을 담보하고 있다. 처계(妻系)나 외계(外系) 및 외손(外孫)에 대한 기록의 정밀성 등은 혈연의 계보를 정확하게 기록하려는 전형이라 할 만하며 이 책은 초간본이면서 희귀하여 보존할 가치가 있다.","a":"창녕 동산서당 광산노씨세보","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665320.jpg"},{"q":"남평 문씨의 종가에서 대대로 소장하고 있는 ○○○로, 조선 중기 때의 학자인 모계 ○○ 선생의 교지류, 문집, 필첩 등이다. ○○는 1592년 임진왜란이 일어나자 거창에서 의병을 모아 싸웠으며, 부모가 돌아가시자 거창현 모계리에 터전을 마련하고 10여 년동안 제자들을 가르쳤다. 그후 김우옹, 유성룡 등이 추천하여 동몽교관, 사헌부감찰 등을 지냈으며, 선조가 죽고 광해군이 임금의 자리에 오르자 벼슬을 내놓고 고향으로 돌아가 독서에만 전념하였다. 그가 죽은 후 거창의 용원서원에 모셔졌다. 이것들은 당시 조선의 상황과 남평 문씨 가문의 내역을 알 수 있는 자료이다.","a":"문위 관련 고문서","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642290.jpg"},{"q":"조선시대 배의 수리·보수·군사 물자의 하역·특수 목적 선박 등의 정박을 목적으로 세운 중요한 군사시설로, 방파제와 선착장의 역할을 함께 수행하였다. 조선 세조 8년(1462) 이 고장의 대외 방어 기지로서 ○○○ 수군만호진을 설치할 때 축조하였다. 임진왜란 당시 이순신 함대의 거북선이 정박한 적이 있다고도 하며, 주위에는 ○○○ 진성지, 안골왜성이 있어 국방상 대단히 유서가 깊은 전적지였음을 알 수 있다.","a":"창원 안골포굴강","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655814.jpg"},{"q":"○○○성은 진도군 군내면 녹진리에 있는 ○○○ 정상에서 동남쪽 500m 밑의 허리에 있는 작은 봉우리(67m)에 있는 성이다. 성의 둘레는 460m이며, 서쪽이 동쪽보다 높은 서고동저형(西高東低型)의 테뫼식 해협 ○○○으로 도랑을 판 흙과 막돌을 섞어 쌓고 외벽을 깎아 접근이 어렵도록 되어 있다. ○○○○○은 명량대첩의 역사현장이란 점에서 중요한 의미를 갖는다.","a":"진도망금산관방성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654362.jpg"},{"q":"<○○○○○>은 집안의 족친들을 중심으로 결성된 친지들의 아회 광경을 그리고 아회에서 수창된 시부(詩賦)를 합록(合錄)한 시화첩이다. 표지에 묵서로 ‘○○○○○’이라는 표제가 써 있다. 이 모임의 대표인 괴원주인(槐園主人) 김재중(金在重)이 을묘년 6월 16일에 쓴 ○○○○○서(槐園盛會錄序), 그림 한 장면, 김재긍(金在兢)이 쓴 괴원성회도기(槐園盛會圖記), 남궁순(南宮石舜)의 제괴원성회도기후(題槐園盛會圖記後), 한상린(韓祥麟)이 쓴 괴원승회도설(槐園勝會圖說)이 차례로 수록되어 있다.","a":"괴원성회록","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636542.jpg"},{"q":"요지란 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. ○○○○○ 가마터는 대구면의 청자가마터와 인접한 ○○○ 저수지 동남쪽에 있다. 이곳에서는 고려시대 10세기∼11세기에 걸친 초기 청자가마터 4곳과 고려 토기 가마터 3곳, 조선시대 15세기∼16세기에 걸친 분청사기가마터 3곳이 발견되고 있어, 고려시대에서 조선시대에 이르기까지 다양하게 청자, 토기, 분청사기를 만들었던 곳으로 추정된다. 이곳에서 출토되는 도자기 조각들은 주로 고려 후기에서 조선 전기에 발달했던 선상감문과 인화상감의 흔적이 엿보인다.","a":"강진 삼흥리 도요지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654215.jpg"},{"q":"○○○○○는 북한산 일대 고려 말에서 조선 초기에 이르는 시기에 운영된 가마로서 2011년 학술발굴조사가 이루어져 그 중요성이 입증된 유적이다. 조선 초기 한양을 소비지로 하는 북한산 일대 가마의 전모를 보여주며, 도자 양식사적으로 상감청자에서 ○○○○로 이행하는 도자생산의 변화 양상을 밝혀주며, 경제사적으로 조선시대 관요 성립 이전 서울지역 도자의 수급체계 추적의 단서를 제공하는 중요한 유적이므로 문화유산으로 지정하여 체계적으로 보존 관리할 필요가 있다.","a":"수유동 분청사기 가마터","c":"시도기념물","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1723791.jpg"},{"q":"○○○의 서북쪽 구릉일대에 분포한 대형 돌방무덤들이다. 사벌국에 의해 만들어진 것으로 추정되며, ○○지역에서 형성범위나 규모가 가장 큰 무덤이다. 무덤이 있는 ○○○의 정상부에는 흙과 돌을 섞어 쌓은 ○○○성이 축조되어 있어, 무덤을 만든 세력의 힘을 짐작할 수 있게 해준다. 아마도 그 세력은 사벌국의 중심세력이나 삼국시대 ○○지역의 지방 유지세력에 의해 만들어졌을 가능성이 크다. ○○○ 무덤들은 원삼국시대의 사벌국의 실체와 그 후에 나타난 세력의 실체를 파악하는데 중요한 단서를 제공해주는 곳이다.","a":"상주 병풍산 고분군","c":"시도기념물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654614.jpg"},{"q":"패총은 ‘조개무덤’이라고도 하며, 해안이나 강가에 살던 선사시대인이 버린 조개 껍질이 쌓여 무덤처럼 된 유적이다. 조개껍질이 지닌 석회질로 그 안의 토기, 석기 및 짐승의 뼈 등이 잘 보존되어 있어 고고학적으로 귀중한 연구 자료가 된다. ○○○○○은 2000년 지표조사에서 확인된 유적으로 외황강과 바닷물이 만나, 강물과 바닷물이 섞이는 곳에 분포한다. 유적의 남동쪽에는 ○○○○○과 동일한 시기에 해당하는 울산 세죽유적이 위치하며, 북동쪽에는 조선시대의 수군만호진성(水軍萬戶鎭城)인 개운포성지가 있다.","a":"성암동패총","c":"시도기념물","nc":"","r":"울산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645896.jpg"},{"q":"이 책은 박기현(1864∼1913)이 기록한 필사본으로, 1891년부터 1903년까지 강진, 장흥일대에서 향촌사회의 동향과 박기현과 그의 문인과의 교류를 기록한 것이다. 그 중에서도 특히 1895년 동학농민운동이 발발했을 당시의 동학농민군측과 관군측의 동향 및 전투상황 등을 상세히 기록하고 있다. 이 책은 동학농민운동사에 있어서 매우 중요한 자료이며, 특히 전라남도 서해지역에서의 동학농민운동의 일례를 보여주는 것으로 향토사연구에도 매우 귀중한 가치가 있다고 평가된다.","a":"강진강재일사","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640133.jpg"},{"q":"○○○ 뒷뜰에 놓여 있는 비로, 절의 개창(開創:절을 처음으로 세움)을 기념하기 위해 세운 것이다. 형태는 거북받침돌 위에 비몸을 올리고 용을 새긴 머릿돌을 얹은 모습이다. 비의 앞면에는 비 이름과 비문이 새겨 있는데, 고려 보조국사가 전주 종남산을 지나다가 절터를 잡아놓고 제자들에게 절을 지을 것을 당부하였다는 내용과 보조국사에서 벽암대사에 이르는 스승과 제자의 계보가 주된 내용이다. 뒷면에는 ○○○를 짓는데 참여했던 스님 가운데 한 분이었던 승명의 말을 인용하여 절을 짓게 된 경위 및 벽암대사의 제자와 시주한 사람, 개창 당시 기술자들의 이름을 기록하였다.","a":"송광사사적비","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639370.jpg"},{"q":"○○○○○은 전체높이 20㎝, 폭 12㎝이며, 옷은 양어깨를 다 덮는 통견의에 두 손을 맞잡은 선정인의 수인을 취하고 있다. 통견의에 선정인의 수인을 한 불상은 흔하지 않으며 ○○○라는 출처가 확인되는 점에서 매우 중요한 가치를 지니고 있어 불교미술사 등 학술적 연구의 귀중한 자료로 평가된다.","a":"개심사금동여래좌상","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661564.jpg"},{"q":"○○○는 대승불교에서 호법선신(護法善神)으로 봉안되어 신앙의 대상이 된 신중(神衆)을 알기 쉽게 그림으로 나타낸 예배용 불화이다. 이 ○○○는 ○○○ 성보박물관에 소장되어 있는 신중탱화로서, 비단 바탕에 채색하여 그렸으며, 크기는 155.5㎝×144.8㎝이다. 상태가 양호한 편이나, 상단의 습기에 의한 변색과 하단의 봉으로 연결되는 부분이 일부 파손되었다. 구도는 상단에는 좌우로 2불을 모시고 주위에 천상중을 배치하였으며, 하단의 중앙부에 날개 달린 투구를 쓴 동진보살을 모시고 그 주위에 신장상을 배치하였는데, 화면의 초점은 동진보살로 모아졌다.","a":"양산 통도사 광서16년명 신중도","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664740.jpg"},{"q":"모악리 마을의 도로가에 자리하고 있는 비이다. 비몸돌을 세운 후 지붕돌을 올린 일반적인 모습이며, 비몸 앞면에는 ＇유조선국○○○○○’라는 비의 명칭을 세로로 새겨 놓았다. 1919년 봄 ○○○○ 23대손인 김철이 중국 상하이에서 몰래 입국하여 써 놓았던 비문을, 김광섭이 3·1 만세운동 후 비에 새겨 세워놓은 것이다. 1937년 중·일전쟁 때 일본인 경찰이 이 비를 발견하고는 ‘조선국’이라는 글씨를 망치로 짓이겨 넘어뜨린 후 파묻어 놓았던 것을, 광복 후 김씨문중에서 다시 찾아 이곳에 세웠다.","a":"영산김씨세장비","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662097.jpg"},{"q":"\"정침은 인종(1545년) 때부터 ○○읍 거촌리에 세거한 晩翠堂 邊永淳(1523~)의 4대손 通德郞 邊洙(1631~1698)가 1653년에 건립한 후 1854년에 중수하고 그 뒤 1984년에는 신응수 대목장이 중건하였다. 사당은 만취당 변영순의 3대손 邊有藩(1605~1671)이 숭조 정신을 함양 계승하기 위하여 1653년에 건립한 후 1930년경 일부 수리가 있었으나, 전체적으로는 원래 모습이 잘 남아 있다.","a":"봉화 수온당 고택","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663773.jpg"},{"q":"조선 영조 29년(1753) ○○군수였던 이기중이 ○○천에 돌다리를 만든 후 그 기념으로 세운 비이다. 다리는 ‘○○○’라 이름지었는데, 큰 홍수로 인해 파괴되고 현재는 이 비만 남아 있다. 비는 네모진 받침 위에 길쭉한 직사각형의 비몸을 세웠다. 비문에는 다리를 설치할 때 참여한 사람들과 목공, 토공, 석공의 이름을 새겨놓았다. 다리를 놓은 그 이듬해인 영조 30년(1754)에 이 비를 세웠다.","a":"단양 우화교기사비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638507.jpg"},{"q":"이 병은 외반(外反)된 구연(口緣)과 아래쪽으로 갈수록 양감(量感)이 크게 표현된 전형적인 조선 후기 병인데, 동 시대 같은 유형의 병보다는 기형(器形)이 준수한 편이다. 유태색(釉胎色)도 밝고 투명하며 불순물이 거의 없는 순백의 질감을 보여주고 있다. 무엇보다 이 병의 조형을 돋보이게 하는 것은 표면에 청화(靑畵)로 시문(施文)되어 있는 운용 문양(雲龍 文樣)이라고 할 수 있다. 이들 문양들은 용과 구름, 여의주 등으로 구성되어 있는데, 작은 구름들 사이에서 솟아오르는 용이 측면이 아닌 정면을 응시하고 있는 점이 특히 주목되는 부분이다.","a":"청화백자운룡문병","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590224.png"},{"q":"이 집은 구한말과 일제 초에 국민계몽과 광복운동에 몸바친 백하 김대락(1845∼1915) 선생의 고택으로 사랑채를 확장하여 1907년 이 지역 최초로 근대식 학교인 협동학교를 개교했던 유래가 있는 집이다. 그의 나이 42세 때(1885) 세운 것으로 보이는 옛집이다. 가옥은 앞면 8칸으로 서쪽 4칸은 사랑채이고 동쪽 4칸은 중문간을 비롯한 아래채이다. 사랑채는 막돌로 쌓은 2층 기단 위에 서 있으며, 아래층 기단은 앞쪽으로 3m가량 돌출되어 있는데 협동학교 교사로 쓰기 위해 사랑채를 확장할 때 넓힌 것으로 보인다.","a":"백하구려","c":"시도기념물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654640.jpg"},{"q":"임하리에 남아있는 석탑들 중 가운데에 자리하고 있는 탑으로, 원래 3층이었으나 현재 탑신(塔身)의 2층 지붕돌까지만 남아 있다. 기단부(基壇部)는 아랫부분이 땅 속에 묻혀 맨윗돌만 드러나 있다. 맨윗돌은 윗면에 3단의 괴임을 두고, 밑면에도 2단의 받침을 새겨 두었다. 탑신의 몸돌은 모서리에 기둥 모양을 새겨 놓았고, 지붕돌은 밑면에 4단의 받침을 두었다. 고려시대 전기에 세운 것으로 보이며, 기단 맨윗돌의 양식으로 보아 원래 대규모의 탑이었을 것으로 짐작된다.","a":"안동임하동중앙삼층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662478.jpg"},{"q":"이 곳은 신라시대의 지극한 효자인 손순(孫順)의 유허지이다. 이 곳에 조선말기 학자인 허전(許傳)이 찬술한 비문을 새긴 유허비(遺墟碑)가 있었다고 전한다. 신라 흥덕왕(興德王) 때의 사람인 손순의 효행은 『삼국유사, 三國遺事』에 기록되어 있다.","a":"경주손순유허","c":"시도기념물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654595.jpg"},{"q":"○○○에 서 있는 탑으로, 네모난 2단의 받침돌 위에 3층의 탑신(塔身)을 올렸다. 탑신의 몸돌 크기는 2층까지 거의 줄지 않고, 3층에서 눈에 띄게 줄어 전체적으로 길쭉한 인상을 주고 있다. 지붕돌은 밑면에 3단씩의 받침을 두었으며, 처마는 느리게 곡선을 그리다 네 귀퉁이에서 살짝 위로 들려 있다. 전설에 의하면 이 탑에 기도한 사람은 신의 도움을 받아 소원성취 하였다 하는데, 음력 4월 8일의 부처님 오신날이 되면 기도를 드리고자 찾아온 사람들로 일대 장관을 이루었다고 한다.","a":"창덕암삼층석탑","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661679.jpg"},{"q":"우암 송시열(1607∼1689)이 조선 효종 4년(1653)에 세운 집이다. 송시열은 조선 후기의 문신이며 학자로 55세인 현종 7년(1661)까지 이 집에 살았던 것으로 알려져 있다. 현재 담장도 없이 ㄷ자형 건물 한 채만 남아 있는데 가운데 3칸 중 왼쪽 2칸에 대청마루를 조성하고 나머지 1칸에는 건넌방을 꾸몄다. 대청마루 왼쪽으로는 안방과 윗방, 부엌을 들이고 건넌방 오른쪽으로는 방 2개와 부엌을 들였다.","a":"송자고택","c":"문화유산자료","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659747.jpg"},{"q":"조선초 훌륭한 유학자의 위패를 모시고 제사하며 지방민의 유학교육과 교화를 위하여 청안에 지은 관학기관이다. 언제 지었는지는 정확히 알지 못하지만, 숙종 29년(1703)에 사마소가 지어진 것을 보아 향교는 그 이전에 지었을 것으로 추정된다. 지금의 건물들은 1979년에서 1981년 사이에 해체·복원한 것이다. 공부하는 강당인 명륜당은 앞에 있고, 제사하는 공간인 대성전은 뒤에 있는 전학후묘의 배치를 하였다. 대성전에는 공자를 비롯하여 중국과 우리나라 유학자의 위패를 모시고 있다. 명륜당의 현판은 영조 9년(1733)에 쓰여진 것이라고 전한다.","a":"괴산 청안향교","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638460.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말하며, 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 『대동지지』에 의하면 ○○도에는 가라산 봉수, 가배량에 남망 봉수, 옥포에 옥림산, 지세포에 눌인곶 봉수, 율포에 가을곶 봉수가 있었다고하는데 이중 옥림산 봉수가 현재 ○○○○○를 가리키는 것으로 보인다. ○○○○○는 조선 전기에 설치된 것으로 보이며 3단으로 석축을 쌓고 ○○○를 설치하였다.","a":"거제 옥녀봉 봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655684.jpg"},{"q":"○○○ 장군(1600∼1664)이 남긴 유물로 장군의 군복, 호남육군사령기, 화살통, 고신, 교지 12매, 논시(論示)가 전해진다. 이 유물은 인조, 효종, 현종대 군인의 품계에 수반된 군대와 관련된 자료를 살필 수 있는 중요한 자료이다. ○○○ 장군은 정묘호란 때 세자를 호위하였고, 병자호란 때 남한산성에서 인조를 호위하였다. 효종 때에는 송시열과 함께 북벌에 참여하였고, 삼도수군통제사 겸 경상우도수군절도사에 올랐다.","a":"조필달장군유물","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639525.jpg"},{"q":"살림집과 정자가 언덕 위에 조화롭게 배치된 집으로 1900년대 초에 지었다. 동북쪽이 낮고 서남쪽이 높은 지형을 살려 낮은 곳에 사랑채와 안채를 동서 중심축에 배치하였다. 주거공간의 왼쪽에 연못과 하은정을 그 뒤쪽에는 연파정을 배치하여 자연과 어울리도록 하였다. 안채마당에서 돌계단을 따라 동산에 올라가면 오래된 벗나무에 둘러싸인 하은정과 연파정이 있다. 하은정과 연파정은 1933년에 지은 정자이다. 연파정은 원래 김용학의 아버지 김희수가 할아버지를 위하여 지었는데, 김용학이 아버지를 위하여 하은정을 지으면서 불이나 다시 지었다고 한다.","a":"김용학가옥","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658115.jpg"},{"q":"이 ○○○은 조선 중기의 학자이자 문신인 행정(杏亭) 도형(都衡)의 효행을 기려 건립한 것이다. 도형(1480∼1547)은 본관이 ○○로, 진사를 지낸 도맹녕(導孟寧)의 아들이다. 학문에 전념하여 출세에 뜻을 두지 않아 과거에 응시하지 않았으나, 중종 14년(1519) 조광조(趙光祖) 등이 사림정치를 주도하면서 학행으로 현량과(賢良科)에 천거되어 벼슬길에 나아가 사간원 정언·성균관 전적 등을 역임하였다. 기묘·을사사화 등 두차례의 사화(士禍)에 화를 입었으며, 이후 향리에 물러나 학문에 전심 하였다.","a":"성주 도형정려각","c":"문화유산자료","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663640.jpg"},{"q":"ㅇ 1661년 충재 권벌의 손자이며 광해군대에 군자감정을 지내 석천거사 권래(權來)의 묘소를 수호하기 위하여 장자인 권상충(權尙忠)이 건립한 재사이다. ㅇ 일제강점기인 1920년 권두응의 후손 성재 권상익(權相翊)이 사동 ○○○ 인근에 거처하며 사동 덕천서당에서 강학활동과 함께 유림단 활동을 통해 독립운동을 하였는데, 1919년 제1차 유림단운동인 파리장서에 참여하였으나 무위에 그쳤고, 1920년 이에 굴하지 않고 중국 총통과 대신들에게 전할 제2차 장서를 작성한 독립운동 사적지로 유서 깊은 곳이다.","a":"봉화사동추원재","c":"시도기념물","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654674.jpg"},{"q":"삼국시대 ○○○으로 석실묘, 석곽묘, 목곽묘 등 다양한 묘제(墓制)의 고분이 분포하고 있다. 현재 20여기 이상의 봉토분이 분포하고 있는 것으로 지표조사되었다.","a":"의령 운곡리 고분군","c":"시도기념물","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656806.jpg"},{"q":"○○○ 절내의 외떨어진 곳에 자리하고 있는 비로, ○○○○ 지눌의 행적을 기리고 있다. 지눌은 고려시대의 승려로, 8세에 출가하여 34세에 승과에 합격하였으나, 출세를 멀리하며 선배의 가르침을 받았다. 당시는 선종과 교종의 대립이 심하였는데, 지눌은 교종의 가르침을 무시하지 않으면서 선종의 가르침을 받았으며, 그 일치점을 찾기 위해 노력하였다. 이후 그를 따르는 무리가 많아지자 새로운 장소를 찾아다니다 ○○○에 들어와 머무르게 되었다.","a":"송광사보조국사비","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639931.jpg"},{"q":"○○○에 남아 있는 4기의 사리탑 중의 하나로, 기단(基壇)에서부터 지붕돌에 이르기까지 모두 8각의 평면을 기본으로 삼고 있다. 세부분으로 이루어진 기단은 가운데받침돌을 제외한 아래윗받침돌에 굵은 연꽃무늬를 둘렀다. 기단 위로는 탑신(塔身)의 몸돌을 얹기 전에 납작한 북모양의 돌을 끼워두었는데, 이것의 가운데 불룩한 부분에 꽃송이를 새긴 띠를 둘러 놓았다. 지붕돌은 밑면에 2단의 받침을 두었으며, 처마의 밑선은 수평을 이루고, 윗선은 부드러운 곡선을 그리고 있다.","a":"함양 안국암 승탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641410.jpg"},{"q":"절에서 공양할 때 밥통으로 사용하던 식기의 일종으로, 높이 21㎝, 아가리 지름 44.5㎝, 밑 지름 27.5㎝이다. 그릇 몸통 양옆에는 2개의 손잡이 고리가 달려있으며, 그릇받침에는 명문을 새겨 놓았다. 높이와 아가리 지름의 비례가 전체적으로 안정감을 준다. 그릇의 바깥부분은 두 부분으로 도드리지게 처리해 몸통을 3등분하였다. 받침에 ‘도광 2(5?)년’이라는 명문이 새겨 있어, 조선 순조 때인 1822년 또는 1825년에 만들어진 것으로 보인다. 조선 후기 불교의식의 단면을 살펴볼 수 있는 좋은 자료이다.","a":"범어사 유제 대발","c":"문화유산자료","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659348.jpg"},{"q":"○○○이 위치한 자리는 태조 이성계가 백일기도를 한 후 조선을 건국하고 왕위에 올랐다는 명당지로서 신라시대에는 왕용암, 고려시대에는 수심대, 조선시대에는 ○○○으로 불리웠다 한다. 1889년 평양에서 출생한 정원강은 수도생활을 위해 21세 때인 1910년에 ○○○을 찾았으며, 백옥성 도장에 머물면서 백옥성의 딸과 혼인을 하고, 천단, 정심원·태상전, 산신각, 칠성각, 용궁 등을 연차적으로 건립하여 ○○○ 지역을 재정비하였다.","a":"계룡산삼신당","c":"시도민속문화유산","nc":"","r":"충청남도","s":"계룡시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658273.jpg"},{"q":"※ 문화유산자료 천흥사 동제관음상, 문화유산자료 만일사 금동불은 동일한 불상으로 1984년 5월 17일 오류지정됨에 따라 지정해제 후, 유형문화유산 천안 ○○○○○으로 재지정됨.","a":"천안성거산천성사명금동보살입상","c":"시도유형문화유산","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639283.jpg"},{"q":"고흥 ○○○○○ 및 ○○○ 부도는 조선시대 후기 승려로 사제간인 ○○○과 ○○○의 부도이다. ○○○에는 경내에 팔각원당형 부도 1기, ○○○ 외곽의 계곡 곁에 9기 등 10기의 부도가 있는데, 9기 가운데 ○○○ 부도와 ○○○ 부도는 원 위치로 알려져 온다. ○○○ 부도는 석종형으로 기단부는 방형의 하대석 위로 8각의 복련을 새겼다. 16엽의 연화문으로 화려한 문양이 없어 오히려 소박한 편이다. 그 위에 원형의 홈을 파고 탑신부를 얹었다. 탑신부는 크게 나눠 상대, 하대로 구분되는데, 하대에는 돌아가면서 물고기, 게 등이 조각되었다.","a":"고흥능가사추계당및사영당부도","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640172.jpg"},{"q":"이 영정은 좌안7분면의 바닥가부좌상으로, 양손에 각각 주장자와 염주를 쥐고 측면을 향해 앉아 있다. 문양 없는 상단의 벽면과 돗자리의 이단구도를 배경으로 한 뒤, 인물의 등 뒤로 연부에 화려한 연화당초문계열의 문양이 묘사된 법피를 두른 의자형상을 단순화하고 평면화 시켜 일종의 배경적 역할을 하는 장식품으로 표현하였다. 화면 향좌측에 주지묵서의 화제가 있고 배면에 묵서화기가 있어 이 작품이 1859년,咸豊九年己未七月(함풍구년기미칠월) 조성되었음을 알 수 있다. 화면크기는 가로78.9cm, 120.3cm이다.","a":"대은당 우관 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642999.JPG"},{"q":"조선 선조 때의 유학자이며 의병장인 중봉 조헌(1544～1592)선생의 제사를 위한 건물이다. 원래는 산지기의 기거 용도로 지어졌을 것으로 추측된다. 이 건물의 초창기는 알 수 없으나, 대청의 종도리 장혀에\"煎建築崇禎四壬申十月三日重建 檀紀四千三百三年庚戌三月二十一日午時立柱酉時上梁 庚坐甲向…\"이라는 상량문으로 보아 1812년 창건하고, 1970년에 중수하였음을 알 수 있다. ○○○가 위치한 도농리 주변에는 중봉 조헌 선생 묘소, 중봉 조헌 선생 신도비, 표충사 등 중봉 조헌 선생 관련 유적이 주변에 많이 있다.","a":"옥천 영모재","c":"문화유산자료","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660847.jpg"},{"q":"고려 후기의 학자이자 충절인 조신 선생의 묘이다. 선생의 원래 이름은 사겸이었는데 신돈의 섭정으로 조정이 어지러워지자 벼슬을 버리고 충청남도 부여 임천에 숨어 지내면서 신(愼)으로 바꾸었다. 봉상대부 회양부사를 지냈으며 당대의 학자인 이색·정몽주와도 가까이 지냈다. 그는 조선 태종의 어릴적 스승이기도 하여 태종이 왕위에 오른 후 그의 자손들에게 벼슬을 주며 후대하였다. 묘비는 처음에 후손인 조속(趙涑)이 유적들을 모아 세웠지만 닳은 정도가 심하여 영조 10년(1734)에 다시 세운 것이다. 지금의 비문은 후손 조최수가 글을 짓고 조현명이 글씨를 쓴 것이다.","a":"조신의묘","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661092.jpg"},{"q":"표면에 도금을 베풀었지만 높이 45cm 크기의 아담한 쇠 불상이다. 철은 다루기가 까다롭기 때문인지 조각의 재료로 널리 이용되지는 않았다. ○○○ 철불은 상주 남장사 보광전의 철불좌상과 함께 자취를 감추기 직전에 만들어진 조선 초기 철불의 중요한 예이다. 현재 불상의 양손은 도금을 새로 하면서 나무로 만들어 끼워놓았다. 이 불상은 전체적으로 신체에 비해 얼굴이 지나치게 크고 머리 위의 살상투(肉髻; 인도 사람들이 머리카락을 올려 묶던 상투에서 유래했으며 부처의 크고 높은 지혜를 상징)도 과장되어 조선 초기 불상의 특징을 보인다.","a":"양평상원사철조여래좌상","c":"문화유산자료","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023052614170400.jpg"},{"q":"○○의 본관은 ○○. 자는 주옹(主翁), 호는 어계(漁溪)이다. 그는 34세 되던 해에 진사시(進士試)에 급제하여 태학(太學-지금의 성균관)에서 학문 등에 더욱 주력하던 중 단종 1년에 일어난 계유정란에 격분하여 스스로 귀향하여 홀로 학문증진에 노력하였으며 단종이 유배지에서 사사 당하자 위험을 무릅쓰고 찾아가 시신을 수렴하였다고 전한다. 1489년(성종 20년) 별세하였으며 1698년(숙종 24년) 생육신에 추봉되었다.","a":"함안 조려 묘","c":"시도기념물","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2016012414390400.JPG"},{"q":"이 성은 언제 쌓았는지 정확하게 알 수 없지만 백제 때 만든 것으로 보이며, 현재 둘레 500m 정도가 남아 있다. 조선시대에 성을 보수하여 병사들의 군량미를 저장하였기 때문에 ○○○이라고 불렀다고 한다. 이 산성의 특징은 내성과 외성이 있는 점으로, 내성은 성곽의 동북쪽 모서리에 돌출되어 있는데, 성 안에서는 가장 높은 있어 조망대 구실을 한다. 성곽의 규모는 동변 19m, 북변 37m이며, 동쪽과 북쪽 성벽이 외성벽을 겸하고 있다. 성 안쪽과 구분하는 성 줄기는 남쪽 40m, 서쪽 13m이다.","a":"합미성","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661687.jpg"},{"q":"○○○○○은 다보여래(多寶如來), 묘색신여래(妙色身如來), 광박신여래(廣博身如來), 이포외여래(離怖畏如來), 김로왕여래(甘露王如來) 등 다섯여래를 그린 탱화로, 영가천도 시에 경내에 내어 거는 불화이다. ○○○○의 다섯 불입상의 전체적인 모습이 아주 흡사하다. 견본채색의 족자 형태로 그려졌던 각각의 화심들이 최근 1폭씩의 액자 형태로 개조된 채 재표구 되어져 있다. 화기란(畵記欄)은 원위치를 상실한 채 따로 액자 속에 보관되어 있다. 원 불화의 채색은 은은한 흔적이나 현재는 진하고 조잡한 색채를 군데군데 덧칠해 놓았다.","a":"묘관음사오여래탱","c":"문화유산자료","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659389.jpg"},{"q":"○○○은 고려 말 조선 초의 문관으로 본관은 안동(安東)이다. 장상들과 함께 이성계를 추대해 개국공신(開國功臣) 1등에 봉해졌으며, 상락백(上洛伯)의 작위를 받았다. 1398년 제1차 왕자의 난 때, 백관을 거느리고 대궐에 가 적장(嫡長)을 후사로 세울 것을 요청해 정종의 즉위를 도운 공으로 정사공신(定社功臣) 1등에 책록되었다. 개국공신 중에서는 배극렴(裵克廉) 다음으로 지위가 높았던 고려의 원로 구신(舊臣)이며, 가문이 귀하고 높아 마음이 청고해 이성계가 아꼈다고 한다. ○○○의 묘는 부인 죽산 박씨(竹山朴氏)와 합장된 단분(單墳)이다.","a":"익원공김사형묘역","c":"문화유산자료","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660198.jpg"},{"q":"이 자료는 ○○에 세거해 온 ○○○○○사우인 세덕사와 관련된 고왕록, 전답안, 완문, 입안 등과 ○○○○ 가문에서 ○○해 온 명문, 완문, 입안 등의 18세기 ○○○이다. ○○○○○은 회재 이언적의 동생인 농재 이언활의 4대손인 이강이 경주 양좌동에서 이곳 ○○으로 이거한 이래 300여 년 간 세거해 오고 있으며, 현재 이들 ○○○는 ○○민속전시관에 보관되어 있다.","a":"포항 덕동 여주이씨 문중 소장 고문서","c":"문화유산자료","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663645.jpg"},{"q":"○○○에 소장되어 있는 나무로 만든 ○○○○○패로, 조선시대 불전의 불단 위에 많이 봉안되어져 있던 불교의식구의 하나인 원패이다. 전체적인 형태는 능화형(菱花形) 주연(周緣)을 지닌 몸체 부분을 연꽃무늬 대좌(臺座)에 결구시킨 조선시대 원패의 일반적인 형태를 따르고 있다. ○○○○○석가여래위패(부산광역시 문화유산자료)와 형태가 거의 유사하다.","a":"범어사목조시방삼보자존패","c":"문화유산자료","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659368.jpg"},{"q":"경상북도 청도군 화양읍 ○○○에 있는 불상으로, 불신과 광배(光背)를 하나의 돌에 새겼다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며 그 위에 상투 모양의 머리묶음이 솟아 있다. 얼굴은 친근감을 주는 온유한 인상으로 정면을 똑바로 바라보고 있다. 양 어깨를 감싸고 입은 옷은 몸에 밀착되어 풍만한 신체를 더욱 드러나 보이게 한다. 옷주름은 간결하게 처리하여 표현했으나 부드럽고 아름다워 보인다. 손모양은 오른손은 가슴 위에 얹고 왼손은 아래로 내려 옷자락을 가볍게 잡고 있는 모습이다.","a":"청도합천리석조아미타여래입상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640901.jpg"},{"q":"최정산에 위치한 ○○○는 신라 문무왕 10년(670)에 의상법사가 처음 짓고 옥천사라 이름하였으나, 후에 ○○○로 고쳤다. 여러 차례 다시 지어졌는데, 조선 순조 5년(1805) 의열화주가 다시 지은것이 오늘에 이르고 있다. 처음 지어질 당시에는 3,000여 명의 승려가 도를 닦고 47개의 암자가 소속되어 있을 정도로 큰 규모의 사찰이었다고 한다. 현재는 곳곳에서 그 흔적만을 찾아 볼 수 있다. ○○○○○은 앞면 3칸·옆면 3칸 규모로 못 하나 사용하지 않은 매우 웅장한 건물이며, 기둥이 되는 목재는 아름드리 칡덩굴을 사용하였다.","a":"용천사대웅전","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640957.jpg"},{"q":"1940년대에 지은 집으로 안채·사랑채·행랑채 등을 갖추고 있다. 배치는 앞쪽에 사랑채를 두고 중문을 통해 그 뒤의 안채로 들어가도록 구성하였다. 사랑채는 앞면 4칸 반·옆면 2칸으로 비교적 큰 규모의 건물이다. 앞뒤 칸 밖에 퇴칸을 마련하여 방을 크게 꾸밀 수 있게 하였다. 또한 ㄱ자형의 툇마루를 두어 공간을 넓히는 한편 통로로도 활용할 수 있게 하였다. 안채로 들어가는 구조나 툇마루의 기능을 넓힌 점에서 전통 한옥 건축의 기법과는 다소 차이가 있는 양식을 보이는 집이다.","a":"보은 선병묵 고가","c":"문화유산자료","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660714.jpg"},{"q":"조선 숙종 35년(1709) 정월에 제작된 제주도 지도와 그 서문(序文)이다. 지도는 도면 전체를 3단으로 나누어 상단과 하단에는 제주도의 지리적 상황을 기록하고 가운데에는 지도를 그려 놓았다. 지도는 본토 쪽에서 제주도를 바라보는 것을 가정하여 그린 것으로, 제주도의 남쪽이 지도의 상부가 되어있다. 주요한 오름은 거의 표기하였는데 산 모양의 그림으로 오름의 이름을 대신하고 있으며 포구도 자세하게 기록하고 있다. 주변의 바다를 파도 무늬로 표현하였는데 이러한 바다의 표현법은 조선시대 전기의 표현법을 이은 것이다.","a":"탐라지도및지도병서","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643287.jpg"},{"q":"지석묘(○○○)는 청동기시대의 무덤양식 중 하나로, 주검을 땅 위에 두는 탁자식(북방식)과 땅 아래에 두는 바둑판식(남방식), 그리고 주검을 지하에 묻고 그 위에 덮개돌만을 덮는 개석식의 세 종류가 있다. ○○지석묘는 탁자식 ○○○로, 4면에 널돌을 세우고 그 위로 길고 평평한 덮개돌을 얹은 모습이었는데, 현재는 앞뒷면 널돌은 사라지고 양쪽면에만 널돌이 남아있다. 이곳에서 발견된 유물은 갈돌대, 돌쩌귀, 돌칼, 돌화살촉, 그물추, 구멍쪼으개, 여성을 나타낸 얼굴조각, 토기 등 이다. 주로 식생활에 관련된 유물이 많아 묻힌 사람은 여자였을 것으로 판단된다.","a":"옥천 석탄리 고인돌","c":"시도기념물","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651517.jpg"},{"q":"○○○는 삼년산성 내에 위치한 사찰로 ○○군지에 의하면 1902년 朴鏡荷 스님이 창건하였다. 錦湖堂 若效가 金魚를 맡고 萬聰․法任이 제작한 ○○○〈지장보살도〉는 본존인 지장보살을 중심으로 좌우에 3열의 권속으로 구성되어 있다. 본존은 꽃잎형태의 두․신광을 두르고, 왼손에 투명보주를 쥐고 있으며, 유희좌의 모습이다. 협시로는 화불이 표현된 석장을 든 도명존자와 관모에 경책을 매어 묶은 무독귀왕을 비롯, 十王이 제1·2열에 걸쳐 시위하고 있으며, 제3열에는 童子․童女, 判官, 直府使者, 牛頭羅刹·馬頭羅刹 등이 묘사되어 있다.","a":"보은 보은사 지장시왕도","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638958.jpg"},{"q":"원래 땅 속에 묻혀 있던 것을 밭을 일구다가 발견하였다고 하며 1996년에 보호각을 지어 모시고 있다. 하나의 돌에 불상과 광배(光背)를 새기고 머리는 다른 돌로 새겨 조립하도록 했으나 지금은 없어졌다. 오른손은 가슴에 올리고 왼손은 아래로 내려 물병을 잡고 있다. 배(舟)모양의 타원형 광배는 연꽃무늬를 새긴 머리광배와 불꽃무늬를 새긴 몸광배로 구분된다. 이 석불은 여래상인지 보살상인지 확실하지 않으나 겉옷의 조각 표현과 독립불상인 점으로 보아 여래상으로 추정된다. 불상을 만든 시기는 고려 전기로 보인다.","a":"금릉신안동석불입상","c":"문화유산자료","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662804.jpg"},{"q":"○○○는 전라남도 장흥군 가지산에 있는 절로, 860년 신라의 승려 체징에 의해 창건되었다. 이 책은 ○○○○○의 배안에 넣어서 보관하던 유물 가운데 하나이다. 인도로부터 중국에 전래된 초기의 경전으로 가섭마등과 법란이 공동으로 번역한 것이다. 불교의 방대한 내용을 42장의 요지로 간명하게 나누어 설명한 것으로, ‘불조삼경(佛祖三經)’이라 부르기도 한다. 우리나라에서는 고려 공민왕 10년(1361) 전북특별자치도 전주 원암사에서 간행된 판본과 고려 우왕 10년(1384)에 간행된 것 등 2종이 전하고 있다.","a":"보림사사천왕상복장불설사십이장경","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022813550600.jpg"},{"q":"○○○○에서 인천감리서로 보낸 공문의 부본 12종으로 2종은 1886년, 10종은 1889년에 작성된 것이다. 이 ○○에는 당시 인천세관장 대리 J.F.Schoenicke(한국명：사납기)의 친필서명 및 발송 연월일이 기재되어 있으며, 당시 ＂○○○○ 세무사＂의 직인을 제1면 좌측에 첨부하였다. 이 ○○는 사납기의 친필서명과 서명일시, ○○번호 등 명문이 뚜렷한 보기 드문 자료로서 19c말 인천항 개항시기의 각국 조계지 조성과 관련한 귀중한 가치를 지니고 있으며 아울러 우리나라의 영문표기가 'COREA'로 표기된 것이 눈에 띄는 자료이다.","a":"인천해관 문서","c":"문화유산자료","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001659583.jpg"},{"q":"조선의 군사업무를 담당하던 ○○○의 청사건물이다. 고종 5년(1868)에 덕의당·청헌당과 함께 지어졌다. 원래 광화문 남쪽 현재의 정부종합청사 자리에 있던 것을 ○○○ 청사의 중심이 되는 ○○○만을 1930년대에 지금의 위치로 옮겼다. 앞면 7칸·옆면 4칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 중앙 3칸은 대청이고 양 옆에 1칸의 온돌방이 있으며 그 옆에는 광이 있다. ○○○○○은 조선시대 관아건물로서 희귀한 문화유산이다.","a":"삼군부 총무당","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636122.jpg"},{"q":"○○○○○은 줄여서 ‘법화경’이라고 부르기도 하며 천태종의 근본경전이다. 부처가 되는 길이 누구에게나 열려 있음을 기본사상으로 하고 있으며 화엄경과 함께 우리나라 불교사상의 확립에 가장 크게 영향을 끼쳤으며, 삼국시대 이래 가장 많이 유통된 불교경전이다. 이 책의 판식(板式)은 상하단변(上下單邊), 유계(有界), 상하내향흑어미(上下內向黑魚尾), 10행 17字이며, 전 7권 중 ○○으로 1434년에 주조된 초주갑인자(初鑄甲寅字)로 1457년에 인출(印出)한 선장본(線裝本)이다. 표지는 개장하였으며 판심제(版心題)는 “妙法蓮華經 卷 第三 二”이다.","a":"묘법연화경 권3","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593624.jpg"},{"q":"조선시대 문신이었던 윤효손(1431∼1503) 선생의 묘앞에 서 있는 석등과 석비이다. 석등은 받침돌 위에 불을 밝혀두는 화사석(火舍石)을 올리고 지붕돌을 얹은 모습으로, 전체가 4각을 이루고 있다. 화사석은 네 면마다 불빛이 새어나오도록 작은 창을 뚫어놓았으며, 옛 가옥의 지붕을 본뜬 듯한 지붕돌 위로는 정교하게 조각된 머리장식을 올려 놓았다. 석비는 단을 높직하게 마련하여 거북받침을 올리고, 그 위로 비몸을 세운 뒤 머릿돌을 얹어 마무리 하였다. 돌거북 아래의 높직한 단은 보기드문 모습이며, 용대신 연잎을 조각해놓은 머리돌도 특이하다.","a":"구례윤문효공묘전석등및석비","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639862.jpg"},{"q":"조선 초기 남양만을 거쳐 해안으로 침입하는 왜적을 막기 위하여 바닷가에 있는 두 곳의 얕은 산봉우리를 서로 연결하여 돌로 쌓아 만든 해안산성이다. 왜구의 침입이 잦은 해안 지역에 만호부가 설치되었다는 기록과 연관하여, 이곳에 수군 만호영이 있었으나 갯벌이 밀려 배의 출입이 어려워지자 인천의 영종포로 영을 옮겼다가, 바다가 다시 깊어져 배의 출입이 가능해지자 다시 군영을 두었다는 기록이 있다. 성의 크기는 둘레 1040m, 높이 1.2∼2.1m라는 옛기록이 있지만, 한국전쟁 때 대부분 파괴되었던 것을 1988년 복원하였다.","a":"별망성지","c":"시도기념물","nc":"","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646147.jpg"},{"q":"임진왜란(壬辰倭亂) 진주성 전투에서 전공을 세운 ○○○의 공적을 포상하여 달라고 청원한 진주지역민들의 ○○○과 이를 인정하여 국가에서 공신으로 인정한 선무원종공신녹권(宣武原從功臣錄券)이다. ○○○은 3매이고 공신녹권은 1책(35X21Cm)이다. ○○○은 1593년(선조26) 6월의 진주성 2차 전투에서 수문장(守門將)으로 왜적과 맞서 싸우다가 장렬하게 전사하였는데 묘소는 진주시 문산읍 갈곡리에 있다.","a":"박세항공신록권및상서문","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664642.jpg"},{"q":"이 고장 충신인 백제의 성충·흥수·계백과 고려 후기의 충신 이존오를 위해 부여현감 홍가신이 세운 사당이다. 후에 조선 선조(재위 1567∼1608) 때 선비 정택뢰, 인조 (재위 1623∼1649)때 문신 황일호(1588∼1641)를 추가로 모셔 현재는 6명을 모시고 있는데, 해마다 봄·가을에 제사를 지내고 있다. 조선 선조 8년(1575)에 처음 지어 인조 19년(1641)에 새로 고쳐 지었으며, 고종 3년(1866)에 헐렸다가 그 뒤 다시 지었다. 지금 있는 건물은 원래 용정리의 망월산에 있던 것을 1971년 현 남령공원으로 옮긴 것이다.","a":"의열사","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661077.jpg"},{"q":"수지면 신덕마을 뒤 ○○○ 입구에서 약 6㎞ 정도 올라가면 산 정상이 있고 정상에 있는 묘를 좌측으로 하고 내려서면 높이 5m 내외의 거대한 암벽이 자리하고 있다. 암벽의 하단 약 2.5m 지점에 새겨진 이 마애불은 현재 무릎 이하 부분이 결실되어 정확한 규모는 알 수 없으나 연화좌대를 포함한 불상의 높이는 3.2m, 어깨폭 78㎝, 두부길이 58㎝에 이르는 대형의 ○○○○○이다. 비만형의 얼굴에 장대한 신체는 건장한 체구를 이루고 있으며 눈은 좌우로 치켜 올라간 듯하고 두툼한 코, 꽉 다문 입 등 전체적으로 경직된 표정을 짓고 있다.","a":"견두산마애여래입상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639748.jpg"},{"q":"오리 이원익 정승의 가풍을 이어 가기 위한 노력의 일단을 보여주는 자료이고, 조선시대 중부지역 사족의 가풍의 단면을 보여주는 중요한 자료이다. 오리 이원익의 4세손 ○○○가 1734-1737년에 이르는 4년에 걸쳐 작성하여 종손인 이언수(李彦秀, 1713~1774)에게 준것이다. 내용을 간략히 살펴보면 다음과 같다.","a":"광명 이존도 유서","c":"시도유형문화유산","nc":"","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637806.jpg"},{"q":"○○○ 고분은 서쪽에 태산봉과 동쪽에 있는 구릉 사이에 형성된 곡간평지에 위치하고 있다. 곡간평지의 논 가운데에 우뚝 솟아 있어서 섬처럼 보이는 ○○○○○은 ○○○ 또는 자라뫼·조산 등으로 불리고 있다. 이 고분은 둥근 부분과 네모난 부분을 갖춘 장고분 형태를 하고 있는데 둥근 부분을 북쪽에 두고 남쪽으로 좁고 길게 내민 네모난 부분이 있다. 둥근 부분에 비하여 네모난 부분이 상대적으로 낮고 작게 축조되었는데 네모난 부분의 너비가 좁고 앞이 벌어지지 않아 다른 장고분처럼 허리부분이 형성되어 있지 않다.","a":"영암태간리자라봉고분","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654347.jpg"},{"q":"장대는 지휘하는 사람이 올라서서 명령하는 대를 가리킨다. 진주시 남성동에 있는 이 장대는 ○○○ 서문에 속하는 곳이다. 『여지도서』에 보면 회룡루로 나오며, 규모는 작으나 ○○○의 남장대인 촉석루와 같은 다락집형이었다고 기록되어 있다. 지금의 건물은 허물어진 것을 1934년 서상필씨가 새롭게 고쳐지은 것으로, 앞면 3칸·옆면 2칸의 여덟 팔(八)자 모양의 팔작지붕으로 목조 기와집이다.","a":"진주성 서장대","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663791.jpg"},{"q":"○○○는 임진왜란 때 세운 공으로 공신에 오른 이계정(1542∼1596)을 위시한 이숙형, 이황, 이대행, 이호, 이순, 이원해, 이준, 이성춘 등 원주 이씨 문중 9명의 충신을 모시고 제사지내는 사우(祠宇)로, 영조 8년(1732)에 설립되었다. 이곳에 소장되어 있는 문서중에서, 전라남도 문화유산자료로 지정된 문서목록에는 이계정이 충청수사로 임명된 후 선조가 내린 밀부와 밀지(유지)인 「선조밀부유지」와, 이계정이 충청수사로서 군비, 군량 등을 운영하는 것에 대해 선조임금으로부터 지시받은 내용을 적은 임진왜란 중 군사관련 유지 등이 있다.","a":"영산사소장문서일괄","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662133.jpg"},{"q":"조선 후기의 문신이며 암행어사로 유명했던 기은(耆隱) 박문수(1691∼1756)의 묘소이다. 경종 3년(1723) 문과에 급제하여 여러 벼슬을 지냈으며, 영조 4년(1728) 이인좌의 난이 일어나자 오명항의 종사관으로 출전하여 난을 평정한 공으로 영성군에 봉해졌다. 영조 5년(1729) 영남절도사로 있을 때 함경도지방에 수재가 있을 것을 미리 예상하고 영남 제민창에 있던 조 3천석을 보내어 10여 고을의 수재민을 구하였으므로 후에 함흥 만세교 옆에 북민비라는 송덕비가 세워졌다.","a":"박문수묘","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661315.jpg"},{"q":"천방사터에 서 있는 석탑으로, 1층의 기단(基壇) 위에 5층의 탑신(塔身)을 올려놓았다. 기단의 네면에는 모서리마다 기둥모양을 본 떠 새겼는데, 그 위의 맨윗돌은 마치 탑신의 지붕돌과 그 모습이 비슷하여 시선을 모은다. 즉 밑면에는 3단의 받침을 두었고, 네 귀퉁이는 약하게 들려 있으며, 경사가 급한 윗면의 네모서리가 굵게 표현되어 있다. 탑신부의 다섯 몸돌에는 기단에서처럼 모서리에 기둥조각을 두었고, 지붕돌은 밑면에 3단의 받침을 두었다. 전체적으로 불안정한 비례를 보이고 있어, 고려말·조선초에 세운 탑으로 보인다.","a":"장성 내계리 오층석탑","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639996.jpg"},{"q":"○○○○○는 조선 숙종 14년(1688)에 세운 것으로 ○○○ 경내의 선방건물 뒤편 언덕 아래에 있는데 사각형 지대석 위에 복련(伏蓮)이 조각된 화강암 비좌(碑座)를 놓고 높이 177cm, 너비 90cm, 38.5cm의 대리석 비신(碑身)을 세우고, 팔작지붕 모양의 비관(碑冠)을 얹었다.비문은 4면에 모두 새겨있는데 정면에 있는 본문과 이어지는 문장이 아니며, 좌·우측면의 내용은 뒷면의 시주자 명단의 연속으로 보이나, 시주시기가 서로 다른 이들을 추가로 새긴 것으로 보인다.","a":"괴산 공림사 사적비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638762.jpg"},{"q":"야옹 전응방(1491∼1554)이 조선 선조(재위 1567∼1608) 때 세운 정자로 도덕과 학문을 강의하고 토론하던 곳이다. 전응방은 중종 때 진사에 급제하였으나 단종 때 왕위찬탈의 추함을 몸소 겪은 할아버지 휴계 전희철의 유언을 받들어 관직에 뜻을 버리고 산수 좋은 이곳에 ○○○을 세워 도덕과 학문을 수련하였으며, 퇴계 이황과 자주 만나 도학을 강론하였다. 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 현판은 퇴계 이황이 직접 쓴 것이다.","a":"봉화 야옹정","c":"시도민속문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659001.jpg"},{"q":"이 지도는 전주부성 안를 중심으로 전주부 내의 전역을 그린 대형지도로서 4폭의 병풍식으로 되어 있다. 지도에는 성의 표시와 성문 그리고 관아의 배치․향교․서원․수목 등이 그려져 있고, 성 밖은 산천의 지형을 옛날 방식으로 그렸으며 각 면의 이름을 써 붙였다. 지도의 귀퉁이에는 전주부의 사방거리와 이웃 고을로부터의 거리를 표시하고 있고, 전주부내 4면의 원호(元戶) 3,783호, 전주부 외 각 면의 원호 12,215호 등 총 31개 면에 원호 15,998호를 정확하게 밝혀두고 있다.","a":"전주부지도","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639481.jpg"},{"q":"○○○○○ 고가는 ○○시 상당구 낭성면에 조선 후기 ○○○ 신후(申逅, 1708〜1779)가 지은 전통한옥이다. 낮은 야산 앞에 자리 잡고 있는 남향집으로 집 앞으로는 넓은 논과 밭이 펼쳐져 있다. 고가로 들어가는 입구에 사랑채가 있고 그 뒤로 행랑채와 안채가 일곽을 이루며 배치되어 있다. 안채와 행랑채 사이 동쪽에 신축된 건물은 생활을 위해 축조되어 전체적으로 □자 배치를 하고 있다. 앞쪽의 사랑채는 정면 6칸, 측면 2칸의 一자형 평면을 이루고 있다.","a":"청주 과필헌","c":"시도민속문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658210.jpg"},{"q":"목포지역은 예부터 내륙과 해상을 연결하는 군사상의 요충지였는데, 목포진은 조선시대 수군의 진영으로 목포영, 목포대라고 부른다. 조선 왕조 때 각 도의 여러 진에 붙은 종 4품의 무관인 만호가 배치되었다고 해서 만호영, 만호진, 만호청이라고 부르기도 한다. 여러 기록을 통해서 볼 때 조선 세종 15년(1433)에 목포병선을 황원(현재 해남)으로 옮기고, 세종 21년(1439)에 현재의 자리에 목포 만호진을 설치하였으며, 개항과 함께 고종 21년(1895)에 폐진된 것으로 보인다. 현재 목포 만호진의 성이나 유적은 거의 남아있지 않다.","a":"목포진지","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662089.jpg"},{"q":"○○○은 仁祖反正의 주역인 延平府院君 이귀(李貴, 1557~1633)의 次子이자 延陽府院君 이시백(李時白, 1581~1660)의 동생이다. 현재 ○○○의 ○○화는 보물로 지정된 흑단령포본 전신상이 남아있으며, 본 ‘○○○○○’에는 흑단령포본 반신상과 유지초본, 시복본 노년상과 초본 2점, ○○화를 보관했던 목제 함(函) 및 ○○화 족자틀을 감싸 보관했던 보(褓)가 포함되어 있다. 흑단령포를 입고 있는 반신상은 전신상과 비교하여 화격은 다소 떨어지나 거의 같은 모습이며 화면의 상단의 화제를 보면 영의정으로 추증된 후에 그려진 것으로 보인다.","a":"이시방 초상 일괄","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023062713223200.jpg"},{"q":"◦ 통일신라 때 만들어진 것으로 ○○○의 금당에 오르는 돌계단임. ◦ 이 ○○○ 양쪽에는 돌사자상 조각되어 세워져 있었는데 그 조각 수법이 아주 뛰어났으나 이것은 1986년도 도난당하였고, 2013년 중심사역 정비 시 복원하여 재설치 하였음.","a":"성주사지석계단","c":"문화유산자료","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661125.jpg"},{"q":"흥녕사는 자장율사가 세웠다고 전해지며, 선종 9산문 중의 하나인 사자산문의 징효대사에 의하여 크게 번창하였다. 그후 진성여왕 4년(891)에 전쟁으로 불에 타 없어져 고려 혜종 원년(943)에 다시 세웠으나, 계속되는 재해로 폐허가 되고 현재는 ○○○만 남아있다. 전해오는 이야기에 의하면 ○○○○○의 길을 가리키는 3개의 안내 석탑과 1개의 불상이 있었다고 한다. 석탑은 충북 제천시 장락에 있는 석탑과 무릉리의 삼층석탑, 주천리의 삼층석탑이고, 입구 옆에 있는 돌에 새긴 마애여래좌상은 흥녕사의 수호불이라고 전해진다.","a":"영월 흥녕선원지","c":"시도기념물","nc":"","r":"강원특별자치도","s":"영월군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647663.jpg"},{"q":"교지는 임금이 신하에게 어떤 사실이나 명령을 전할 때 내리는 문서이다. 이것은 조선 세종 20년(1438) ○○○이 식년시 문과에 급제하였음을 알리는 교지로서, ○○○의 18세손의 집에 소장되어 온 것이다. ○○○은 강릉 사람으로 세종 20년 문과에 합격하여 영흥판관을 지냈으며, 부모를 봉양하기 위해 고향에 돌아와 강릉향교를 중건하는 등 선행이 뛰어났다. 교지의 종이질은 닥나무종이로 크기는 가로 64㎝, 세로 78㎝이다.","a":"박중신문과급제교지","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638154.jpg"},{"q":"조선 순조 32년(1832) ○○○감 이영모가 세운 ○○건물로 지방업무를 보던 곳이다. 중심건물인 동헌을 중심으로 왼쪽에는 조정에서 파견된 관리들의 숙소였던 객사, 오른쪽에는 군령을 출납하는 사령청, 앞쪽에는 말을 사육하는 마방과 지방의 형사를 담당하는 형방소 등의 부속건물이 같이 있다. 동헌은 앞면 7칸·옆면 3칸의 ㅡ자형 건물이며 객사는 앞면 11칸·옆면 3칸의 건물이었으나, 1985년 불이나 객사는 건물 기단만이 남아있고 동헌은 여러 차례 보수가 있었다.","a":"창원 진해현 관아 및 객사유지","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642031.jpg"},{"q":"○○○은 송은 송형구(松隱 宋亨久, 1598~1675)가 관직에서 은퇴한 1664년(현종5)에 학문 연마와 향촌사림과의 교유를 목적으로 창건한 정자이다.","a":"안동 송은정","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663520.jpg"},{"q":"전북특별자치도 완주군 소양면 ○○○의 나한전에 모셔진 불상으로, 삼존상 3구, 16○○○, 500○○○, 제석상 1구, 동자상 2구, 인왕상 2구, 사자상 2구 등 모두 526구이다. 본존불은 나무로 만든 연꽃무늬 대좌(臺座) 위에 놓여 있는데, 얼굴은 원만한 편이며 양쪽 귀는 짧게 표현되어 있다. 정제된 얼굴 표현에서는 근엄함과 자비로움이 느껴진다. 양 어깨를 감싸고 입은 옷에는 두꺼운 옷주름이 새겨져 있고, 왼쪽 어깨에서 내려진 옷주름은 왼쪽 팔에 걸쳐 무릎을 덮고 있다. 오른손은 무릎 위에 가볍게 얹어놓았고 왼손은 손끝이 땅을 향하고 있다.","a":"송광사오백나한상 일괄","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2016090818022200.jpg"},{"q":"반남 박씨의 가옥 중에 하나로 증언에 따르면 1923년경 지었다고 한다. 이 집은 원래 기와와 초가가 섞여 있는 ○○○의 주택 구성 중에 초가 까치구멍집이었으나 1975년 지붕개량사업 당시 기와집으로 바꾸었다. 앞면 3칸·옆면 2칸 규모의 까치구멍집으로 비교적 작은 집이다. 집 구성은 앞쪽에 사랑방·봉당·부엌이 있으며, 뒤쪽에는 윗방·마루·안방을 배치하였다. 이 집의 특징은 일반적으로 마구간이 있어야 할 자리에 사랑방이 있고, 사랑방 앞면과 옆면, 상방 옆면에 외부로 통하는 문을 설치하여 개방성을 주고 있다는 점이다.","a":"영주수도리박천립가옥","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663215.jpg"},{"q":"○○○란 선사시대 사람들이 바위나 동굴벽에 기호나 물건, 동물 등의 그림을 새겨놓은 것을 말하는데, 주로 농사의 풍요와 생산을 기원하는 주술행위의 결과물로 보인다. 이 ○○○는 땅위에 돌출되어 있는 높이 2m 정도 되는 자그마한 암석에 새겨 놓은 것이다. 면 전체에 새겨놓은 12점의 그림은 추상적인 형태를 하고 있는데, 긋거나 파내는 방식이 아닌 쪼아서 만드는 방식을 사용하고 있다.","a":"경주안심리암각화","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663122.jpg"},{"q":"고려후기에 청동으로 조성된 불교조각상으로,경남지역에서 조사된것은 이번이 처음의 사례이다.보관이 결실된 상태이지만 고려후기의 자비로운 미소를 띤 상호라든가 화려한 영락장식 등을 살펴볼 수 있는 귀중한 유물이며 보살좌상의 크기는 전고(全高)74㎝,두고(頭高)21㎝, 미폭(眉幅)28㎝,구폭(朐幅)20㎝,슬폭(膝幅)53㎝,슬고(膝高)13㎝있다.","a":"합천 해인사 고불암 동조보살좌상","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666687.jpg"},{"q":"머리는 나발(螺髮)이고 육계(肉髻)가 솟았다. 얼굴은 둥글고 귀가 상대적으로 크고 이목구비(耳目口鼻)가 거의 남지 않았으며, 어깨는 좁고 밑으로 흘러 내려졌다. 수인(手印)은 시무외․여원인(施無畏․與願印)으로 오른손이 들려있고 손 부분은 파손되었으며, 왼손은 내려져 있으며 손끝이 뭉특하다. 법의는 통견이고 옷주름은 U자형으로 목부터 다리 발목부위까지 주름이 있다. 좌대는 입상 바로 아래 앙련(仰蓮)이 작게 조각되었고, 그 밑에 복련(覆蓮) 8면이 크게 조각되어 있고, 맨 밑에 8화형 받침이 있으며, 좌대는 밑부분이 뚫려있다.","a":"강릉 청학사 소장 청동불입상","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660652.jpg"},{"q":"○○○○대세지보살상은 17세기 말 18 세기 초 경에 조성된 목(木)보살 양식을 보여주는 전형적인 ○○○○○으로, 현재 ○○○ 극락보전(極樂寶殿)에 아미타불(阿彌陀佛)의 오른쪽 협시보살(脇侍菩薩)로 봉안되어 있다. 전해지는 말에 따르면 충남 공주에 있는 마곡사의 한 암자에서 모셔 왔다고 한다. 이 보살상은 머리에 화려한 보관(寶冠)을 쓴 채 두 손으로는 길게 연꽃가지를 들고 결가부좌(結跏趺坐)하고 있는데, 신체에 비하여 보관을 쓴 머리 부분(頭部)이 다소 큰 편이다. 머리는 머리카락을 위로 모아 상투식으로 묶었다.","a":"팔정사 목 보살좌상(대세지보살)","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590566.png"},{"q":"○○○은 조선조 성종의 12남인 무산군의 손자이다. 나라에 공이 있어 순평군(順平君)에 봉해졌으며 그의 부인은 현부인에 올랐다. 부평 동면(현 동양동)에 낙향하여 정착하였는데, 그의 아들 이필혐은 동양동에서 출생하여 벼슬길에 올라 한성판관을 지냈다. 병자호란이 일어나자 가족이 강화도로 피난을 갔을 때, 청나라 군사가 강화도에 상륙하여 닥치는 대로 양민을 학살하자 현부인 엄 씨는 적군에 잡혀 욕을 보이느니 스스로 죽음을 택했다. 그러자 그의 자부인 이필혐의 처 구 씨도 어린 여자종의 치마폭에 유서를 써넣고 시어머니의 뒤를 따라 자결하고 말았다.","a":"이선봉 묘역","c":"시도기념물","nc":"","r":"인천광역시","s":"계양구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645690.jpg"},{"q":"○○○는 조선시대 문신 휴계공 전희철 선생을 추모하기 위해 세운 건물로 인조 9년(1631)에 지었고 ○○○○는 선조 9년(1576)에 지었다고 한다. 그러나 재사(齋舍)의 경우, 건물에서 발견한 기록문에 따라 숙종 22∼23년(1696∼1697) 사이에 지은 것으로 추정한다. ○○○는 앞쪽에 툇마루와 난간을 두어 누각형식으로 꾸민 건물이다. 지붕은 옆면에서 볼 때 지붕선이 여덟 팔자 모양과 비슷한 팔작지붕이며 앞면 4칸 중 가운데 2칸이 대청이다. 양쪽 끝 칸은 대청으로 연결된 마루 1칸과 반칸짜리 온돌방을 만들어 놓았다.","a":"칠성루및휴계재사","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640626.jpg"},{"q":"이 영정(○○○○○영정)은 좌안7분면의 전신교의가부좌상으로, 팔걸이가 부착된 의자에 가부좌를 하고 있으며 양손에 각각 염주와 주장자를 들고 있다. 전신교의가부좌상은 교의좌상에서 바닥가부좌상으로 변모하는 중간과정으로 파악되는데 특히 이 영정은 화면에 의자의 다리가 잘린 채 표현되는 독특한 형식을 보여준다. 화면 향우측에는 주지백서의 ‘선교양종○○○대선사지진(禪敎兩宗友雲堂大禪師之眞)’ 화제가, 향좌측에는 역시 주지백서의 영찬이 기록되어 있다. 화면크기는 가로 82.1cm, 세로124.2cm이다.","a":"우운당 진희 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642985.jpg"},{"q":"○○○는 조선시대에 군사훈련 지휘소가 있던 곳으로, ○○○도들의 목을 베던 처형장이었다. 당시엔 숲이 칙칙하게 우거져 “숲머리” 혹은 “○○○”라 불렀다. 1801년 ｢신유박해｣ 때, 전라도의 첫 ○○○ 사도 유항검(아우구스티노)의 아내와 제수, 맏며느리 이순이(루갈다) 등이 이곳에서 순교했다. 1839년 ｢기해박해｣ 때는, 신태보(베드로), 이태권(베드로), 이일언(욥), 정태봉(바오로) 등이 순교했다. 1866년 ｢병인박해｣ 때는 경문호(바르톨로메오), 손선지(베드로), 한재권(요셉), 조화서(베드로), 이명서(베드로) 등이 순교했다.","a":"숲정이<천주교순교지>","c":"시도기념물","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653565.jpg"},{"q":"○○○내에 자리하고 있는 석탑으로, ‘청량사(남매탑이 있는 곳)’라는 암자에서 이곳으로 옮겨 놓은 것이다. 1층 기단(基壇) 위로 3층의 탑신(塔身)을 올린 모습인데, 탑신부의 3층 몸돌은 없어진 상태이다. 기단의 맨 윗돌은 탑신의 지붕돌과 같이 윗면에 비스듬한 경사를 두었다. 탑신의 각 몸돌에는 모서리마다 기둥 모양을 본떠 새겼으며, 적당한 경사가 흐르는 지붕돌은 밑면에 5단씩의 받침을 새겨 놓았다. 규모가 작은 탑으로, 통일신라 선덕왕 23년(723) ○○○를 처음 지을 때 함께 세워두었다 하나, 탑의 양식이나 다듬은 솜씨로 보아 고려시대의 작품으로 보인다.","a":"동학사삼층석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660966.jpg"},{"q":"○○○는 연화산 기슭에 있는 절로 신라 문무왕 16년(676)에 의상이 지었으며, 임진왜란 때 불에 타 없어진 것을 인조 17년(1639)에 다시 지었다. ○○○○○은 절의 중심에 있는 법당으로 석가모니를 모시는 건물이다. 임진왜란 때 불타 없어진 것을 효종 8년(1657)에 용성화상이 다시 지었으며, 그 후에 여러 차례의 수리를 거쳐 오늘에 이르고 있다. 앞면 3칸·옆면 2칸으로 1층이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포계 양식이다.","a":"고성 옥천사 대웅전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641690.jpg"},{"q":"봉선에는 1791년 하진태의 어머님이 병이 위독해지자 하진태를 비롯한 가족들이 간병하는 상황 을 10월 16일에서 11월 16일까지 기록하고 있는데 \"조모주병록일기(祖母主病錄日記)\"라하여 하진태(河秦兌)의 아들 익범(益範)이 기록한 것이다. 이러한 ○○ 뒤에 ○○추천 수본(手本) 서목(書目) 상서문(上書文)은 전부 30점으로 그 ○○을 표창해 줄 것을 요로에 요청하는 인근 사림들의 움직임을 살펴볼 수 있는 자료이다. 시기상으로는 1791년에서 19세기 후반에 걸쳐 작성되었다.","a":"진주 담산고택 효행 관련 문헌","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642419.jpg"},{"q":"조선 광해군 5년(1613)에 해남현감 정호례가 지은 주택이다. 정호례는 임진왜란(1592) 때 의병을 일으켜 영천에 침입한 왜병을 격퇴하는 등 많은 전공을 세운 의병장 정세아의 장손이다. 工자 모양으로 지은 전통적인 양식의 건물이며, 이 건물 북쪽에 정세아의 위패를 모신 환고사가 있다.","a":"호수종택","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640419.jpg"},{"q":"탑동 마을 어귀에 있는 밭 가운데에 자리하고 있는 탑으로, 뒤로는 종산(鍾山)이 펼쳐져 배경을 이룬다. 원래 이곳은 옛 부터 ○○○라는 절이 있었다 하나, 지금은 없어지고 이 탑만 남아있다. 탑은 전체의 무게를 지탱하는 기단(基壇)을 2층으로 두고, 3층의 탑신(塔身)을 올려놓은 모습인데, 일부가 떨어져 나가 시멘트로 발라놓는 등 보존상태가 좋지 않다. 기단은 네 모서리마다 별도의 돌을 다듬어 기둥처럼 세워 이 탑의 가장 큰 특징이 되고 있다. 탑신부는 2매의 돌로 이루어진 1층 몸돌을 제외하고는 각 층의 몸돌과 지붕돌이 각각 하나의 돌로 되어 있다.","a":"한산사지삼층석탑","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661997.jpg"},{"q":"현재 경상남도 ○○시 ○○○ 삼현여자고등학교에 있는 석조상으로, 높이는 1.65m, 대좌까지의 높이는 2.7m이다. 머리 부분은 마멸이 심해서 정확한 형태를 알 수 없으나, 정수리 부분에 솟아 오른 상투 모양의 머리묶음이 눈에 띈다. 목에는 3줄의 주름인 삼도(三道)가 있으며, 몸통에는 U자형의 옷주름이 새겨져 있다. 8각형의 대좌(臺座) 위에 서 있는 이 불상은 대좌와 원래의 짝이 아닌 듯하며, 여러 특징으로 보아 고려시대에 만든 것으로 추정된다.","a":"진주 상평동 석조여래입상","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664585.jpg"},{"q":"조선 전기의 문신인 우졸재 ○○○ 선생의 공을 기리고자 세운 비이다. ○○○는 김종직의 문인으로 성종 16년(1485) 문과에 급제하여 벼슬길에 오른 뒤 한성부참군, 사헌부감찰, 성균관전적 등을 지내다 부모님을 모시기 위해 스스로 청하여 창녕현감으로 내려왔다. 현감으로 있으면서 어진 다스림을 펼쳐 임금이 비단과 교서로서 포상하였다. 무오사화(1498)가 일어나자 붕당을 지어 국정을 비방하였다는 죄로 벽동으로 유배되었고, 갑자사화(1504)로 인해 처형 당하였다. 중종반정(1506) 후에 억울한 죄명에서 풀려나 도승지로 추증되었다.","a":"함안 박한주 여표비","c":"문화유산자료","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664535.jpg"},{"q":"원래 심적사는 ○○읍 내리에 있었던 절로서, 통일신라 말기인 929년(경순왕3)에 세웠다고 하지만 세운 사람이나 그 이후의 내력에 대해서는 알려진 바가 없다. 이곳의 ○○○○○은 원래 심적사에 있었던 것이다. 그러나 한국 전쟁 때 이 절이 불에 타버리는 바람에 동봉(東峰)스님이 이 불상을 삼봉산(三峰山)의 동룡굴에 잠시 모셔두었다. ○○○○가 지리에 재건되고 나한전을 세우면서 이 불상을 다시 이곳으로 옮겨와 봉안하였다. 원래는 22기의 불상이 있었는데, 1기는 한국 전쟁 때 분실되었다고 한다.","a":"산청 심적정사 석조불상군","c":"시도유형문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2015121616001900.jpg"},{"q":"○○○와 ○○○는 분성 배씨의 시조 배지타를 비롯하여 부·현경·우·승고·원룡 및 맹후·명원·형원·일장 공을 제사지내는 곳이다. ○○○는 조선 중종 32년(1537)에 상정에 지었으나 무너져서 1948년 현위치로 옮겼다. 앞면 3칸·옆면 2칸으로 지붕옆면이 사람 인(人)자 모양인 맞배 지붕이며 앞면에 다른 기둥을 세워 트여있는 공간을 만들었다. 조선 숙종 1년(1675)에 명곡에 명곡서원을 지었으나 고종 때 서원철폐령으로 인해 헐리었다. 1938년에 상정에 ○○○로 다시 지었으며, 1948년에 지금의 위치로 옮겼다.","a":"합천 추본사·명곡사","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642094.jpg"},{"q":"돈대는 해안가나 접경 지역에 쌓은 소규모 관측·방어시설이다. 병사들이 돈대 안에서 경계근무를 서며 외적의 척후 활동을 비롯한 각종 수상한 정황을 살피고 대처한다. 적이 침략할 때는 돈대 안에 비치된 무기로 방어전을 펼친다. 1679년(숙종 5) 5월에 완성된 48돈대에 이후 5개 돈대가 추가로 지어졌다. 48돈대는 황해도·강원도·함경도 승군 8,900명과 어영청 소속 어영군 4,262명이 80일 정도 걸려서 쌓았다. 돈대 축조를 기획하고 감독한 이는 병조판서 김석주였고 실무 총괄은 ○○유수 윤이제였다.","a":"강화 화도돈대","c":"문화유산자료","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001659580.jpg"},{"q":"청평사는 고려 광종 24년(973)에 지어져 ‘백암선원’이라 부르던 유서깊은 사찰이다. 그후에 보현원, 문수원으로 불려오다 조선 명종 때 보우선사가 크게 고쳐 지으면서 이름을 청평사로 변경해 오늘에 이르고 있다. 오랜 세월과 한국전쟁으로 인해 문수원기비와 국보였던 극락전 등이 불타 없어졌으며, 현재의 극락전은 최근에 다시 지은 것이다. 남아 있는 유물로는 회전문(보물), 삼층석탑, 진락공 부도, 환숙당 부도 등이 있다. 또한 고려시대에 관직에 있던 이자현이 벼슬을 버리고 숨어 지내던 문수원과 영지가 남아 있는데, 이곳은 고려시대의 정원을 알 수 있는 중요한 유적이다.","a":"청평사지","c":"시도기념물","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648211.jpg"},{"q":"제주의 마을에는 '본향당' 이라 해서 마을의 중심이 되는 신앙처가 있다. ○○○○○은 제주시 조천읍 와흘리마을 입구에 위치하고 있는데, 이 마을 본향당 제는 과거 제주마을제의 모습이 그대로 잘 남아 있어 많은 사람들이 답사하고 있는 곳이기고 하다. 지금은 마을제가 유교식 포제로 많이 바뀌어 버렸지만, 제주의 옛 기록을 보면 '제주 사람들은 본향당에 모두 모여 남녀가 춤을 추고 음식을 먹으며 마을제를 지낸다'고 했다.","a":"와흘본향당","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659286.jpg"},{"q":"○○○○는 살아 있는 화석이라 할 만큼 오래된 나무로 우리나라, 일본, 중국 등지에 분포하고 있다. 우리나라에는 중국에서 유교와 불교가 전해질 때 같이 들어온 것으로 전해지고 있다. 가을 단풍이 매우 아름답고 병충해가 없으며 넓고 짙은 그늘을 제공한다는 장점이 있어 정자나무 또는 가로수로도 많이 심는다. ○○○의 ○○○○는 낙안읍성민속마을로부터 남쪽으로 조금 떨어진 낙안향교 안에 자리하고 있다. 낙안향교는 원해 성의 동쪽 농암등에 있었는데 효종 9년(1658)경에 이곳으로 옮긴 후 여러 차례 고쳐 지어 오늘에 이르고 있다.","a":"낙안교촌리은행나무","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654340.jpg"},{"q":"도천서원에 모시고 있던 청향당 이원과 죽각 이광우를 따로 모시기 위해 세운 서원이다. 이원(1501∼1568)은 벼슬이나 과거에 뜻을 두지 않고 학문연구를 한 조선 전기의 학자이다. 그는 조식·이황 선생과 학문의 뜻을 같이 하였으며, 명종 1년(1546)에는 나라에서 벼슬을 내렸으나 거절하고 학문에만 전념하였다. ○○○○은 조선 영조 47년(1771)에 덕연사만 세워 위패를 모셨으나, 흥선대원군의 서원철폐령으로 고종 5년(1868)에 철거되었다. 그 뒤 1919년에 새로 지어 ○○○당이라 하였다. 서원 안에는 문묘, 도동사, 강당이 있다.","a":"산청 배산서원","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663912.jpg"},{"q":"○○○는 대승불교에서 호법선신(護法善神)으로 봉안되어 신앙의 대상이 된 신중(神衆)을 알기 쉽게 그림으로 나타낸 예배용 불화이다. 이 ○○○는 ○○○ 성보박물관에 소장되어 있는 신중탱화로서, 비단 바탕에 채색하여 그렸으며, 크기는 168.2㎝×153.0㎝이다. 구도가 다른 ○○○와는 차이를 보이고 있는데, 상단은 마치 왼쪽 일부가 잘려 나간 것처럼 왼쪽으로 치우친 제석천을 중심으로 좌우에 천상중을 배치하였으며, 오른쪽 한편에 동진보살을 배치하였고, 하단에 신중상을 배치하여 화면의 초점이 좌측의 제석천을 중심으로 조성되었다.","a":"양산 통도사 광서19년명 신중도","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664737.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 고려 공민왕(재위 1351∼1374) 때 지었고, 조선 명종(재위 1545∼1567) 때 다시 지었으나, 임진왜란 때 불타 없어졌다. 광해군 7년(1615)에 도천산 아래로 옮겼다가 영조 4년(1728)에 지금 있는 자리로 옮겨 세웠다. 1900년과 1922년에 대성전을 수리하였고 1924년에 명륜당을, 1926년에 다시 대성전을 수리하였다. 지금 남아 있는 건물은 대성전, 명륜당, 모성루, 동재 등이다.","a":"자인향교","c":"문화유산자료","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662577.jpg"},{"q":"○○○○○는 조선후기 부농층 주거의 전형을 잘 보여주는 집으로 안채와 사랑채, 곳간채 등이 원형대로 잘 남아 있어 당시 부농층의 의식과 생활을 살필 수 있는 우수한 학술적 자료로 평가된다. 안채는 정면4칸 측면 3칸 각기둥 230*230 도리는 납도리, 반오량가 형식이며 홑처마 팔작지붕 와구토 기와이다. 용마루는 층단 용마루기와로 꾸며져 있다. 부엌은 현재 아궁이와 예전모습대로 잘남아 있고, 부엌의 판문과 판벽의 판벽에 문양을 넣어 환기, 채광을 고려하였다. 부엌의 중층 다락방이 설치되어 있고, 쪽방과 쪽문이 설치되었다.","a":"거창 사병리 밀양변씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666827.jpg"},{"q":"조선 중기의 문신인 유순정(柳順汀, 1459~1512)의 본관은 진주(晉州), 호는 청천(菁川)이다. 이 초상은 유순정이1506년(중종 1) 중종반정에 참여한 공으로 정국 1등 공신에 녹훈되었을 때 그린 공신도상을 18세기 전반기에 후손들이 베껴 그린 것이다. 화면 상단에는 전서체로 ‘靖國功臣領議政柳順汀遺像(정국공신영의정유순정유상)’이라 적혀 있다. 그 오른쪽에 유순정에 관한 신상 기록, 그림의 왼쪽 위에는 김상헌(金尙憲)이 지은 찬시가 적혀있다. 그 아래쪽에는 김상헌의 시를 1720년(숙종 46)에 유순정의 9대손인 유수(柳綬)가 다시 적었음을 밝혀놓았다.","a":"유순정초상 및 함","c":"시도유형문화유산","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637779.jpg"},{"q":"이 성은 ○○○ 8부 능선을 따라 축조된 테뫼성으로서 소가야시대에 쌓은 성(城)이라고 전해지고 있다. 지리적으로 ○○○은 ○○평야의 동쪽에 위치하면서 서쪽을 제외한 동남북 3면이 바다에 둘러 쌓여 있고, 특히 북쪽으로는 임진왜란때 전적지로 유명한 당항포만이 자리할 정도로 남해안을 관망할 수 있는 요충지이다. 성은 자연 암벽사이에 산돌을 이용하여 외벽을 받쳐쌓은 내락수법을 취하고 내벽쪽은 평평한 성내의 도로처럼 평지와 연결되어 있으며, 성벽자체는 곡선을 이룬다.","a":"고성 철마산성","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664030.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 정확히 지어진 연대는 알 수 없으나 연산군 5년(1499)에 향교를 없애고 중종 13년(1518)에 백련동에 향교를 지었다. 그러나 매년 제사 때마다 호랑이가 나타나서 숙종 30년(1704)에 봉성산 아래인 현 위치로 옮겼다. 1825년에 명륜당을 수리하였고, 그 뒤에도 여러 차례 수리가 있었다. 현재 남아있는 건물은 대성전 ·명륜당 ·동재 ·서재 ·동무·서무 ·외삼문 등이 있다.","a":"구례향교","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639964.jpg"},{"q":"임진왜란 때 허물어진 대구토성을 돌로 다시 쌓은 후 이를 기념하고자 세운 비이다. 비는 직사각형으로, 바닥돌 위에 비몸을 세운 간단한 모습이다. 비문에 의하면 성의 둘레는 2,124보(步)이며, 네 개의 문을 만들고 성을 지키기 위한 군량, 전포 등을 갖춘 창고를 두었다. 석성의 공사기간은 6개월이며, 동원된 인원은 78,534명에 달한다. 성이 완성된 뒤에는 여러 장사들을 모아 활쏘기대회를 열어 상을 주었다 한다. 경상도 관찰사였던 민응수가 나라에 건의하여 영조 13년(1737) 대구 남문 밖에 세워두었으며, 민응수가 비문을 짓고, 백상휘가 글씨를 썼다.","a":"영영축성비","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636844.jpg"},{"q":"경상남도 ○○군 하북면에서 출토된 청동으로 된 불상과 사리탑이다. 불상은 불꽃무늬가 새겨진 광배(光背)를 배경으로 앉아 있는데, 투박하게 만들어진 데다가 표면의 부식이 심해서 확실한 특징을 살피기 어렵다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 정수리에는 상투 모양의 머리묶음이 솟아 있다. 얼굴은 코와 입이 작게 표현되어 균형미를 잃고 있다. 옷은 양 어깨에 걸치고 있으며 왼쪽 어깨와 허리 아래 부분에 옷주름이 새겨져 있다. 오른손은 어깨 높이에서 손끝을 위로 향하여 손바닥을 보이고 있으며, 왼손은 배꼽 부위에서 들고 있다.","a":"양산 통도사 청동여래좌상 및 청동사리탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641578.jpg"},{"q":"○○○○○은 조선 후기 문신인 귀애 조극승(1803∼1877)을 추앙하기 위해 그의 동생 성재 조규승이 지은 정자이다. 두 사람 모두 많은 관직을 지냈으나, 말년에는 고향에서 지내며 선비들을 가르치는데 힘을 썼고, 학문 연구에 정열을 쏟아 『귀애집』, 『성재집』 등을 남겼다. 지금까지도 조씨 문중과 지역 민이 두 형제의 학덕과 사상을 높이 여기고 계승, 발전시키기 위해 노력하고 있다.","a":"영천 귀애정","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658952.jpg"},{"q":"조선시대 후기의 실학자이며 과학 사상가였던 담헌 ○○○ 선생이 태어난 터이다. ○○○은 북학파 실학자로 유명한 박지원·박제가·이덕우·유득공 등과 친분을 나누며 학문의 세계를 넓혀 나갔으며, 영조 41년(1765)에는 북경에 가서 서양의 과학 및 서양문물을 살피고 돌아왔다. 우리나라에서 처음으로 지전설과 우주무한론을 주장한 사람으로, 사실에 근거하여 진리나 진상을 탐구하는 학문태도와 과학주의적 사고방식을 가진, 조선시대의 가장 뛰어난 과학 사상가였다.","a":"홍대용선생생가지","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661500.jpg"},{"q":"경남 ○○군에 있는 ○○○는 모두 16종 194판의 불교관련 문헌 ○○을 소장하고 있다. 이 ○○들은 17세기 후반에서 18세기 초에 새겨진 것들로 대승경전과 불교의식관련 문헌들이다. 이 가운데 정토신앙의 근본경전인 아미타경은 세조 10년(1464)에 간경도감에서 간행된 것을 숙종 28년(1702)에 다시 그대로 새겨 간행한 복간본이다. 거의 대부분의 판들이 온전하게 보존되어 있어 조선 후기 절의 ○○인쇄문화와 ○○○의 격을 알 수 있는 귀중한 자료이다.","a":"고성 운흥사 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641795.jpg"},{"q":"국탄 김시정의 셋째 아들 김영운이 정조 9년(1785) 분가하면서 지은 집이다. 집의 이름은 김영운의 호를 따라 ○○이라 부른다. 원래는 임동면 지례동에 있었으나, 임하댐 건설로 물에 잠겨 1988년 지금 있는 자리로 옮겨 지었다. 건물은 二자형으로 앞면 4칸·옆면 1칸의 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 구성은 남부지방의 일반적인 형태를 갖추고 있으면서, 유독 부엌이 오른쪽에 있는 점이 특징이다.","a":"치헌","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662423.jpg"},{"q":"조선시대에 청자(靑磁), 백자(白磁), 분청사기(粉靑沙器) 등을 굽던 가마터가 무리를 이루어 남아 있어 ○○○이라고 이름이 붙었다. 이곳에서 흩어진 채 발견되는 파편들로 확인된 그릇의 종류로는 대접, 접시, 종지, 병, 태항아리[胎壺], 합(盒)등이 있다. 수습된 파편 가운데 눈길을 끄는 것으로는 ‘언양인수(彦陽仁壽)’, ‘장흥(長興)’,‘순(順)’,‘예(禮)’ 등 조선시대의 관청 이름과 관련이 있는 명문편(銘文片)들이 있는데, 이는 가마터의 성격과 조업시기를 알려 주는 자료가 된다.","a":"삼동하잠리요지군","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645913.jpg"},{"q":"○○○○○에는 석조지장보살좌상을 중심으로 좌우로 도명존자상과 무독귀왕상, 시왕을 협시로 한 지장○○○ 13구와 함께 동녀상, 귀왕상, 판관상, 사자상, 역사상이 좌우로 각 1구씩 배치되어 있다. 지장○○○의 조사 과정에서 모두 복장물을 넣을 수 있는 복장공(腹藏空)이 마련되어 있음을 확인하였다. ○○○ 지장○○○과 권속들은 전반적으로 상태가 양호한 편이지만, 군데군데 채색 안료의 박락이 보이고 부분적으로 파손·손상 되어 보수된 것도 있다.","a":"장안사 명부전 석조지장보살삼존 및 시왕상 일괄","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636764.jpg"},{"q":"연대는 횃불과 연기를 이용하여 정치·군사적으로 급한 소식을 전하던 통신수단을 말한다. 봉수대와는 기능면에서 차이가 없으나 연대는 주로 구릉이나 해변지역에 설치되었고 봉수대는 산 정상에 설치하여 낮에는 연기로 밤에는 횃불을 피워 신호를 보냈다. 별방진에 소속되어 있는 ○○○○는 북제주군 구좌읍 한동리 북쪽에 있는 옛날에 좌가장이라고 불리는 곳에 자리잡고 있다. 현재 남·서쪽면은 무너졌으나 연대의 윤곽은 뚜렷하며, 높이는 1.8∼2.2m 정도가 남아있다.","a":"좌가연대","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657833.jpg"},{"q":"고려의 명장 인헌공 ○○○ 장군이 태어난 곳이다. 태어난 날 하늘에서 큰 별이 떨어졌다 하여 그 ○○의 터를 낙성대落星垈라 하였다. 원래 '○○○ 낙성대'라 새겨진 고려시대 사리탑식 3층 석탑이 있어 탄생지를 알려주고 있었으나, 1973년 낙성대공원을 조성하면서 이 석탑을 공원내 안국사 경내로 옮겼다. 원래의 자리에는 1974년 유허비를 세워 유서깊은 사적지임을 표시하였다.","a":"강감찬 생가 터(낙성대)","c":"시도기념물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644753.jpg"},{"q":"전북특별자치도 임실군 오수면 오수리 관월마을에 있는 고려시대 석불로, 높이는 4.8m의 입상이며, 석재는 화강석이다. 하체 부분이 땅에 묻혀 있던 것을 발굴과 복원을 통해서 입상을 완연하게 감상할 수 있다. 광배(光背)와 불상이 하나의 돌로 되어 있다. 광배는 주형거신광배(舟形擧身光背)를 2줄 선으로 표시하고 안쪽에 연꽃무늬, 바깥쪽에 불꽃무늬, 맨 위에 화불을 새겼다. 미륵불의 머리는 나발에 작은상투 같은 육계가 있고, 둥근 얼굴이다. 귀는 길게 표현되었으며 목에는 3줄의 삼도(三道)가 있다. 어깨는 좁고 체구는 다소 평편하다.","a":"오수리석불","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639488.jpg"},{"q":"조선 후기의 문신이자 학자이며, 서화가인 추사 김정희(1786∼1856)의 말년 작품으로 「71과병중작」이라고 새겨져 있다. 김정희는 북학파의 일인자인 박제가의 제자이다. 청나라 고증학의 영향을 받아 금석학을 연구하였으며, 뛰어난 예술가로 추사체를 만들었고 문인화의 대가였다. 김정희는 순조 9년(1809)에 생원이 되고, 순조 19년(1819)에 문과에 급제하였으며 고증학을 우리나라에 도입하였다. 전해오기로는 그가 「71과병중작」이란 글씨를 쓴 3일후에 세상을 떠났다고 하는데, 죽은 해에 대해서는 여러 설이 있다.","a":"봉은사 판전 현판","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636259.jpg"},{"q":"○○○ 대웅전에 주존불로 봉안되어 있는 목조○○○○으로, 높이 90㎝, 무릎폭 64㎝이다. ○○○는 백제 의자왕(재위 641∼660) 때 창건된 절이라고 하나 뚜렷한 기록은 전해지지 않고 있다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 정수리에는 상투 모양의 머리묶음이 낮게 솟아 있다. 넓적한 얼굴은 원만하며, 가늘고 긴 눈과 큼직한 코 등이 균형있게 표현되었다. 이마 부분에는 동그란 백호(白毫)가 있으며, 양쪽 귀는 짧은 편이나 목에 3개의 주름이 있어 인자하면서도 근엄한 인상이다.","a":"불주사목조아미타여래좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639715.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 바닥가부좌상으로, 뒤편으로는 상단벽면과 하단돗자리의 이단구도를 배경으로 하여 도식화된 등받이를 묘사하고 앞으로는 서책이 놓여진 서안을 배치하였다. 선사의 왼손엔 주장자를 들고 오른손은 염주를 쥐고 있지 않고 경탁위에 올려놓고 있는 것이 이색적인 모습이라 하겠다. 화면 향우측엔 주지묵서의 ‘양종정사○○○○○대선사진(兩宗正事九成堂鳳儀大禪師眞)’의 화제가 있고 향우측엔 영찬이 있다. 화면 크기는 가로 77.8cm, 세로 121.0cm이다.","a":"구성당 봉의 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643044.JPG"},{"q":"○○○은 조선 세종 6년(1424)에 세종의 형인 효령대군의 별장으로 지어진 건물이다. 세종 7년(1425) 가뭄이 계속되자 농민의 삶을 걱정한 세종이 농사형편을 살피기 위해 서울 서쪽의 넓은 들을 살피고, 효령대군이 살고 있는 이곳에 들렀다. 그런데 때마침 단비가 내려 온 들판을 촉촉하게 적시므로 왕이 기뻐하며 정자의 이름을 '기쁜 비를 만난 정자다'라는 의미의 희우정(喜雨亭)이라 하였다. 그 이후 성종 15년(1484) 성종의 형 월산대군이 정자를 크게 고치고 아름다운 산과 강을 잇는 경치를 멀리 바라본다는 뜻으로 이름도 ○○○으로 바꾸었다.","a":"망원정 터","c":"시도기념물","nc":"","r":"서울특별시","s":"마포구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644773.jpg"},{"q":"조선 중기의 문신이자 임진왜란 때 의병을 일으켜 뛰어난 공적을 세운 농포(農圃) ○○○ 장군의 묘이다. 묘역은 부인 고령 신씨(高靈申氏)와 합장한 하나의 봉분 형태다. 묘제(墓制)는 후대에 정비를 하였지만 대체로 원형이고, 석물은 옛 것 그대로이다. 봉분 앞에 묘표(墓表 ; 무덤 주인공의 이름 등을 새긴 비석)를 1기 세웠으며, 그 앞으로 혼유석, 상석, 향로석을 차례로 조성하였다. 묘표는 일반적인 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)인데, 앞면의 글씨가 웅장하고 강건하여 주목된다.","a":"정문부장군묘","c":"시도기념물","nc":"","r":"경기도","s":"의정부시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646043.jpg"},{"q":"∙ 조선 후기의 문신 김성구가 건립한 가옥이다. 김성구는 본관은 의성(義城), 자는 덕휴(德休), 호는 ○○○이다. 1662년(현종 3) 사마시를 거쳐 1669년 식년문과(式年文科) 갑과로 급제하였고 이후 여러 벼슬을 지내다가 1693년(숙종 19) 강원도관찰사에 이르렀다. 김성구가 17세기에 처음으로 건립한 다음, 그 후손들이 다시 건립하여 지금에 이른다.","a":"봉화팔오헌종택","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2344060.jpg"},{"q":"안채는 정면 5칸, 측면 2칸 규모의 전·후 툇집으로 기단은 자연석을 3∼4단 쌓고 그 위에 자연석으로 초석을 놓고 기둥을 세웠는데 기둥은 모두 방주이며 약한 민흘림을 두었다. 마루는 우물마루 형식이며 우측 방 전면의 툇마루는 약간의 높이차를 두었다. 종도리에 기록된 상량문에 의해 사랑채가 1838년, 안채는 1840년 등 건립연대를 확인할 수 있으며 부재의 단면크기가 크지는 않으나 자연재를 그대로 사용한 가구기법이나, 안채, 사랑채에 모두 전 ·후 툇간을 적용한 점 등 조선 후기 주거건축의 양식과 가구기법을 볼 수 있는 건물이다.","a":"함양오담고택","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642416.jpg"},{"q":"상여와 장례에 쓰이는 용구들을 보관하는 곳으로 곳집으로도 불린다. 19세기 초에 지은 것으로 전하는 이 건물은 전국에 남아 있는 몇 동 안되는 ○○○의 하나로 매우 소박하고 간결하게 지었다. 벽 아랫부분은 돌과 흙으로 쌓아 튼튼하게 막았으며, 윗부분은 널판으로 구성하여 환기와 채광을 고려하였다. 마을 공동으로 관리하고 있으며 ○○○ 연구에 귀중한 자료가 되고 있다.","a":"안동 상여집","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658948.jpg"},{"q":"○○○는 조선 명종 3년(1548) 하서 김인후가 처향(妻鄕)인 순창의 점암촌에 이거하고, 초당을 세워 훈몽이라는 편액을 걸고 강학했던 곳이다. 김인후가 ○○○에 머물렀던 시기는 1548년부터 그가 부친상을 당하여 장성으로 돌아간 1549년까지 약 2년간이다. 이후, 1680년경 김인후의 5대 손인 김시서가 인근에 자연당을 짓고 기거하며 ○○○를 중건하여 후학을 양성하였으나, 다시 퇴락하였다. 1820년경 김인후의 후손들이 점암마을에 ○○○를 중건하고, 어암서원을 건립하여 김인후, 김시서, 정철, 이이의 위패를 봉안하였으나, 대원군의 서원철폐령에 의하여 훼철되었다.","a":"훈몽재 유지","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661894.jpg"},{"q":"청동기시대의 집자리 유적으로, 서호면 면소재지에서 동남쪽으로 약 500m 떨어진 ○○○ 괴음마을 앞 도로변에 자리하고 있다. 지름 4.3∼5.2m의 움집터이며, 형태는 원형 내지 타원형을 이루고 있다. 중앙에 얕은 구덩이가 있고, 바닥면 가장자리에 기둥구멍이 마련되어 있는데, 화로터나 출입구가 없는 것이 특색이다. 출토된 유물로는 항아리형·사발형의 무늬없는토기, 화살촉·가락바퀴·삼각형 돌칼 등 석기류가 있다. 1984년 목포대학 박물관에서 발굴조사한 것으로, 한반도 서남부지역에서만 볼 수 있는 독특한 문화권의 유적이다.","a":"영암장천리선사주거지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654247.jpg"},{"q":"경상북도 경산시 용성면 해발 435m 용산의 정상 아래를 둘러싼 형태의 산성으로, 경사가 완만한 동·남쪽으로는 돌을 쌓았으며, 경사가 급한 서·북쪽으로는 돌과 흙을 이용하여 쌓았다. 지금 남아있는 성의 총 둘레는 1,481㎞이며, 성벽의 높이는 약 1.5∼2.5m이다. 동쪽의 성벽은 내외 2중 성벽의 형태를 취하였으며, 성안에는 잡석과 흙을 다져 뒤채움을 하였고, 회곽도로를 만들어 통행하였다. 경사가 아주 급한 서문터와 남문터 사이의 구간에는 계단을 만들어 성벽이 무너지는 것에 대비하였고, 북쪽 구간과 동·남쪽 구간에는 성의 안팎으로 성벽을 쌓았다.","a":"용산산성","c":"시도기념물","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654631.jpg"},{"q":"통례원 봉례를 지낸 황전이 세종 11년(1429)에 학문을 연마하고 지방 유생들을 가르치기 위해 세운 건물이다. 그 후 영주지역 창원 황씨를 중심으로 사림들이 영조 11년(1735)에 사당으로 다시 지었으며 현재의 건물은 정조 2년(1778)레 고쳐 지은 것이다. 앞면 3칸·옆면 1칸 규모이며 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕의 단아한 건물이다. 가운데 마루가 있고 양 옆에 온돌방을 배치하였다.","a":"첨모당","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663129.jpg"},{"q":"○○○○○은 삼성산의 정상에서 오른족으로 뻗어 내려온 구릉 정상부에 화강암으포 축조되었다. 해발 약 300m 정도의 높은 곳에 위치하고 있으며 고분은 산의 정상부를 향해 남북으로 조성되어 있다. 석실 내부는 화강암의 할석(割石)을 이용해 동·서·북벽의 3면을 맞추어 축조하여고, 남벽은 대판석(大板石) 1매로 축조하였다. 동·서벽은 5~6단으로 쌓여 있고 북벽은 크고 작은 돌이 6~7단으로 쌓여 있다. 발굴 조사가 이루어지지 않은 상태에서 도굴되어 ○○○의 정확한 구조와 연대는 알 수 없다.","a":"석수동석실분","c":"시도기념물","nc":"","r":"경기도","s":"안양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646607.jpg"},{"q":"조선 후기의 문신 조익(1579∼1655)의 무덤에서 나온 묘지 16점으로, 묘지란 죽은 사람의 이름이나 행적 등을 새겨 무덤 옆에 파묻는 돌이나 도판을 말한다. 조익은 1602년 문과에 급제하여 벼슬에 나아갔다가 인목대비가 유폐되는 사건이 빚어지자, 벼슬을 그만두고 은거하였다. 1623년 인조가 즉위하면서 이조좌랑에 임명되어 조정에 들어갔다. 대동법의 시행을 적극 주장하였고 효종이 즉위하자 우의정과 좌의정에 올랐다. 1613년 벼슬을 버리고 신창현 도고산 밑에 초가를 짓고 여생을 보냈는데, 이 때문에 예산과 인연이 맺어져 예산에 묻혔다.","a":"조익선생일괄유물","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661457.jpg"},{"q":"이곳은 130년 전부터 우리 조상들의 생활 도구의 하나인 옹기를 만들었던 곳이다. 우리 조상들은 돌가마에서 옹기를 구워 내어 물물교환을 통해 생계를 유지하였다. 이 돌가마는 제주지역에서만 볼 수 있는 매우 독특한 것으로서 이곳은 우리 조상들의 생활을 보여주어 학자들의 연구에 좋은 자료를 제공해 준다. ○○○의 불 지피는 곳을 ‘석’, 배연구는 ‘뒷고망’이라 하며, 온도 1100℃ 이상에서 적갈색조를 내며 구워지기 때문에 ‘○○○’이라 하고, 그리고 소성을 하다가 약 900℃ 내외에서 연기를 먹여 검게 나타내게 하는 ‘검은굴’이 있다.","a":"구억리노랑굴","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657955.jpg"},{"q":"○○○○는 일제시기에 지은 상류주택으로 시대적 한계, 근대적 변형이 가미된 건축 양식으로 안채, 사랑채 등 조선시대 상류주택이 갖추어야 할 형식적 요소를 빠짐없이 갖추었고, ㄷ자형 안채와 ㄱ자형 사랑채가 결합된 주택이라는 점도 이 지방에서는 흔치 않은 형식임","a":"거창 월헌고가","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018101516191000.JPG"},{"q":"○○○○이 설법하는 모습을 그린 그림으로, 비단 바탕에 채색하였으며, 가로 223.5㎝, 세로 138㎝ 의 규모이다. 화면의 중심에 ○○○○을 두고, 양 옆에 권속들을 배치하였는데, 형태가 풍만하고 정교하며 무늬가 화려하다. 5가지 색깔의 광배가 눈길을 끌며, 옷의 묘사가 도식화되어 있다. 적색과 녹색의 색상은 다소 탁하며, 코발트 빛깔의 짙은 청색은 19세기 말의 불화양식을 잘 보여준다.","a":"지장사 아미타불도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2588022.jpg"},{"q":"조선 태종의 둘째 아들이며 세종의 형인 ○○○○의 사당과 묘소이다. ○○○○의 이름은 보(補), 자는 선숙(善叔), 시호는 정효(靖孝)이다. 어려서부터 총명하여 글읽기와 활쏘기를 좋아했고, 부모에 대한 효성이 지극하였다. 세조 10년(1464)에 원각사 창건을 감독하였고, 불교에 독실하여 승려들을 모아 불경을 강론하기도 했다. 사당에는 ○○○○의 위패가 모셔져 있으며, 영조·정조 때에 중건과 보수를 거쳤다.","a":"효령대군 이보 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636079.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워서 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 뚜껑돌을 덮고 그 위에 거대한 덮개돌을 올린 바둑판식으로 구분된다. 영암군 서호면 ○○○에 모두 18기의 바둑판식 고인돌이 2줄로 넓게 분포되어 있다. 1984년 목포대학박물관에서 일부를 발굴 조사함으로써 고인돌의 구조와 성격이 밝혀지게 되었다.","a":"영암엄길리지석묘군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654217.jpg"},{"q":"지은 시기를 정확하게 알 수 없으나, 전하는 말에 따르면 약 70년 전에 지은 것으로 추정한다. 건물 구조는 안채, 곳간채, 대문채 등으로 구성되어 있다. 안채는 앞면 4칸·옆면 3칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양의 팔작지붕이며 ㄱ자형 평면을 갖추었다. 곳간채는 앞면 3칸·옆면 1칸 규모에 一자형 평면을 이루고 있다. 대문채는 앞면 6칸·옆면 1칸 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕으로 꾸몄다.","a":"산청대포리민씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664219.jpg"},{"q":"근남면 구산2리 중등산 하단에 남향한 곳에 위치하고 있으며, 이 일대는 현재 논밭으로 경작되고 있고 금당지로 추정되는 밭에는 소형석탑이 서 있었던 자리가 있으며, 그 기단 일부도 남아 있으며, 탑신부는 수년전 도난되었다고 한다. ○○○○는 금당지에서 남쪽으로 약 200m 떨어진 밭 가운데에 위치하고 있다.","a":"배잠사지 당간지주","c":"문화유산자료","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663518.jpg"},{"q":"정면 4칸,측면 1칸반 규모의 팔작와가임. 대문채는 정면 3칸, 측면 1칸으로 목조기와 솟을 대문임. 1744년 창건되었던 영천사의 모습임. 건축기법을 그대로 적용한 것으로 보여지며 건물의 규모에 비해 사용부재나 결구법이 손색이 없으며 보존상태도 양호하여 조선후기 건축양식에 대한 귀중한 학술자료임.","a":"거창 영빈서원","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664786.jpg"},{"q":"○○○○은 조선 전·후기의 가장 대표적인 성리학자인 조광조와 송시열을 배향(配享:위패를 모시고 제사를 지냄)한 사액서원(賜額書院:조선시대 국왕으로부터 편액·서적·토지·노비 등을 하사받아 그 권위를 인정받은 서원)으로 백사 이항복 등 저명한 시인 묵객들이 시문을 남긴 오늘날 서울 지역 내 가장 대표적인 서원이다. 비록 1871년 서원철폐령에 의해 훼철되어 유적의 대부분이 멸실되었으나 서울 지역 내 다른 ○○○ 달리 사당의 기단과 옛 사료상의 ○○○○ 유적으로 소개된 ○○○이 서원 터 앞 계곡에 대부분 원형대로 남아 있어 유적의 경계를 비교적 명확히 확인할 수 있다.","a":"도봉서원과 각석군","c":"시도기념물","nc":"","r":"서울특별시","s":"도봉구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644880.jpg"},{"q":"정각이란 충신·효자·열녀 등을 나라에서 표창하여 그들이 사는 고을 입구에 세워 주던 것으로 이 곳은 충신 ○○○과 열녀인 그의 ○○을 기념하기 위해 세운 것이다. ○○○은 인천에 세거해 온 부평 이씨의 후손으로 궁술과 마술에 뛰어나 충무위부사과에 제수되었다. 병자호란이 일어나자 ○○○은 의병을 모집하여 원도(현 낙섬)에 들어가 강화도와 남한산성에 이르는 통로를 차단하였으며 이튿날인 1월24일에는 약탈을 일삼는 청병을 격퇴하였다.","a":"이윤생·부인 강씨 정려","c":"시도기념물","nc":"","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019071210033100.jpg"},{"q":"○○○○○는 경상남도 ○○군 쌍책면 덕봉리 마을 북서쪽에 자리한 창녕 조씨 문중의 재실이다. 원래는 조선 정조 14년(1790)에 덕양서원이라는 이름으로 창건되었으나, 조선 고종 5년(1868)의 서원 철폐령에 따라 철거되었다. 이후 1872년에 ○○○라는 이름으로 재건되어 오늘에 이르고 있다. ○○○는 주변에 다른 건축물 없이 토석으로 쌓은 담장 안에 단독으로 자리 잡고 있다. 건물 아래 마당 옆에는 과거 덕양서원에 배향되었던 조수천, 조이천, 조신천 세 선현의 유적비가 최근에 세워져, 조상의 정신과 전통을 계승하고 있다.","a":"합천 덕양재","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2025053010194891.JPG"},{"q":"조선 중기의 문신이며 임진왜란 당시의 명장인 만취당(晩翠堂) 권율(權慄, 1537∼1599) 장군의 묘소이다. 선조 15년(1582) 과거에 급제한 후 여러 관직을 역임하였으며, 1592년 임진왜란이 일어나자 광주목사에 제수되어 바로 임지로 떠났다. 왜병에 의해 수도가 함락된 뒤 전라도관찰사 이광(李洸)과 방어사 곽영(郭嶸)이 군사를 모집할 때 광주목사로서 곽영의 휘하에서 중위장(中衛將)이 되어 서울의 수복을 위해 함께 북진, 용인에서 적들을 공격해 대패하고 광주로 퇴각해 후사를 계획했다.","a":"권율장군묘","c":"시도기념물","nc":"","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645936.jpg"},{"q":"조선 전기 무신인 정충신 장군(1576∼1636)의 영정과 유품을 보관하고 있는 사당이다. 장군은 임진왜란(1592) 때 17세의 나이로 권율 장군을 도와 싸웠으며, 인조 2년(1624)에는 이괄의 난을 평정하고 정묘호란 때는 팔도부원사(八道副元師)로 참전하였다. 그 뒤 포도대장, 병마절도사 등을 지냈다. 이곳은 인조 14년(1636) 왕명으로 세운 이후 영조 13년(1737) 고쳐 지었다.","a":"정충신사당(진충사)","c":"문화유산자료","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661254.jpg"},{"q":"영남 사림의 대표적 인물인 이황 선생의 제자로서 학문적인 책을 많이 남긴 이덕홍(1541∼1596) 선생이 공부 하던 정자이다. 선생은 10여 세에 이황의 제자로 들어가 오로지 학문에만 열중하였다. 임진왜란 당시 바다에는 거북선을 육지에는 거북선 모양의 수레를 사용할 것을 주장하기도 하였다. 임진왜란 후에는 백성을 구제하는데 온 힘을 기울였으며, 많은 책을 남겼다. ○○○은 조선 선조 3년(1570)에 지은 것으로, 앞면 3칸·옆면 2칸 규모이며 지붕은 여덟 팔(八)자 모양으로 가장 화려한 팔작지붕이다.","a":"군자정","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640863.jpg"},{"q":"만든 때와 만든 이를 알 수 있는 조선 시대 후기의 대표적인 중형 나무 불상 가운데 하나이다. 1972년 표면 금칠을 새로 할 때 나온 발원문(發願文; 바라고 원하는 것을 적은 글. 지금 원본은 도둑맞고 옮겨 적은 것만 남아 있다)에 따르면, 1649년(인조 27) 7월 16일 조각승 사인(思忍. 1614~1656년)과 상림(尙琳)이 석가삼존불과 16나한상을 조각한 뒤 전북특별자치도 순창 회문산 만일사(萬日寺)에 모셨던 불상 가운데 하나로 밝혀졌다.","a":"포천 동화사 목조불좌상","c":"시도유형문화유산","nc":"","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101716013000.jpg"},{"q":"∙ ○○○은 두곡 홍우정이 1636년에 건립하여 후학양성과 태백오현(잠은 강흡, 각금당 심장세, 포옹 정양, 손우당 홍석)으로 추앙받던 학자들과 회동⋅교류하던 장소이다. ∙ 정자는 1637년에 건립하여 1756년에 와가로 중건 한 후 미수 허묵의 편액현판과 태산 이상정의 기문을 걸었다. 1876년에 다시 중수하였다. ∙ ○○○은 정면 3칸 측면 1칸 반 규모의 팔작 기와집이며, 좌측과 우측의 두칸을 각각 온돌방을 두고 가운데는 대청으로 사용하고 있다. ∙ 정자의 주위에는 방형의 토석담장을 둘렀고 전면 우측에 사주문을 세워 정자로 출입케 하고 있다.","a":"봉화 옥류암","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663621.jpg"},{"q":"○○○○는 공자를 비롯한 옛 성현들에게 제사지내고 지방민의 교육을 위해 세운 국립교육기관이다. 조선 태조 원년(1392) 제주성내 교동에 세웠으며 순조 27년(1827)에 지금의 자리로 옮겨 오늘에 이른다. 현재 남아있는 건물로는 공부하는 곳인 명륜당, 사당인 대성전과 계성사 등이 있다. 명륜당은 원래 아름다운 건물이었다고 하나 지금은 콘크리트로 다시 지었다. 대성전에는 공자를 비롯한 여러 성현들의 위패를 모시고 있다. 조선시대에는 국가로부터 토지와 책, 노비 등을 받아 학생을 가르쳤으나 갑오개혁(1894) 이후 지금은 제사만 지내고 있다.","a":"제주향교","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643248.jpg"},{"q":"조선 선조 때의 학자인 송강 정철(1536∼1593)과 그의 아들 기암 정홍명(1592∼1650)의 문집을 새긴 ○○이다. 정철은 명종 16년(1561) 26살의 나이로 진사시 1등을 하였고, 이듬해 문과에서 장원으로 급제하였다. 사헌부지평, 좌랑, 전라도 암행어사와 여러 도의 관찰사를 지냈다. 그는 우리나라 시조와 가사문학의 대가로, 「관동별곡」과 「훈민가」를 시작으로하여 「사미인곡」, 「속미인곡」, 「성산별곡」 등 4편의 가사와 수많은 시조를 남겼다. 그가 죽은 후 전국의 여러 서원에 그의 위패가 모셔졌으며, 시호는 ‘문청’이다.","a":"담양 송강집 및 기암집 목판","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640136.jpg"},{"q":"중암사 불당에서 약 50m 떨어진 곳에 자리하고 있는 6기의 부도와 1기의 탑비이다. 중암사는 대전과 금산의 경계를 이루는 천비산 중턱에 자리잡고 있는 사찰로, 예전에는 서산대사 ·사명대사 ·영규대사 등의 초상을 모신 영정각이 있었다고 전해지나, 지금은 불당으로 쓰이는 함석지붕의 건물 한 채만 남아있다. 부도는 승려의 시신을 화장한 후 그 유골이나 사리를 모셔두는 곳으로, 이 6기의 부도는 각각 한월당(漢月堂), 추월당(秋月堂), 천봉당(天峰堂), 홍파당(泓波堂), 수월당(水月堂), 월영당(月影堂)의 여섯 승려의 사리를 모시고 있다.","a":"중암사부도","c":"문화유산자료","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659702.jpg"},{"q":"정려란 나라에서 충신·효자·열녀를 칭찬하여 그들이 살던 마을의 입구에 세우던 문이나 비(碑)로 이 정려는 임진왜란과 그 이후에 전공을 세운 ○○○ 장군의 충절을 기리기 위해 영조 29년(1753)에 세운 것이다. ○○○ 장군은 선조16년(1583) 과거에 급제한 뒤 선전관 등 여러 벼슬을 거쳐 선조 25년(1592) 임진왜란이 일어나자 임금님을 의주까지 호송하였다. 그 뒤 권율의 휘하에서 행주대첩에 참가하여 공을 세웠으며, 정유재란 시기에는 삼도수군 통제사 이순신과 함께 해전에 참전하였다.","a":"신여량장군정려","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654271.jpg"},{"q":"○○○○은 원래 영조 10년(1734)에 곡남리 진동산에 창건되었으나, 오랜 시간이 흘러 건물이 허물어지면서 유림과 후손들의 정성으로 현재의 위치에 다시 건립되었다고 한다. 사당은 정면 3칸, 측면 2칸의 맞배지붕의 건물이다. 조헌 선생은 조선 중기 문신이자 의병장이며 유학자이다. 조선 명종 20년(1565) 성균관에 입학하였으며 1567년 문과에 급제하였다. 선조 1년(1568) 처음으로 관직에 올라 교수를 역임하였고 선조 5년(1572)에는 교서관에 속하였다. 선조 15년(1582)에는 모함을 받아 파직되었다가 다시 복직되었다.","a":"조헌사당(표충사)","c":"문화유산자료","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660897.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 세운 바둑판식으로 구분된다. 이곳의 고인돌 유적은 금호강변을 따라 자리잡고 있는 특리 사평 마을의 논밭과 농가 곳곳에서 확인되고 있다. 이 곳에서는 고인돌의 덮개돌 35기가 무리지어 확인되었고, 주위에서는 신석기시대의 것으로 보이는 토기조각도 발견되었다.","a":"산청특리지석묘군","c":"시도기념물","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655970.jpg"},{"q":"비봉산에 자리잡은 절로 통일신라 경문왕 5년(865)에 도선국사가 세웠고 조선 현종 10년(1669)에 고쳐 지어 오늘에 이르고 있다. 도선은 신라말의 승려이자 풍수지리의 대가로 알려져 있다. 광해군 때 이수광이 편찬한 『승평지』에 따르면 이 부근의 지형이 새가 알을 품고 있는 형상으로 그 기운이 너무 강하여 지세를 누르기 위해 이곳에 ○○○를 지었다고 한다. 경내의 건물로는 대웅전과 삼성각 그리고 스님들이 생활하는 요사채가 있다.","a":"향림사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661897.jpg"},{"q":"○○의 대표적 양반마을인 산운마을에 소재하고 있으며, 현 소유자의 5대조 이희발이 영월부사로 있을 때 세운 집이라고 한다. 1800년 초에 세운 것으로 추정하는데, 안채는 약 60여년 전에 일부을 다시 지었다. 안채, 사랑채, 사당으로 구성되어 있는 이 마을의 대표적인 건물이다.","a":"의성 운곡당","c":"시도민속문화유산","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658959.jpg"},{"q":"○○○는 백제 무왕 41년(640)에 자장율사가 세웠다고 전한다. 절 경내에는 응진전을 비롯하여 대웅전, 영산전, 대광보전, 홍성루 등 많은 건물이 남아 있다. ○○○은 ○○○의 정문으로 이 문을 지나면 속세를 벗어나 불교 세계에 들어가게 되고, 해탈을 하겠다는 마음을 갖게 된다고 한다. 중앙 통로 양쪽 편에 금강역사상과 문수동자상 등을 모시고 있다.","a":"마곡사해탈문","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660984.jpg"},{"q":"○○○○○은 조선 초 사림파의 대표적 인물인 탁영 김일손의 종택이다. 건물은 김일손의 문집 등을 보관한 영모각, 안채, 사랑채, 행랑채, 그리고 김일손 내외의 위패를 봉안한 부조묘 부조묘(不祧廟)로 구성되어 있다. 부조묘는 조선 선조 11년(1578 )자계 서원에 김일손이 배향되자 종택이 있는 백곡에 건립되었다. 이후 조선 현종 2년(1661)에 자계 서원이 사액 되면서 사불천위(私不遷位)에서 공불천위(公不遷位)로 지위가 올랐다. 조선 헌종 10년1844에 후손 창윤昌潤이 노후된 부조묘를 다시 지었으며, 1940년에는 정면 3칸, 측면 1.5칸으로 고쳐 지었다.","a":"청도 탁영종택","c":"시도기념물","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654684.jpg"},{"q":"○○○○○은 「경서(經書)」의 「○○○○○」을 서사(書寫)하여 ○○으로 만든 것이다. 제작연대와 서사자는 ○○에 기록이 없어 자세히 알 수 없으나 제작연대는 영조 34년(1758) 이전으로 추정된다. 필체는 영조의 어필인 듯하며 모두 10폭이다. 글씨는 묵(墨)이 아닌 금분(金粉)으로 서사(書寫)되어 있다. 우리나라에는 일찍이 고려시대 이래로 각 시대마다 「경서(經書)」의 「○○○○○」을 서사(書寫)하여 ○○을 만드는 사례가 많았다.","a":"보은 법주사 주서무일편 병풍","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638858.jpg"},{"q":"배화여고 뒷정원에는 높다란 암벽이 있는데 그 왼쪽면에 ‘필운대(弼雲臺)’라는 글씨를 세로로 새기고, 가운데에는 몇줄의 싯구를 적어 놓았으며, 오른쪽으로는 아홉 사람의 이름을 나열해 놓았다. 필운은 이곳에 살았었던 ○○○ 선생의 호이다. 선생은 조선 선조 때에 대제학을 지내었으며 평생을 청렴하게 살아 청백리에 뽑히기도 하였다. 가운데의 글은 선생의 후손인 이유원이 이 터에 들른 후 그 느낌을 글로 지어 새긴 것이고, 오른쪽에 있는 명단은 선생의 집을 지을 때 관련되었던 사람들로 추측되고 있다.","a":"백사 이항복 집터(필운대)","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102313204400.jpg"},{"q":"계룡산 내에 봉우리처럼 우뚝 솟아있는 자연바위로, 사람의 손에 의해 만들어진 것이 아닌 자연 그대로의 탑이다. 탑이란 부처의 사리를 모셔두는 곳을 일컫는 것으로, 이 탑에는 다음과 같은 전설이 전해 내려오고 있다. 석가모니가 열반한 후 인도의 아육왕은 구시나가라국에 있는 사리탑에서 많은 양의 사리를 발견하여 이를 시방세계(十方世界:열곳의 방향에 있는 중생의 세계로, 동·서·남·북·동북·동남·서남·서북·상(上)·하(下)에 있는 무한한 세계를 가리킴)에 나누어 주었다.","a":"천진보탑","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660991.jpg"},{"q":"종의 외형은 아래로 갈수록 약간 좁아지며, 고리는 두 마리의 용으로 형상화하였고 천판(天板)은 둥글고 낮게 만들었다. 종의 몸체는 횡선으로 공간을 구획하였는데, 상단과 하단에 2줄을 만들어 세 부분으로 나누었다. 상단에 있는 횡대 윗부분에는 원형범자문이 둘러져 있다. 몸체 중심부에는 보살상과 연곽이 번갈아 배치되었다. 두광을 갖춘 보살상은 두 손을 모으고 구름 위에 서 있으며, 사다리꼴 형태의 연곽 안에는 연꽃 5개가 간략하게 표현되었다. 보살상과 연곽은 종의 몸체에 비해 크게 나타난다. 하단 아래에는 특별한 장식이 없다.","a":"함양 백운암 건륭32년 동종","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643163.jpg"},{"q":"○○○○은 인조의 셋째 왕자인 인평대군(麟坪大君) 이요(李㴭, 1622~1658)의 유적지이다. 인평대군은 이곳에 머물기도 하면서 호를 송계(松溪)라 하였고, 자신의 문객(門客) 이신(李伸)에게 ‘구천은폭’을 써서 폭포 옆에 새기게 하는 등 이곳에 많은 애착을 가지고 있었다. 그러나 1658년 인평대군이 30대의 젊은 나이에 죽은 뒤 ○○○○은 그의 아들들에게 넘겨져 가끔 이용하였을 것이다. 인평대군의 아들인 복창군 이정(李楨), 복선군 이남(李枏)과 복평군 이연(李㮒)은 종친으로서 너무 정치에 깊숙이 관련되었는데 특히 남인들과 친밀하였다.","a":"송계별업 터","c":"문화유산자료","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020010714202800.JPG"},{"q":"원래 요바꼴 언덕 위에 서 있는 불상을 법당에 옮겨 놓았는데, ○○○의 명칭도 이로 인한 것이라 한다. 불신 뒤에 있는 광배(光背)에 아무런 무늬도 새기지 않아 소박함이 엿보이는 이 불상은 신라말이나 고려초에 만들어진 것으로 추정된다.","a":"창녕 석불사 석조보살입상","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663824.jpg"},{"q":"○○○의 효행에 대해서는 『모재실기(慕齋實記)』와 「상서문(上書文)」에 잘 나타나 있다. 더구나 정려기를 지은 단계(端磎) 김인섭(金麟燮)은 성재(性齋) 허전(許傳)의 문인(門人)으로 문과(文科)에 급제하여 사간원(司諫院)의 헌납(獻納)을 지냈던 인물이며, 효자 ○○○과 같은 지역의 동시대 인물이므로 그가 지은 정려기는 신필(信筆)이라 하기에 손색이 없다. 그리고 정려(旌閭)가 되기까지의 과정 및 그 이후의 세역(稅役) 면제(免除) 관련 사항까지 알 수 있는 다섯 점의 고문서가 갖추어져 있으므로 문화유산로서 가치가 있다.","a":"정용균 효행문서 및 정려비","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665084.jpg"},{"q":"○○○○는 사찰 입구에 설치하는 것으로, 절에 행사나 의식이 있을 때는 당이라는 깃발을 걸어둔다. 이 깃발을 꽂아두는 길쭉한 장대를 당간이라 하며 당간의 양 쪽에 서서 이를 지탱해주는 두 돌기둥을 ○○○○라 한다. 드물게 당간이 남아있으나, 대개는 두 지주만 남아있다. 이 ○○○○는 당간과 ○○○○가 모두 남아 있는 경우로 네모난 받침돌 위에 ○○○○를 세웠고, 그 사이에 놓인 당간은 몇 토막의 돌기둥을 철띠로 연결시킨 특이한 형태이다. 높이가 7.45m에 이르나 정상에 끊긴 흔적이 있어 원래는 훨씬 더 높았을 것으로 보인다.","a":"서외리당간지주","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639459.jpg"},{"q":"금당실 마을의 오미봉 기슭에 남향으로 자리잡은 건물로 제사 및 강학을 위한 곳이다. 조선 중종 때의 문신이자 함양 박씨 입향조 박종린(1496∼1553)을 기리고 제사하기 위하여 효종 7년(1656)에 지었다. 흙담 안에 ○○과 내삼문·강당·대문간 등이 튼 ㅁ자로 배치되어 있다. 강당은 앞면 4칸·옆면 2칸 규모이며, 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕이다. 앞면은 둥근 기둥을 세우고 나머지는 네모 기둥을 세웠다. 가운데 2칸은 대청마루이고 양쪽에는 온돌방을 들였으며, ‘전교당’과 ‘○○○’라는 현판이 걸려있다.","a":"예천 상금곡리 추원재 및 사당","c":"시도민속문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658773.jpg"},{"q":"○○○은 검암천의 절벽 위에 위치하는 근대기 정자건축으로, 조선조 세조때 경상우도처치사와 병조판서를 지낸 이호성이 창건하고 그의 손자 이희조가 중수했다고 한다. ○○○은 산수가 수려한 ○○군 가야읍 검암리에 자리 잡고 있다. 뒤는 산림이 울창한 동지산이 위호하고 앞은 항상 맑은 물이 흐르는 여항천이 있다. ○○○은 여항천에 면해 20여m의 절벽 위 절경에 자리 잡고 있다. ○○○은 사대부들이 處士的 취향을 가지고 고향의 풍속을 바로잡고 교화에 힘쓰고 학문 연구에 힘쓰던 중종대 창건되었다. ○○○은 정면 4간, 측면 2간 규모이다.","a":"함안 동산정","c":"문화유산자료","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666393.jpg"},{"q":"금어 완호의 작품으로 도상구성에서 섬세하고 창의성이 뛰어난 작품으로 이미타후불탱, 신중탱, 지장탱, 독성탱, 산신탱으로 구성되어 있다. 동일 작가의 작품을 한데 모아 보존되어 있는 흔치 않은 경울로 조선후기부터 근,현대로 이어지는 불교회화의 변화를 알 수 있는 중요한 자료이다.","a":"거제혜양사완호작불화일괄","c":"문화유산자료","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666439.jpg"},{"q":"마성(馬城)은 말이 도망가는 것을 막기 위해 목장 둘레를 돌로 막아 쌓은 담장이다. 조선시대에는 나라에서 쓸 말을 기르기 위해 주로 해안가와 섬 등을 중심으로 200여개의 목장을 설치하였다. 울산지역의 목장은 조선전기에 방어진목장[구목장], 방암산목장, 이길곶목장 등 모두 3개의 목장이 설치되었으나, 방암산목장과 이길곶목장은 완성을 보지 못하고 바로 폐지된 것으로 보인다.","a":"남목마성","c":"시도기념물","nc":"","r":"울산광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645887.jpg"},{"q":"○○○○○는 남부 부농주택의 배치 특성을 보이는 주거로서 안채, 사랑채 모두 3량가로 구성한 근대기의 특성들이 주거에 잘 반영되어 있는 예를 가지고 있는 좋은 자료이므로 문화유산자료로 지정","a":"진주 허선구 고가","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2017091317382300.jpg"},{"q":"이 불상은 고려말의 고찰(古刹)로 알려진 서울시 ○○○ 소재 ○○○ 약사보전에 봉안되어 있는 ○○○○으로 전체크기는 79.5cm이다. 신체에 비해 얼굴이 크고, 머리에는 나발이 새겨져 있으며 머리 정상에는 계주가 표현되어 있다. 불상의 저부에 균열이 있고, 전체적으로 호분이 여러 겹 칠해져 있어 불상의 원 상호(原 相好)를 알아보기 어려우나 동그란 얼굴에 이목구비가 섬세한 원만한 얼굴이었을 것으로 추정된다. 불신(佛身)은 전체적으로 위축되었으며 머리의 크기에 비해서 어깨가 좁다.","a":"일원동불국사석불좌상","c":"문화유산자료","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659311.jpg"},{"q":"○○○는 어떤 사건이나 사업에 관련된 사실이나 자취를 기록한 비로, 이 비는 ○○읍성을 수리·복원한 사실에 관해 적고 있다. 형태는 길쭉한 직사각형의 비몸 위에 지붕돌을 얹은 모습이다. 비몸에는 성의 수리에 관한 내용들을 새겨 넣었다. 비문에는 조선 고종 3년(1866) 병인양요 후 성과 군용기구 등을 수선하였고, 비상사태에 대비하기 위해 고종 6년(1869)에 전면적인 수리를 하였다는 내용이 기록되어 있다.","a":"충주 축성사적비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638492.jpg"},{"q":"一蠹 鄭汝昌(1450-1504)은 조선 성리학사상 한훤당 김굉필과 함께 포은 정몽주의 학통을 계승하여, 정암 조광조·회재 이언적·퇴계 이황·남명 조식 등과 같은 성리학자들의 배출을 가능케 한 인물이다. 그의 묘소는 1504년 서거 직후에 일어난 갑자사화로 인해 부관참시라는 처참한 역사적 현실을 겪었던 곳이다. 묘역 내에는 일두 ○○○의 묘와 정경부인 완산이씨의 묘가 자리잡고 있으며 ○○○ 묘 앞에 선 신도비는 병자호란 때 남한산성에서 인조가 청나라에 항복하려 하자 자결을 시도하여 청사에 이름이 길이 빛나는 桐溪 鄭蘊(1569-1641)이 지은 것이다.","a":"함양 정여창묘역","c":"시도기념물","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657503.jpg"},{"q":"○○○는 회청색의 청자 태토에 기벽을 두껍게 하여 성형한 후 기 면의 안팎으로 흑유를 얇게 입힌 항아리로 내부의 시유상태가 좋은 편이며, 시유된 표면에는 빙렬이 균일하게 나 있다. 산화로 인한 유탈현상을 제외하면 상태가 양호한 편이며, 굽 언저리에 흙물이 남아 있는 것으로 보아 출토품으로 생각된다. 뚜껑이 있는 항아리 형태로 성형한 후 몸체 부분을 4면 형태로 편평하게 다졌는데, 합각이 되는 곳은 능형처럼 곡을 잡은 형태이다. 또한 몸체 부분 한 면에 결가부좌하고 있는 인물상이 날카로운 도구로 간략하게 음 각되어 있다.","a":"흑유호 및 흑유정병","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636793.jpg"},{"q":"조선 중기의 문신이며 시인인 송강 ○○의 ○○이다. 명종 17년(1562) 별시문과에 장원급제하였고, 여러 관직을 두루 거쳐 선조 17년(1584)에 대사헌이 되었다. 1589년 우의정이 되어 서인의 대표로 동인을 추방하였으며, 다음해 좌의정에 올랐다. 1591년 광해군의 책봉을 건의하여 파직하였으나, 1592년 임진왜란이 일어나자 경기·충청·전라의 3도체찰사가 되었고, 1593년 중국 명나라에 사신으로 다녀왔다. ○○은 정치가로서 큰 일을 많이 하였지만, 붕당 싸움에 말려 반대당의 배척을 받았다.","a":"진천 정철 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650526.jpg"},{"q":"조선 중기의 문신 이유당 ○○○의 ○○이다. ○○○는 본관이 한산韓山이고 자는 사로師魯이며 호는 이유당이다. 김장생金長生으로부터 가르침을 받았으며, 1608년(선조 41)에 별시문과 병과에 급제한 후 검열檢閱·저작著作·박사博士 등을 지냈다. 1612년(광해군 4)에 김직재金直哉의 무옥誣獄에 관련되어 이산理山으로 귀양가고 다시 창평昌平으로 이배移配되었다가 1621년(광해군 13)에 풀려났다. 1623년 인조반정으로 전부典簿가 되었고 1632년(인조 10) 좌부승지左副承旨로 있을 때, 인조의 아버지에 대한 추숭追崇에 반대하다가 연산連山에 유배되었다.","a":"청주 이덕수 묘역","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019042311481300.jpg"},{"q":"이 ○○○는 조선조 인조때의 명신인 荷潭 ○○○선생의 ○○○로 1670년(현종11년) 8월에 세워졌다. 이 비석의 비문은 당대의 명문장가인 조경(趙絅)이 忠翼公 金時讓의 아들인 김휘(金徽)의 요청으로 지었으며, 글씨와 전자(篆字)는 당대 최고의 서예가인 이정영(李正英)이 썼다. 전형적인 조선의 ○○○ 양식을 잘 갖추고 있는 이 비는 양질의 화강암과 웅장한 규모 그리고 명문장과 명서체 등으로 높이 평가 받고 있다. 방형대석과 비신, 가첨석을 갖춘 전형적인 ○○○를 최근에 난간석을 돌려 보호하고 있다. 모두 화강암으로 만들었으나 암질이 차이가 있다.","a":"괴산 김시양 신도비","c":"문화유산자료","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660828.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 언제 처음 지었는지 정확히 알 수 없으나, 조선 초 각 지방 군·현에 향교들이 건립될 때인 1407년(태종 7)~1413년(태종 13)에 창건되었을 것으로 추측된다. 처음에는 동교리에 있던 것을 지세가 협소하여 성현을 추가로 모시거나 제사를 올릴 때 법도대로 모시지 못하여 1649년 현감 이창윤(李昌胤)에 의해 현의 남쪽으로 이건되었다. 그러나 1684년(숙종 8) 율곡 이이와 우계 성혼을 추가로 제향하면서 건물이 협소해 다시 현재 위치로 이건하였다.","a":"전의향교","c":"시도기념물","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1658034.jpg"},{"q":"경기도 의왕시 ○○○에 소장되어 있는 18종 466판의 목판이다. 1622년(광해군 14)에 새긴 묘법연화경을 비롯하여 1623년(인조 1년)에 새긴 선요·도서·절요·서장 등 불교 교과목과 『예수십왕생칠경』, 『오대진언』, 『법계성범수륙승회수재의궤』등의 불교의식에 관한 문헌이다. 이외에도 1831년(순조 31)에 새긴 『천지팔양신주경판』 과 『몽산법어』, 『천자문』, 『계초심학인문·발심수행장』이 있다. 이들 모두 ○○○에서 새긴 목판이다 .","a":"청계사소장목판","c":"시도유형문화유산","nc":"","r":"경기도","s":"의왕시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637616.jpg"},{"q":"논에 물을 대기 위해 둑을 쌓아 만든 보(洑)로서, 서석면 수하리에서 내촌면 물걸리까지 약 1㎞ 정도의 물길이다. 물길을 끼고 있는 산의 낭떠러지 바위면에는 ‘보주 김군보(洑主 金君甫)’라는 글귀가 보이는데, 김군보 개인이 자신의 재산을 털어 직접 만들었던 것으로 보인다. 200여 년 전에 만든 것으로 전하는 이 보는 홍천군 내촌면 물걸리 지역 일대의 개척과 관련된 농경유적으로, 조선 후기의 수리 및 관개 시설의 형태를 비교적 잘 보여준다.","a":"홍천동창보수로및암각명","c":"시도기념물","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648321.jpg"},{"q":"石保君(李福生) 墓는 1447(세종 29)년 경기도 양주군 미아리에 조성하였으나 시가지 확장으로 인하여 1958년 2월25일 ○○시 소태면 양촌리 산46번지로 이장하였다. 1872년에 제작된 長明燈과 墓表를 함께 이전하였다. 묘역 입구에 神道碑가 있으며 石碑(2점), 望柱石, 魂遊石, 床石, 香爐石, 長明燈(2점), 童子石, 文人石, 羊石 등을 갖추고 있다. 墓表 음기에 “崇禎後五壬申 九月 日改立”이라는 기록이 있어 이 비의 건립이 1872년 9월임을 알 수 있다. 신도비는 1990년 건립하였으며 귀부와 이수를 갖추고 있다.","a":"충주 석보군 묘소","c":"문화유산자료","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660867.jpg"},{"q":"이 유물들은 조선 인조 때의 무신인 광서 ○○○ 장군이 평소 사용하던 ○○과 명나라 제독에게 받은 장려패문 등이다. ○○○은 선조 25년(1592) 임진왜란이 일어나자 군수 유숭인과 함께 의병을 모아 왜적을 물리쳤다. 선조 32년(1599)에 용궁현감에 임명되었고 광해군 5년(1613)에 경흥도호부사에 제수되었다. 인조 2년(1624)에 이괄의 난이 일어나자 도원수 장만의 휘하에 들어가 동교에서 대승하였다. 인조 14년(1636)에 병자호란이 일어나 청에 굴욕적인 항복을 했다고 비분강개하다가 인조 19년(1641)에 73세의 나이로 죽었다.","a":"박진영 유품","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641577.jpg"},{"q":"귀부에 비신을 세우고 가첨석을 올려놓은 모습으로 가첨석의 일부가 파손된 것을 제외하면 보존상태는 양호한 편이다. 비문에는 사찰의 경영을 위하여 신도들이 출원한 내용을 기록하고 있는데 음기에 시주한 불자들의 이름과 출원품의 양이 명시되어 있고 이 비를 세운 대표자는 통정대부 崇徽로 되어 있다. 사원경제 분야의 연구에 귀중한 자료이다. 크기 : 비신높이 140cm, 너비 69cm, 두께 23cm","a":"충주 청룡사 위전비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638862.jpg"},{"q":"○○○○○은 웅촌면 면소재지에서 고연리로 연결되는 도로 옆에 3기가 모여 있는데, 덮개돌은 화강암으로 논두렁에 비스듬히 놓여 있다. 크기는 3기중 제일 큰 것이 길이 300㎝, 너비250㎝, 두께 50㎝정도이다. 현재의 상태로는 정확한 구조적 특징이나 내용 등을 알 수는 없으나 외형적으로 볼 때 개석식에 속한다. 이 ○○○○은 사적 제332호인 울주 ○○○ 유적과 함께 청동기시대 ○○○ 일대의 정치·사회·문화 등을 연구할 수 있는 중요한 자료가 된다.","a":"검단리지석묘군","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645905.jpg"},{"q":"비를 받쳐주던 받침돌로, 거북의 모습을 하고 있다. 전체적으로 온화한 느낌을 주고 있으며, 등에 바짝 붙은 머리는 시선이 위를 향하고 있다. 목의 비늘 표현이라든가 등껍질 무늬가 없어 간략화된 모습이 보인다. 등 중앙에는 비를 꽂아두기 위한 네모난 홈을 둔 후 그 주위로 연꽃무늬를 둘러 장식하였다. 각 부분의 조각솜씨나 양식들이 조선 태조의 헌릉비나, 영암 도갑사의 도선국사비, 삼전도비 등의 수법을 닮아 있어 조선시대 전기의 작품으로 추측된다.","a":"상주 무양동 석조귀부","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662651.jpg"},{"q":"영덕 ○○○ 마을 내에 있는 ○○○은 남용(南鎔)이 조선 고종 37년(1900)에 건립한 것을 1942년에 남응호(현 소유자의 아버지)가 매입하였다고 한다. ‘○○○’이라는 이름은 현 소유자 남명순(현 소유자)의 할아버지인 남조영의 처가 동네 이름인 경주 사곡을 딴 것이라 한다. 이 ○○○은 정면 4칸·측면 5칸의 ㅁ자형 건물로 자연석 기단과 자연석 주초 위에 네모기둥을 세웠으며, 벽체·기단·굴뚝 등은 시멘트로 덧 발라져 있다. 대문칸을 중심으로 좌측에 1칸 마굿간이 있고, 우측에 아랫방과 사랑대청이 있다.","a":"영덕괴시리사곡댁","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663410.jpg"},{"q":"이 책판은 구한말의 대학자 ○○○의 시문을 모아 만든 문집목판으로, 48권 목록 1책을 합하여 25책이나 되는 방대한 유물이다. ○○○은 성품이 온화하고 학문이 뛰어나 일찍 나라의 부름을 받았으나 혼란한 때라 하여 후진을 기르는데 노력하였다. 이식의 학맥을 이은 허전의 의발을 받아 민족문헌 보급의 실천적인 학풍을 세운 대유학자이다. 실사구시의 학풍을 이은 학자로서 인명사전인 『동국씨족고』, 교육용 교과서인 『여사수지』, 실천적 예의책인 『상례편람』, 역사지리책인 『강역고』등 다수의 많은 저술들을 남겼다.","a":"노상직 소눌문집 책판외 20종","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641784.jpg"},{"q":"이 재사는 우곡(愚谷)선생의 높은 덕을 기리기 위하여 증손 송영(宋穎)이 숙종대에 건립한 건물로 추정된다. 17세기 후기의 건물로서는 가운데 설주, 연귀마춤 등의 치목수법(治木手法)이 건립 연대와 부합되는 수작으로 평가된다. 우곡(愚谷) 송량(宋亮, 1534～1618)선생은 유교를 실천 궁행한 대표적 선비 중의 한 분이다. 스스로 효행을 다한 선비로, 그가 사는 마을 소곡(所谷)을 효곡(孝谷)이라 부르게 된 것은 선조 17년 이후부터라 한다.","a":"효곡재사","c":"시도유형문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640802.jpg"},{"q":"○○○은 고종 23년(1886)에 연재 송병선(1836∼1905) 선생이 무주에 내려와 구천동 물가에 지은 정자로, 선비들과 나라 일을 논하며 후학을 양성하던 곳이다. 송병선 선생은 송시열의 후손으로 벼슬에 뜻을 두지 않고 은둔생활을 하던 중, 일제에 의해 강제로 을사조약이 체결되자 망국의 울분을 참지 못하고 자결로써 충절을 지킨 충신이다. 지금 있는 정자는 불에 타 없어져 고종 28년(1891)에 다시 지은 것으로, 한국전쟁 때에는 북한군이 머물기도 하였다.","a":"서벽정","c":"시도기념물","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653593.jpg"},{"q":"‘포천 ○○○○’은 조선 시대의 유학자 이덕형(李德馨, 1561년-1613년)과 조경(趙絅, 1586년-1669년)의 학문과 덕행을 기리기 위해 두 사람의 위패를 모신 건물이다. 1692년에 서원 부근의 연못 이름을 따서 ‘용연(龍淵)’이라는 이름으로 사액(賜額; 조선 시대에 임금이 사당이나 서원 등에 이름을 지어 새긴 편액(扁額)을 내리던 일)을 받았다. 이덕형은 임진왜란(壬辰倭亂; 1592년-1598년까지 2차에 걸친 조선과 일본과의 싸움) 때 구원병을 요청하러 중국 명나라에 다녀왔고 여러 주요 관직들을 지냈다.","a":"용연서원","c":"시도유형문화유산","nc":"","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637445.jpg"},{"q":"본『○○○○』은 세종이 문사(文士)에게 필요한 책이라 하여 1435년(세종 17) 가을에 강원도감사로 부임하는 유계문(柳季聞)이 배사(拜辭)하는 날에 간포(刊布)를 명하여 간행하게 된 것이다. 그러나 실제 간행은 다음해 봄에 세종이 집현전에 경연소장 선본(善本) 2부를 내어 주어 간행되었다. 간행시 본서의 발문은 1437년 6월에 남수문(南秀文)이 지었고 발문의 말미에 \"江陵原州分刊\"이라 되어 있어 강릉과 원주 2곳에서 나누어 발간하였음을 알 수 있다.","a":"운부군옥","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637196.jpg"},{"q":"돈대란 적의 움직임을 살피거나 공격에 대비하기 위하여 영토 내 접경지역 또는 해안지역의 감시가 쉬운 곳에 마련해두는 초소이다. 대개 높은 평지에 쌓아두는데, 밖은 성곽으로 높게 하고, 안은 낮게 하여 포를 설치해둔다. ○○도의 가장 남쪽에 자리잡고 있는 이 돈대는 조망할 수 있는 시야가 매우 넓으며, 자연의 지형을 이용하여 쌓았기 때문에 평면이 반달모양을 이루고 있다. 4곳에 문을 설치한 외곽 포대로, 관아에서 돈장을 따로 두어 관리하게 할 정도로 그 중요성을 띠었다 한다.","a":"강화 분오리돈대","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101617165800.jpg"},{"q":"○○○는 광주이씨 석전문중의 대표적인 건물로서 낙촌 이도장(各村 李道長)의 덕행을 기리기 위해 1913년에 세운 정면 4칸 측면 2칸 홑처마 팔작지붕 목조 와가의 낙촌정, 장자 귀암 이원정(歸巖 李元禎)의 유덕과 공적을 알리기 위해 1903년에 세운 정면 4칸 측면2칸 홑처마 팔작지붕의 목조와가 경암재, 장손 정제 이담명(靜齋 李聃命)의 별사봉향을 위해 세운 정면4칸 측면1칸 홑처마 맞배지붕 목조와가의 소암재와 묘실, 대문채, 관리사를 일괄하여 이름을 붙인 것이다.","a":"동산재","c":"문화유산자료","nc":"","r":"경상북도","s":"칠곡군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663589.jpg"},{"q":"향교란 공자를 비롯한 여러 성현께 제사지내고, 지방 백성들의 교육과 교화를 담당했던 국립교육기관을 가리킨다. ○○○○는 조선 태종 4년(1404)에 세웠고 정유재란(1597)으로 불탄 것을 인조 13년(1635)에 다시 지었는데 그 뒤에도 몇 차례의 수리가 있었다. 앞면 3칸·옆면 2칸의 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 앞면에 사당건축에서 흔히 볼 수 있는 앞과 옆이 트인 퇴칸을 두었고 몸채쪽에는 문을 달았다. 중앙칸의 가운데에 2짝의 문을 달고 양쪽 기둥에는 골판벽을 끼웠다.","a":"김제향교대성전","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639373.jpg"},{"q":"조선 고종(재위 1863∼1907)의 친아버지인 흥선대원군의 별장으로 원래는 김흥근의 소유였던 것을 고종 즉위 후 대원군이 사용하였다. 한국전쟁 후 고아원·병원 등으로 사용되다가, 현재는 개인소유 건물이다. 정자의 앞산이 모두 바위라 대원군이 ‘○○○’이라 이름지었으며 삼계동 정자라 하기도 한다. 커다란 바위와 바위산에서 흐르는 시냇물, 뜰에 서 있는 소나무를 배경으로 한 ○○○은 매우 아름답다.","a":"석파정","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636103.jpg"},{"q":"봉천산 꼭대기에 설치하여 하늘에 나라의 태평과 백성들의 평안을 빌었던 곳으로, 벽돌을 쌓아올려 위로 갈수록 좁아드는 사다리꼴 형식을 하고 있다. 『강도지』에 의하면, 고려 때에는 나라에서 하늘에 제사를 지내는 제천의식을 거행하였던 곳이었으나, 조선시대 중기에 와서는 봉화를 켜두는 봉화대로 사용하였다 한다.","a":"강화 봉천대","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018112016152800.jpg"},{"q":"이 유적은 ‘앞동산 노랑굴’이라고도 한다. 우리 선현들이 일상 생활에서 사용하는 허벅·통개·병·장테 등의 도기를 만들었던 곳이다. 다른 지역에서는 그릇의 표면에 유약을 칠하지만, 이곳에서는 유약을 칠하지 않고 자연적으로 발색시킨다. 또한 다른 지역은 모두 토요(土窯)인 데 반하여 제주도의 도요는 세계에서 유일한 석요(石窯)이다. 이 유적은 제주도 특유의 도기문화를 꽃 피우던 곳일 뿐만 아니라, 우리 선현들의 지혜를 엿 볼 수 있는 곳이기도 하다. 이 굴은 남고 북저로 축조된 노랑굴○○○이다.","a":"신평리도요지","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657971.jpg"},{"q":"1926년 이 지역 선비들이 시사계를 조직하여 지역 풍속을 아름답게 만들고 시(詩)를 발전시키기 위해 만든 정자이다. 정자는 앞면 3칸·옆면 1칸으로 이루어져 있으며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 정자 안에는 ○○○ 건축의 시작과 끝, 참여자 이름 등을 적어 놓은 글과 시사계의 활동을 엿볼 수 있는 글이 걸려 있다.","a":"운흥정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661952.jpg"},{"q":"돈대는 적의 움직임을 살피거나 공격에 대비하기 위해서 영토 내 접경지역 또는 해안지역의 감시가 쉬운 곳에 마련해 두는 초소이다. 대개 높은 평지에 쌓아두는데 밖은 성곽으로 높게 하고 안은 낮게 하여 포를 설치해 둔다. 이 돈대는 자연적인 지형을 이용하여 그 위에 작은 요새를 만든 것이다. ○○○○는 1679년(숙종 5)에 쌓은 48돈대 가운데 하나로 ‘긴○○○’라고도 불린다. 해안으로 돌출된 지형에 자리 잡아서 관측과 방어에 매우 유리한 조건을 갖췄다. 내부 지름이 31m인 원형 구조로 둘레가 128m, 석벽 높이 210㎝~350㎝이다.","a":"강화 장곶돈대","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645579.jpg"},{"q":"이 돌비석은 ○○○의 경계를 표시하기 위해 세운 장생(長生 혹은 長牲)으로서 ‘장승’이라고도 한다. 장생은 수호신, 이정표, 경계표 등의 역할을 하며, 풍수지리설과 함께 민속신앙과도 깊은 관계를 맺고 있다. 이 장생은 경계 표시로서의 성격이 강하다. ‘○○○’이라고 한 것은 국가의 명에 의해 건립된 장생이라는 뜻이다. ○○○의 장생표는 7기였으나 1085년(선종 2) ○○○에서 호부에 보고하여 12기를 다시 세웠으며, 그 땅이 사방 둘레가 47,000보 가량이라고 전한다. 현재까지 ○○군 상남면 ○○○와 양산 하북면 백록리에 위치한 ○○○○○ 2기가 남아있다.","a":"울주 상천리 통도사 국장생 석표","c":"시도유형문화유산","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637246.jpg"},{"q":"전남 함평군 나산면에 자리잡은 이 가옥은 정유재란 때 순절한 이충인(1526∼1597)이 지었다고 한다. 지은 시기는 정확하게 알 수 없지만, 안채 건물에서 발견한 기록으로 미루어 17∼18세기에 지은 것으로 보인다. 원래 문간채, 행랑채, 사랑채 등을 고루 갖춘 짜임새 있는 양반집이었다고 하나 지금은 모두 없어지고 안채만 남아 있다. 안채는 앞면 7칸 규모의 一자형 평면구조를 이룬다. 기둥은 앞면과 오른쪽 부분에만 둥근기둥을 세우고, 그 외 나머지는 사각기둥을 세웠다. 집을 지으면서 심었다고 전하는 커다란 동백나무와 모과나무 한 그루가 현재 집 주위에 남아 있다.","a":"함평이규행가옥","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662120.jpg"},{"q":"이 불상은 ○○○ 극락전 중앙 불단 위에 삼존불로 봉안되어 있는데 그중 주존불이다. 2004년에 개금불사를 시행하여 전반적으로 보존상태는 양호한 편이다. 불상 바닥에 마련된 복장공은 가로 17cm, 세로 9cm의 작은 크기로 현재는 한지로 발라두었다. 개금당시 복장공을 개봉하였으나 이미 도난당해 복장 내에 유물은 하나도 남아 있지 않았다고 한다. 함양 ○○○○○은 등을 세우고 머리를 약간 앞으로 숙인 자세로 결가부좌하였다. 수인은 ○○○인으로 양손을 무릎 위에서 살짝 들어 오른손은 손등을 위로 하고, 왼손은 손바닥을 위로 하여 엄지와 중지를 맞댄 하품중생을 결하였다.","a":"함양안국사목조아미타여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642679.jpg"},{"q":"황간향교 앞에 있는 이 누각은 자연경관을 즐기던 곳으로, 조선 태조 2년(1393)에 황간현감 하첨이 지었다. 임진왜란(1592) 때 불탔으나 새로 짓고 여러 차례 보수했다. ○○○라는 이름은 경상도관찰사 남공이 마치 학이 바람을 타고 떠다니는 듯하다 해서 지은 것이다. 앞면 4칸·옆면 4칸 규모의 1층 건물이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 기둥과 난간만 있어 사방이 탁 트인 형태로 시원하다.","a":"영동 가학루","c":"시도유형문화유산","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638430.jpg"},{"q":"장척 마을의 산 기슭 도로가에 자리하고 있는 비로, 현감을 따라 순절한 통인(通引:관아에 딸려 잔심부름을 하던 벼슬아치)의 충절을 기리고 있다. 조선시대 숙종 4년(1678) 당시 장수현감을 지내던 조종면은 민정시찰을 나섰다가 이곳 산비탈길을 지나게 되었다. 요란한 말발굽 소리에 놀라 숲 속에 있던 꿩이 소리치며 날아오르고, 이로인해 현감의 말이 덩달아 놀라 한쪽 발을 잘못 디디게 되어 결국 벼랑 밑으로 떨어져 말과 함께 현감도 목숨을 잃고 말았다.","a":"타루비","c":"시도기념물","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653620.jpg"},{"q":"조선 효종 원년(1650)에 궁구당 김중정이 병자호란 때 벼슬을 버리고 은거하던 중 유생을 가르치기 위해 세운 암자이다. 순조 27년(1827)에 물 때문에 왕래가 불편하자 김상원이 지금 있는 자리인 물 건너편으로 옮겨 지었다고 한다. 건물은 앞면 3칸·옆면 3칸 규모로 암반 위에 있다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이며 누마루 형태이다.","a":"와룡암","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661634.jpg"},{"q":"1900년대에 지은 주택으로 규모가 작은 별장형 주택으로 보이나 살림집으로 축소된 듯하다. 보통의 한옥은 사랑채와 안채로 구분되고 있는데 반해, 이 집은 사랑채와 안채가 한 건물 안에 배치되어 있다. 1900년대의 개량 한옥이 갖는 요소들을 잘 지니고 있는 중요한 민속자료이다.","a":"상허이태준가옥","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658047.jpg"},{"q":"조선 인조(재위 1623∼1649) 때의 충신 박신용 장군의 위패를 모신 사당이다. 지금도 그의 충의 정신을 길이 빛내기 위하여 관복을 소장하고 봄·가을로 제사를 지내고 있다. 박신용 장군은 선전관이 되어 군사들을 이끌고, 몸을 던져 싸우다 죽었다. 이 때 조정에서 내린 관복이 있어 후손이 보호 관리하여 오다가 조선 후기에 이르러 관복을 보관할 건물을 짓고 ○○○이라 부르고 제사를 드렸는데, 그 내용을 석비로 만들어 새겨 놓았다. 건물은 사당 형식으로 만들었고, 문은 가운데 칸을 높여 세운 삼문(三門)형식으로 주변은 담장을 둘렀다.","a":"유의각","c":"문화유산자료","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661148.jpg"},{"q":"전북특별자치도 무주군 적상면 ○○○에 있는 사고를 보관한 곳으로 사고(史庫)는 조선 왕조의 역사에 관한 기록이나 중요한 서적을 보관하던 곳을 말한다. 임진왜란(1592) 때 서울의 춘추관을 비롯한 전국의 사고가 불에 탄 후, 정족산·태백산·오대산 등 5곳에 새로운 사고를 설치하였다. 그러나 이중 묘향산 사고가 북방 후금의 위협으로 관리가 어렵게 되자 광해군 6년(1614)에 천연 요새인 ○○○에 실록을 옮겨 보존하였다. 인조 19년(1641)에는 선원각을 세우고 왕실의 족보인 『선원록』을 소장하면서 완전한 사고의 역할을 하게되었다.","a":"적상산 사고지 유구","c":"시도기념물","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653635.jpg"},{"q":"평택시 청북면 옥길리의 해발 104.7m인 ○○○에 있다. 북쪽에는 발안천이 흐르고, 남으로는 자미산과 비파산으로 이어지는 능선이 아산만 방향으로 뻗어있어 동서 교통로를 차단하는 요충지에 해당한다. ○○○○은 ○○○의 9부능선을 따라 쌓았다. 평면 형태는 장타원형에 일부가 돌출된 다각형이다. 성벽은 흙으로 쌓은 토성이며 전체 둘레는 547m다. 성벽은 기초를 편평하게 정리하고 그 위에 점토를 다져 수평을 맞춘 후 점토와 모래를 교대로 쌓아 올렸다. 북치성 주변에서는 기초부에서 와적층(瓦積層)이 확인되었다. 모든 성곽은 축성 당시의 토목기술로 쌓았다.","a":"평택무성산성지","c":"시도기념물","nc":"","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647278.jpg"},{"q":"○○○은 효행이 남달라 어머니의 병환 중 산신령의 감응으로 영약을 구하게 되어 어머니가 기사회생하는 이적이 있었으므로 진주인근의 유생들이 관찰사, 성주, 암행어사 등에게 정려를 요청한 상서문(6매)과 예조입안 및 완문, 그리고 ○○○은 동몽교관으로 부인 진양강씨를 영인으로 증직한 교지, 호구단자(8매) 등으로 당시 지방유림의 예교존중실태와 여론조성과정, 지방관의 민원처리를 비롯한 당시 지역사회상을 연구하는데 좋은 자료이다.","a":"박효근효행관련고문서","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665128.jpg"},{"q":"이 동종은 극락전 안에 있으며 전체 높이 140㎝, 몸체 높이 85㎝, 입 지름 70㎝이다. 종의 맨 윗부분에는 꽃을 세워 도드라지게 장식한 문양이 있다. 어깨에는 간략화된 꽃무늬 띠를 둘렀다. 어깨 아래로는 4개의 유곽이 있고, 그 사이에 보살상을 새겼다. 유곽은 길이 25㎝, 폭 25㎝이며, 덩굴무늬로 장식된 곽 안에는 9개의 유두가 있다. 유곽 밑에는 금철대시주(金鐵大施主), 동철대시주(銅鐵大施主), 보시(布施), 공양(供養) 등의 문자판이 새겨 있다.","a":"화암사동종","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639423.jpg"},{"q":"○○○○○ 앞에 있는 3층 석탑이다. ○○○는 구룡산 중턱에 자리한 절로, 많은 문화유산을 전하고 있어 널리 알려져 있으나, 절의 역사에 관한 기록은 전하고 있지 않다. 석탑은 바위를 바닥돌 삼아 2층 기단(基壇) 위에 3층 탑신(塔身)을 올린 모습이다. 아래층 기단의 네 모서리와 면의 가운데에는 기둥모양을 조각했고, 가운데기둥 양 옆으로 얇고 넓직하게 안상(眼象)을 새겼다. 위층 기단 역시 네 모서리와 면의 가운데에 기둥모양을 새겼다. 탑신부는 1층 지붕돌이 파손이 심한 편이며, 몸돌과 지붕돌은 각각 한 개씩의 돌로 쌓아 올렸다.","a":"창녕 관룡사 약사전 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641354.jpg"},{"q":"팔공산 기슭에 있는 ○○○는 신라 흥덕왕 10년(835)에 심지왕사가 지은 절이다. ○○○은 대웅전 옆에 있는 강당으로, 처음 지은 연대는 확실하지 않으나 조선 초기에 지어진 것으로 보인다. 지금의 건물은 1976년에 해체하여 수리한 것이다. 앞면 3칸·옆면 3칸의 규모로, 사람 인(人)자 모양의 단순한 맞배지붕집이다. 앞쪽에는 겹처마이고 뒤쪽은 홑처마의 구조로 조선 초기·중기에 많이 지어진 양식이다. 지붕 처마를 받치면서 장식을 겸하는 공포는 기둥 위에만 있는 간결한 주심포 양식이다. 순조 24년(1824)에 쓴 현판이 걸려 있다.","a":"환성사심검당","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640402.jpg"},{"q":"○○○ 경내에 서 있는 비로, 영암 출신 ○○○○의 활동과 내력을 기록하고 있다. 수미는 조선시대 승려로 13세에 출가하였고, 불교를 숭상했던 세조 임금이 그 스승(왕사)으로 모셨던 인물이다. 비는 거북모양의 받침 위에 비몸을 세우고 머릿돌을 올린 일반적인 모습이다. 형식적으로 조각된 거북받침은 머리가 용의 머리처럼 바뀌었으나, 목이 짧다. 앞발과 뒷발의 발톱이 다섯개씩이다. 거북 등에는 벌집모양의 육각형이 매우 두껍게 조각되어 있다. 비몸 위에 놓인 머릿돌에는 섬세하게 조각된 구름 위로 중간과 양 모서리에 다투듯 뒤엉킨 두마리의 용을 새겨놓았다.","a":"도갑사수미왕사비","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640046.jpg"},{"q":"탑골이라 불리우던 보광사의 옛 터에 있었던 탑으로, 임진왜란 때 절이 폐허가 되어 탑만 서 있던 것을, 1928년 현재의 관음사에 옮겨 세웠다고 전한다. 탑은 4면에 기둥 모양의 조각을 둔 기단(基壇) 위로 탑신(塔身)의 몸돌 1개와 지붕돌 3개를 차례대로 올린 모습이다. 비록 일부 석재가 없어졌지만 지붕돌 밑면의 받침수가 3단인 점으로 보아 고려시대에 세운 것으로 보인다.","a":"창녕 도천 삼층석탑","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663819.jpg"},{"q":"조선시대 유학자인 수재 정호(1837∼1938)와 류연구(1861∼1938)가 지은 집이다. 정호의 호를 따서 일명 ‘수재고택’으로도 불리는 이 집은 일제시대 독립지사인 류동환(1885∼1973)이 1939년에 고쳐 지었다. 원래는 안동시 임동면 수곡리에 있었으나 임하댐 건설로 1987년 지금 자리에 옮겨 세운 것이다.","a":"임하댁","c":"문화유산자료","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662450.jpg"},{"q":"신라 경문왕 2년(862)에 도선(道詵)이 절을 세운 후, 큰 암석을 손으로 갈라서 만들었다고 전해지는 전체 높이 8.43m의 마애관음보살상으로 신체는 원통형으로 되어 있다. 신비스러운 영험이 있다고 하여 많은 사람들의 발길이 끊일 날이 없으며 석불 앞에는 석탑과 석등이 있다. 조선시대 억불정책으로 방치되었던 이 석불은 철종 14년(1863)에 나라의 기도도량으로 지정된 바도 있다. 불상 형태로 보아 고려시대에 유행하던 ○○○ 계통을 이어받은 조선 중기의 작품으로 추정된다.","a":"도선사 마애불입상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636116.jpg"},{"q":"오리 ○○○의 친필 글씨 중 포은 정몽주(圃隱 鄭夢周, 1338~1392)의 시를 옮겨 ○○○의 손자, 손녀에게 남긴 자료로그의 후손들에 대한 사랑과 선비로서의 청렴한 생활을 알 수 있으며, 특히 ○○○의 부인인 영일 정씨는 정몽주의 현손으로 ○○○에게는 더 뜻 깊었을 것으로 여기진다.","a":"광명 이원익 친필유묵","c":"시도유형문화유산","nc":"","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637805.jpg"},{"q":"이 집은 19세기 말 옻골 입향조인 최동집의 12세손이 되는 최명덕이 아들의 분가를 위해 건립한 살림집으로 경주최씨 종가 바로 앞쪽에 위치하고 있다. 마을 안길의 우측 골목에 서있는 대문을 들어서면 일자형의 사랑채와 안채가 이자(二字)를 이루며 남향하고 있다. 건립 당시 안채는 와가, 사랑채는 초가였으나 1918년 사랑채는 와가로, 안채는 칸수를 늘리고, 기둥을 높이는 등의 중건이 있었다. 사랑채는 정면 5칸 측면 1.5칸 규모의 일자형 홑처마 팔작기와 집으로 앞쪽이 개방된 대청을 중심으로 좌우에 사랑방, 침방을 두고 앞쪽에 툇마루를 설치하여 드나들 수 있게 하였다.","a":"수구당","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659503.jpg"},{"q":"유봉시(1654∼1709)가 두 아들의 공부를 위해 안동시 임동면 위동으로 이사하였는데, 두 아들이 모두 학문에 전념한 보람이 있어 학덕과 벼슬이 세상에 알려지자 이곳에 서재를 짓고 세 그루의 나무를 심어 ○○○이라 하였다. 조선 현종 15년(1674) 안동군 임동면 위리에 지었다가 1922년에는 박곡리로 옮겨 지었으나, 1987년 임하댐 건설로 지금 있는 자리에 다시 옮겨 지었다.","a":"삼가정","c":"문화유산자료","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662443.jpg"},{"q":"조선을 건국한 태조 이성계의 태(胎)를 안치했던 곳으로, 본래 함경도 용연(龍淵) 있었으나 태조 2년(1393) 당시 전라도 완주군 진동현이었던 현재의 금산군 추부면 마전리로 옮겨왔다. ○○은 몇 차례 중수 및 개수되었으며, 일제강점기인 1928년 조선총독부에서 ○○을 훼손하여 태 항아리를 창덕궁으로 옮겨갔고 1993년 지역 주민들이 남은 석비와 석물을 수습하여 현재의 위치에 복원하였다. 비석 전면에는 '○○○○○'이라는 명문이 새겨져 있고, 후면에는 중건한 시기(1689년)가 새겨져 있다.","a":"태조대왕 태실","c":"시도유형문화유산","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639221.jpg"},{"q":"이 석탑은 기단(基壇)이 제대로 갖추어지지 않은 채, 평평한 돌 위로 5층의 탑신(塔身)이 올려져 있다. 탑신의 1층 몸돌은 2개의 돌로 이루어졌고, 나머지 몸돌과 지붕돌은 각각 하나의 돌로 만들어졌다. 1층 몸돌은 큰편이고, 2층 몸돌에서 급격히 낮아지다가 5층까지는 비슷한 크기를 유지한다. 각 층 지붕돌은 두꺼운 편이며, 밑면에는 5단씩의 받침을 두었다. 전체적으로 비례가 좋지 않고, 지붕돌이 두꺼워진 점 등으로 보아 고려시대 작품으로 짐작된다. 일제시대에 쓰러졌던 것을 1967년 마을 주민들이 다시 세워놓은 것이다.","a":"괴산 봉학사지 오층석탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638445.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배계층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 북제주군 애월읍 광령리에 돌담에 있는 이 고인돌은 덮개돌이 반으로 쪼개져 경사면에 쓰러져 있으며 받침돌은 보이지 않는다. 원래는 밭 한가운데에 있던 것을 경작지를 만들 때 밀어낸 것으로 보인다.","a":"광령지석묘 3호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657673.jpg"},{"q":"안성시 대덕면 죽리 외평마을 입구 당산나무 옆에 위치한 석불상이다. 현재 높이 2.35m의 크기로 무릎 이하는 땅에 묻혀 있다. 불상은 광배(光背 ; 붓다의 몸에서 나오는 성스러운 빛을 형상화한 것)와 한 돌로 조성되었다. 방형의 얼굴에 높은 육계(肉髻 ; 상투 모양으로 솟은 붓다의 정수리, 지혜를 상징)와 보주형의 정상계주(頂上髻珠 : 붓다의 육계 위에 표현된 보배구슬)를 표현하였다. 둥글고 큰 눈에 비하여 코와 입은 매우 작다. 짧은 목에 삼도(三道 ; 불상의 목에 표현된 세 줄의 주름으로 지혜를 상징)를 나타냈으며 목이 짧으므로 귀가 어깨에 닿았다.","a":"안성죽리석조여래입상","c":"문화유산자료","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660204.jpg"},{"q":"○○○○은 화순읍과 동면의 경계 지점에 해당하는 해발290.4m의 ○○○ 일대에 있는 테뫼식 산성으로 ○○○의 자연 지형을 최대한 이용하여 축조하였다. 산성의 전체길이는 약 675m 내외이다. 성벽은 능선이나 절벽을 이용하여 대부분 주변의 돌을 사용하였다. 성벽의 기단석은 큰돌을 사용하고 위로 올라갈수록 작은 돌을 사용하고 있는데 동벽은 산경사면을 깎아낸 후 자연석을 가공하여 한쪽 면만을 축조한 편축법으로 이루어졌다. 남벽은 건물지 앞의 능선사면을 이용하여 축조하였는데 그 일부는 산경사면을 깎아낸 후 양쪽에 돌을 쌓아 만들었다.","a":"화순오성산성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654350.jpg"},{"q":"\"○○○ 가옥은 창평면 소재지의 남쪽부근의 넓은 들을 바라보면 자리하고 있다. 넓고 잘 다듬어진 마을 안 길을 가다 집으로 향한 좁은 골목으로 10여m 지나면 5칸의 곡간채가 나오는데 맨 좌측 끝 1칸을 대문으로 하였다. 동입서출이라고 동쪽으로 난 대문을 들어서면 벽돌 담장을 쌓아 대문에서 안채가 들어다 보이지 않게 하였다. 시선차단용 담장을 지나면 넓은 안마당을 두고 사방을 안채, 사랑채, 삼칸채, 문간(곡간)채가 마당을 에워싼 ㅁ자형식으로 둘러싸여 있다.","a":"담양고재환가옥","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658409.jpg"},{"q":"장흥 ○○○○○은 조선시대 초기(1435년, 세종 17)의 매향사실을 기록한 비석이다. 매향(埋香)이란 향나무(香木)를 묻는 민간불교 신앙의례이다. 향나무를 민물과 갯물이 만나는 지역에 오래 묻었다가 약재나 불교의식용으로 썼으며, 그 매향의 시기와 장소, 관련 인물들을 기록한 것이 매향비(또는 암각)이다. 자연암반에 음각된 매향의 명문 순서는 왼쪽에서 오른쪽으로 새겨져 있어 통례적인 오른쪽에서부터 읽는 것과 다르다. 글자수는 총 6행 21자로 되어 있다. 자형(字形)은 아주 정서(精書)된 것 같지는 않고 투박한 편이다.","a":"장흥덕암리암각매향명","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662290.jpg"},{"q":"○○○○○은 일제강점기인 1923년 12월 10일 건축됐다. 우편업무 담당을 목적으로 지은 근대식 건물로, 당시 행정관청 치고는 웅대한 규모였다. 건립 당시의 명칭은 ○○○편국이었으며, 해방 이후인 1949년 8월 ○○○○○으로 개칭되었다. 입구 양쪽에 큰 기둥 형식의 탑부(塔部)를 세우고, 그 사이에 주두(柱頭: 기둥머리를 장식하여 공포를 받치는 재료)가 없는 여려개의 기둥을 받쳤다. 당시 행정 관청 건물은 윗부분에 돔 모양의 탑옥(塔屋)을 올려 놓은 것이 일반적이었지만, 이 건물은 이를 생략하는 등 평면과 세부적 외양이 기본 형식에서 약간 벗어나 있다.","a":"구 인천우체국","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2016033015014000.JPG"},{"q":"○○○○○은 ○○○의 정상부(해발 571m)에 있는 산성이다. 소가야가 신라를 방어하기 위해 삼국시대에 쌓은 산성으로 전해져 왔으나, 발굴 조사에서 신라 말에서 고려 초에 쌓은 것으로 확인되었다. ○○○○은 ○○○에 있는 얕은 계곡 2개를 포함하여 쌓은 포곡식(包谷式) 산성이며, 전체 둘레는 약 1,381m이다. 산성을 ○○○의 정상부의 남동쪽 비탈면에 쌓아서 ○○ 읍내에서는 잘 보이나 바다에서는 보이지 않도록 하였다. 북쪽은 성벽이 없는데 이는 험한 지세를 이용하여 의도적으로 성벽축조를 생략한 것으로 추정된다.","a":"고성 거류산성","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664027.jpg"},{"q":"조선 전기 효자 ○○○의 효행을 기리기 위해 세운 비석이다. ○○○에 전해져 내려오는 이야기에 따르면, 백정 출신인 ○○○이 현재의 ○○시 상당구 운동동 비선거리에서 두 아우와 함께 살았는데, 주위 사람들에게 평판이 좋지 않았고 늙은 어머니에게도 효도를 하지 않았다. 어머니가 드러눕게 되자 고려장을 하려고 하였다. 이때 ○○ 남일면 효촌리에 사는 효자로 이름난 경대유慶大有[경연慶延]라는 사람이 이 소문을 듣고 삼형제를 불러 꾸짖자 ○○○ 3형제는 크게 감화되어 이후 노모에게 효행을 극진히 하였다고 한다.","a":"청주 양수척 효자비","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651485.jpg"},{"q":"경남 진해시 현동 고산에 있는 이 산성은 고려말 우왕 10년(1384)에 만든 것이다. 완향성, 비봉산성, 현동산성으로 불렸으며 왜구의 잦은 침입을 방어하고 백성을 보호하기 위하여 만든 것이다. 그러나 ○○○이 웅천현에 합쳐지면서 행정적인 기능을 상실한 것으로 추정한다. 북벽과 동벽이 만나는 산 정상에 고산 봉수대가 있으며, 절벽 위에 세운 남벽을 제외한 동·서·북에는 문터를 두었는데, 서벽은 2곳에 문터를 두었다. 안쪽 벽은 3∼5단의 계단식으로 만들었으며 동벽과 남벽 성 안에는 일정한 간격으로 언덕을 두었다.","a":"창원 완포현 고산성","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656362.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 철원군 갈말읍 토성리에 있는 이 고인돌군은 탁자식으로, 남대천의 강변을 따라 같은 형태, 같은 방향, 일정한 간격으로 일직선상에 만들어졌다. 원래는 7기였던 것으로 추정되나 현재는 2기만 남아있다.","a":"철원지석묘군","c":"시도기념물","nc":"","r":"강원특별자치도","s":"철원군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647799.jpg"},{"q":"조선 중종 때의 문신인 김식(金湜, 1482∼1520)과 그의 후손들인 ○○○○ 가족의 묘역이다. 이 묘역에는 3세손 김육(金堉), 4세손 김좌명(金佐明), 7대손 김성응(金聖應), 8대손 김시묵(金時默) 등의 묘가 있다. 김식의 묘는 부인 전주이씨와 함께 매장된 쌍분(雙墳 ; 두개의 봉분) 형태다. 신도비는 1662년에 제작한 것으로 이수방부형(螭首方趺形 ; 용문양을 장식한 머릿돌과 사각 받침돌의 비석 형태)이다. 조각 솜씨가 뛰어나며 구조가 안정적인데 몸돌은 대리석 재질로 파도문양이 아름답다. 김육은 대동법의 시행을 추진한 인물이다.","a":"청풍김씨문의공파묘역","c":"시도기념물","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647102.jpg"},{"q":"나주 ○○○○○은 나주의 유림이던 겸산 이병수(1855～1941)가 1894년 동학농민혁명을 관군편에서 적은 기록과 1895년 을미년의 의병 등에 관한 기록을 필사한 것으로 나주 지역 동학과 의병운동을 이해하는 사료적 가치가 크다.","a":"나주금성정의록","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640211.jpg"},{"q":"이 불상은 일제강점기에 ○○시 대성동 당산공원의 일본인 신사 터에 옮겨졌다가 해방 이후 청화사(2002년 화재로 전소)로 이전 봉안하였다고 전해지는데, 원래의 위치는 알 수 없으며, 고문헌기록도 전해지지 않고 있어 불상의 출처와 내력을 전혀 알 수 없다. 청화사 자리도 옛 절터는 아닌 것으로 보아 ○○ 우암산 인근의 절터에서 당산공원으로 옮겨졌다가 다시 지금의 자리로 옮겨 봉안된 것으로 추정된다. 실측치는 全高 121㎝, 寶冠高 16㎝, 頭高 30㎝, 頭幅 17㎝, 身高 44㎝, 肩幅 32㎝, 膝幅 48㎝, 臺座高 21㎝, 臺座幅 60㎝, 光背幅 12㎝이다.","a":"청주 모충동 석조비로자나불좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638964.jpg"},{"q":"인천서원은 모두 4채로 이루어진 간소한 서원공간 구성에 전학후묘의 서원구성을 취하고 있다. 전면에 3간의 문간채와 강학공간인 ○○○이 있고, 직선축의 후면에는 3간의 내삼문과 사당인 경인사가 후묘공간을 구성하고 있다. ○○○은 전면5간의 양측에 퇴가 있으며, 측면 1.5간의 건물로서, 구성상 5간의 맞배집의 양 옆에 전면 반간씩의 공간을 증축하여 전면·좌우측 툇집의 구성을 취하고 좌우측의 퇴에는 부섭지붕으로 구성되어 있다. 평면은 전면에 퇴를 두고, 중앙간과 그 동측의 간으로 2간의 마루를 마련하였고, 양측에 각 2간씩의 온돌방을 두었다.","a":"하동 경현당","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665847.jpg"},{"q":"○○○는 18세기 전반에 사세가 융성하고 대대적인 중수 불사를 하면서 당시 대표적인 화승 의겸을 모시고 긍척 등 많은 화승들이 불화불사를 진행하는데 ○○○○○도 이 시기에 그려지면서 전체적인 색감과 화면구성, 각 군중의 표현 등에서 18세기 전남지방의 우수한 특징을 보여주고 있다. 우리나라의 신중도는 조선전기의 작품으로 1583년에 제작된 일본 禪覺寺 소장 ○○○와 일본 西大寺 소장 ○○○, 일본 靈寶館 소장 십이신중도 열두폭이 있다. 조선 후기의 작품으로는 1622년 순천 향림사의 신중도를 제외하고는 모두 18세기나 19세기의 작품들이다.","a":"여수 흥국사 제석도","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640221.jpg"},{"q":"○○○○이란 석가모니가 인도에 있는 영취산에서『법화경』을 설한 법회모임을 말한다. 그러나 시대를 지나면서 ○○○○의 개념은 석가의 설법자체를 의미하는 것으로 바뀌었다. 이 그림은 ○○○○을 이 땅에 실현하고자 하는 강한 신앙심의 구체적 표현이기도 하다. ‘○○○○○’는 대웅전이나 영산전의 불상 뒤편에 봉안되는 것이 보통이다. ○○○○은 일반적으로 석가여래를 중심으로 좌우에 2대 또는 4대·6대·8대 보살과 10대 제자, 불법을 지키는 선신들로 구성된다.","a":"진주청곡사영산회상도","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642304.jpg"},{"q":"○○○은 중국으로부터 유입된 ○○○앙의 대상물로, 마을수호신을 일컫는다. 우리나라에서는 고려 때 부터 모시기 시작했는데, ○○○의 신체가 머무는 곳인 성황당을 만들어 정기적으로 제사를 지냄으로써 마을의 안녕과 풍요를 기원하였다. 우리나라의 ○○○은 대체적으로 마을 수호에 공이 큰 인물을 신격화하여 섬기는 경우가 많은데, 순천 김씨의 시조인 김총 역시 순천의 고을신으로 모셔지고 있다. 김총의 영정은 갑옷을 입고 투구를 쓴 모습으로, 두 손에 창을 들고 있으며 검은색 의자에 앉은 무장상으로 전신을 그린 것이다.","a":"성황신김총영정","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658394.jpg"},{"q":"경상북도 경주시 안강읍 용운사에 모신 높이 176㎝의 불상이다. 배(舟)모양의 타원형 광배(光背) 앞면에 정면으로 꼿꼿이 서 있는 여래상을 매우 도드라지게 새겼으며, 현재 머리 부분 및 광배 윗부분이 없어진 것을 시멘트로 보수하였다. 긴 얼굴에 세모꼴의 코, 작은 입, 짧은 귀 등이 표현되어 독특한 인상을 풍긴다. 몸통과 옷은 간결하게 도식적으로 표현하였으며, 불신 뒤 광배에는 아무런 무늬도 새기지 않아 밋밋하다. 이 불상에서 특징적인 것은 광배 뒷면에 3층탑이 조각되어 있다는 점인데 여기에는 여래좌상이 새겨져 있다.","a":"경주근계리입불상","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662558.jpg"},{"q":"○○○ 범종은 조선 순조 4년(1804) 7월에 대시주 1명과 15명의 일반시주자의 시주를 받아 4천근의 동으로 제작된 청동종이다. 종신(鐘身) 하단에는 “가경구년갑자칠월일대○○○대종중사천근(嘉慶九年甲子七月日大法住寺大鐘重四千斤)” 이라는 명문(銘文)이 음각되어 있고, 시주자와 당시의 주지(住持), 만든이 등이 새겨져 있어 제작연대를 명확히 알 수 있는 조선 후기의 종이다.","a":"보은 법주사 가경구년명 철종","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638855.jpg"},{"q":"이 ｢○○○｣은 1665(현종 6)년에 충청도 ○○지역에 거주하는 70세 이상의 耆老들이 조직한 儒契의 계원명단과 계원들이 쓴 시 및 활동내역을 수록한 1권1책의 필사본이다. ｢○○○｣에는 대략 1590년대를 전후하여 出生하였던 인물들을 대상으로 하고 있다. 수록된 稧會의 開催年度는 김정현(1591～1675)과 조옥(1595～?)이 을사년 正月十八日에 <七十會通文>을 出文한 干支로 볼 때, 1665(乙巳, 顯宗 6)년이었던 것으로 짐작된다. 이 壽會錄에는 대략 1590年代를 前後하여 出生한 人物들을 對象으로 하고 있다.","a":"충주 수회록","c":"문화유산자료","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660850.jpg"},{"q":"건축양식이나 공간 구성적인 면에서 이전 시기의 정자건물에 비하여 부재들의 치수가 작고, 결구수법이 간결해지는 등 근대적 변화를 보여주고 있으며 민속마을 보존차원에서 보존할 가치가 있다.","a":"동계정","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659510.jpg"},{"q":"안동 권씨인 권인형과 그의 아들 권세평의 위패를 모시고 있는 재실이다. 이들은 조선 단종의 외할아버지인 권전의 후손으로 단종 복위를 위한 사육신 사건에 연루되어 일가족들이 화를 당하고 그의 손자인 권책만이 홀로 이곳에 유배되어 정착하게 되었다. 이들은 선조들의 뜻을 받들어 학업에 열중하고 후진양성에 힘쓰며 벼슬길에는 나가지 않았다. 선대에 관계된 한 맺힌 일상의 행적과 문서들은 유언에 따라 은폐하거나 소각했으며 이들의 극진한 효성은 멀리까지 소문이 자자했다. 영조 26년(1750)경에 세웠을 것으로 추측할 뿐 이 재실의 관한 기록은 남아 있지 않다.","a":"각리언곡재","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663287.jpg"},{"q":"『○○○』에는 임진왜란 때 의병활동을 전개한 소계(蘇溪) 최강(崔堈: 1559-1614)과 그의 형인 소호(蘇湖) 최균(崔均:1537-1616)의 행적과 그들에 대한 국가의 포장(襃獎)의 사실들이 기록되어 있으며, 『난중잡록(亂中雜錄)』이나 『선묘중흥지(宣廟中興誌)』등 여러 자료에 그에 대한 기록이 많이 남아 있다. 『○○○○○』은 1823년 ○○으로 새겨서 만든 것으로 180여 년전의 인쇄술 등을 이해하는데 중요한 자료이다.","a":"쌍충록 목판","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666418.jpg"},{"q":"선조(재위 1567∼1608) 때의 문인 표옹 송영구가 은거하던 곳의 후원에 있는 누각이다. 선조 40년(1607)에 부친 상을 당한 뒤에 집 뒤쪽 언덕에 이 집을 짓고, 동쪽 우산에 모셔져 있는 조상들을 추모하였다고 한다. 앞면 3칸·옆면 3칸의 정사각형 건물로, 지붕 옆면이 여덟 팔(八)자 모양의 화려한 팔작지붕집이다. 앞면에 있는 4개의 주춧돌은 1m 정도의 높이로 마치 돌기둥같고, 뒷면은 지반을 계단식으로 다져 얕게 세웠다. ‘○○○’이란 현판은 중국 사신 주지번이 직접 쓴 것을 새긴 것이다.","a":"망모당","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639497.jpg"},{"q":"○○○○○는 명문와(銘文瓦)를 통해 도광 22년(1842)에 건립된 것으로 추정되며 정참판이 기거했다하여 참판집으로 불리던 집이다. 해방 후 밀성박씨 통덕랑 휘석자파에서 매입하여 안채는 사당으로 사용하고 사랑채는 재실로 사용하고 있다. 기와의 제작 수법과 기술이 뛰어나고, 툇마루 청판은 오래된 고식기법(古式技法)으로 조선시대의 치목기법(治木技法)이 역력히 나타나 있고 보존상태가 양호하다. 아울러, 건축 가구법(架構法)이 축조 당시의 목조기술을 파악할 수 있으며 일부의 변형 기단과 일부 부재 교체를 제외하고 원형을 유지하고 있어 건축 연구자료로서 보존할 가치가 있다.","a":"옥천 백운리 고가","c":"문화유산자료","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660824.jpg"},{"q":"태실이란 왕이나 왕실 자손의 태를 모셔두는 돌로 만든 방으로, ○○○는 태실에 태를 모신 것을 기념하는 비이다. 이 비는 ○○○○의 태를 모신 후 세운 비로, ○○○ 절내에 사적비와 나란히 서 있다. 원래는 절 뒤편 산기슭에 있었으나 일제 때 태실을 발굴해간 뒤, ○○○의 스님들에 의해 이 자리로 옮겨온 것이다. 비는 거북받침돌 위로 비몸을 세우고 머릿돌을 올려놓은 모습이다. 거북받침은 머리가 용머리화 되어 입에 여의주를 물고 있다. 머릿돌은 네모난 형태로, 앞면에 두 마리의 용이 서로 엉켜 있는 장면을 도드라지게 새겼다.","a":"명봉사문종대왕태실비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640648.jpg"},{"q":"로마네스크 양식의 3층 교회건물이다. 조선 고종 27년(1890)에 우리나라에 온 ○○○ 1대 주교인 코프의 전도활동으로 ○○○의 기초가 잡히게 되자, 3대 주교인 마크 트롤로프가 건립하였다. 영국인 딕슨의 설계로 감독관 브로크가 1922년에 공사를 시작하여 1926년 5월에 완공하였다. 十자형의 평면구조를 갖고 있는 이 교회는 기초부와 뒷면의 일부는 화강석을 사용하고 나머지 벽체는 붉은 벽돌을 사용하여 지었다. 건물 전체에 공간상의 높낮이를 다르게 하여 율동감을 느낄 수 있다. 특히 종탑부는 중앙의 큰 종탑과 그 앞의 작은 종탑이 생동감있게 연결되어 있다.","a":"성공회 서울성당","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636117.jpg"},{"q":"1890년대 상무좌우사의 접장을 지낸 ○○○의 공을 기념하기 위해 세운 것이다. 상무사는 광무 3년(1899) 상업을 관장하는 기관으로 설립되어 전국 보부상단의 관리를 하였으며, 등짐장수인 부상단을 좌사로, 봇짐장수인 보상단을 우사로 그 명칭을 정했다. 접장은 좌사와 우사를 통틀어 상무사의 우두머리로, 모든 업무를 담당하고 총회를 소집하여 사회를 보는데, 격년제로 뽑으며 각 지역대표 중에서 투표로 선출한다. ○○○은 시장관리를 양심에 따라 공정하게 처리하여 상인들의 권리를 보호하고 발전시키는데 큰 공을 세웠다.","a":"함양 하경순 포선불망비","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664563.jpg"},{"q":"곰솔은 소나무과로 잎이 소나무 잎보다 억세기 때문에 곰솔이라고 부르며, 소나무의 겨울눈은 붉은색인데 반해 곰솔은 회백색인 것이 특징이다. 바닷가를 따라 자라기 때문에 해송으로도 부르며, 또 줄기 껍질의 색이 소나무보다 검다고 해서 흑송이라고도 한다. 바닷바람과 염분에 강하여 바닷가의 바람을 막아주는 방풍림이나 방조림으로 많이 심는다. 고흥 ○○○ 곰솔은 나이가 300년 정도로 추정되며, 높이는 14m, 둘레는 127∼130㎝이다.","a":"고흥옥하리곰솔","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654366.jpg"},{"q":"○○○○는 훌륭한 유학자들의 위패를 모시고 제사지내며 지방백성의 교육과 교화를 담당하기 위해 세워진 것으로 조선 세종 15년(1433)에 처음 지어진 후, 여러 차례에 걸쳐 부분적인 공사가 있었다. 약간 높은 언덕에 자리잡고 있으며, 일반적인 향교의 건물 배치처럼 강당인 명륜당이 앞에 있고 제사 공간인 ○○○이 뒤에 있는 전학후묘의 형식을 보이고 있다. ○○○은 공자를 비롯한 중국과 우리나라 성현의 위패를 모시고 제사지내는 건물이다. 지붕 처마를 받치면서 장식을 겸하는 공포가 기둥 위에만 놓인 주심포 양식의 건물로, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다.","a":"화순향교대성전","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639905.jpg"},{"q":"병진안으로서, 향인의 훼손으로 계유(1753)년과 신묘년에 다시 작성했다가 계속 훼손된 이후 갑오(1774)년에 재차 중수한 것이다. 이 ○○도 총 212인 중 80여인이 도할되었다. 각 가문에 소장된 ○○합록과 비교할 때 원래는 85인이 입록되어 있었던 것으로 보인다.","a":"향안(1736년)","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642523.jpg"},{"q":"고려 후기의 대학자인 가정 이곡(李穀,1298∼1351)과 그의 아들 목은 이색(李穡,1328∼1396)의 문집을 간행하기 위해 만든 것이다. 이곡은 이제현의 문인으로 도첨의찬성사를 지내고 한산군으로 봉해졌다. 이색은 성균관 대사성을 지낸 성리학자로서 포은 정몽주, 야은 길재와 함께 고려가 망할 때 태조 이성계에 굴하지 않고 절개를 지킨 삼은(三隱)으로 불린다. 현존하는 목판은 975판이 있으며, 문헌서원 장판각에 보존되어 있다. 이 목판은 한국 문화사 뿐만 아니라 국문학사의 귀중한 자료로 평가된다.","a":"가정목은선생문집판","c":"시도유형문화유산","nc":"","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639125.jpg"},{"q":"임진왜란시 3대 대첩 중의 하나인 ‘진주성대첩’의 명장인 ○○○ 장군의 생가지와 사사처(射蛇處)인 ○○○이다. 천안시 병천면 가전리 백전마을 노인들의 구전에 의하면, 이 곳은 ○○○ 장군이 태어나 어린시절을 보냈던 생가지로 전하고 있다. 현재는 1944년에 건축된 건물이 공가(空家)로 남아 있다. 사사처는 충무공 ○○○ 장군이 9세의 어린 나이에 활을 쏘아 이무기를 잡았다는 전설이 전해오는 장소이며, 충무공의 상무정신과 용맹함을 기념하기 위해 세운 비가 마을 입구에 있다. 주요 시설물로는 구암(龜巖) 1기, 유적비 1기 등이 있다.","a":"천안김시민장군유허지","c":"시도기념물","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653174.jpg"},{"q":"∙ 종택은 법전리 음지마을에 위치해 음지마를 대표하는 전통주택으로 도로 건너편 양지마을의 양지마의 「봉화 법전강씨 종택」(민속문화유산)과 함께 법전리 마을의 전통적 풍광이 조화를 이루고 있다. ∙ ○○○ 종택은 100여 년전 구 종택을 옮겨 복원한 것이며, 이건 시기인 19세기 후반의 구조양식을 보여주고 있는 건물로 대문채가 멸실되고 없으나 종가의 구색과 품격을 비교적 잘 갖추고 있다.","a":"봉화송월재종택","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663558.jpg"},{"q":"○○○○은 대전 분지의 계족산지 동편 금강의 물길이 잘 조망되는 표고 276m(비고 200m) 능선 정상부에 위치하고 있다. 금강의 본류 및 지류들은 지금은 모두 대청댐이 생기면서 수몰되었으나 이 산성에서는 서쪽으로는 신탄진 방면에서 대전 동구 주산동·옥천 방면으로 연결되는 교통로를 감제(瞰制)할 수 있고, 동쪽으로는 금강을 이용하는 수로를 감시할 수 있다. 그리고 서남쪽으로는 계족산성의 내부를 훤히 들여다볼 수 있어 계족산성의 동쪽 방면을 방호하는 데 매우 중요한 전략적 가치를 가지고 있다.","a":"노고산성","c":"시도기념물","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645802.jpg"},{"q":"이 불화는 조선후기 ○○○○○로는 연대가 올라가는 고불화에 속하며, 적.녹.청.황.백 등의 색채 외에도 조선불화에서 아껴 쓴 금채가 장식적 역할을 하고 있다. 머리모양과 차분한 얼굴표정 등에서 조선전기 불화의 영향을 엿볼 수 있어 유형문화유산으로 지정한다.","a":"정수사지장시왕도","c":"시도유형문화유산","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641147.jpg"},{"q":"풍양면사무소 정원에 자리하고 있는 석탑으로, 인근 야산에 있던 것을 이곳으로 옮겨 놓았다. 원래는 기단부(基壇部) 전체와 탑신(塔身)의 세 지붕돌만 남아 있었으나, 1990년 몸돌과 머리장식을 새로이 만들어 복원해 놓아, 1층의 기단 위에 3층의 탑신을 올린 모습이다. 기단 한쪽 면에는 탑을 세울 당시 함께 새겨둔 기록이 남아 있어 탑을 만든 시기를 정확히 알려주고 있다. 기단 윗면의 탑신을 괴어두는 부분에는 연꽃무늬가 있는데 형식에 그친 감이 있다. 새로 만든 탑신의 세 몸돌은 각각 네 모서리마다 기둥 모양을 본 떠 새겼다.","a":"고흥상림리삼층석탑","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662185.jpg"},{"q":"○○○○는 사찰 입구에 설치하는 것으로, 절에 행사나 의식이 있을 때면 이곳에 당이라는 깃발을 달아두는데, 깃발을 거는 길쭉한 장대를 당간이라 하고, 당간을 양쪽에서 지탱해 주는 두 돌기둥을 ○○○○라 한다. 이 ○○○○는 양 기둥에 별다른 조각이 없다. 기둥 사이에는 당간을 꽂았던 둥근 받침돌이 2단으로 마련되어 있는데, 그 윗면 가운데에 높히 솟아오른 부분을 두어 여기에 깃대를 끼웠던 것으로 보인다. 기둥 안쪽면에는 아래위로 홈을 두어 당간을 고정시키도록 하였다. 조각솜씨가 세련되거나 정교하지 못하나 간결한 모습을 보이고 있어, 고려시대 전기의 작품으로 짐작된다.","a":"괴산 외사리 당간지주","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638608.jpg"},{"q":"강진청자박물관에 소장된 ○○○○○은 ○○○○이 흑상감되어 있는 매우 양질의 청자이다. 강진 고려청자 요지군의 사당리 41호 주변에서 수습되어 학술적 가치와 함께 강진 대구면 지역이 왕실용 청자를 구웠음을 실증적으로 뒷받침하는 매우 중요한 자료이다. 원래 잔과 같이 한 벌로 구성된 기물이나 지금은 잔탁만 있는 상태이지만, 명문을 통하여 특수한 용처를 유추할 수 있고 강진청자의 위상을 설명하는데 중요한 자료이다.","a":"청자상감‘王’명잔탁","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101118262800.jpg"},{"q":"○○○의 대웅전 앞에 있는 ○○○○으로, 탑몸을 점판암으로 만든 청석탑(靑石塔)이다. ○○○는 고려 공민왕 17년(1368)에 지공선사와 나옹선사가 절을 지었으며 처음에는 대국사라 이름하였다가 다시 ○○○로 고쳐 불렀다고 한다. 이 탑은 전체 높이가 173㎝로서, 상륜부는 없어졌으나 화강암으로 된 기단부와 점판암으로 된 탑신부는 약간의 손상을 입은 상태로 남아 있다. 땅에 맞닿아 탑의 토대가 되는 기단부의 바닥돌은 사각의 돌로 되어 있고 그 위에 함께 기단부를 형성하는 하대석이나 중대석, 연화대좌, 상대석이 차례로 놓여져 있다.","a":"의성대곡사다층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663296.jpg"},{"q":"조선 후기에 지은 집으로 안채와 사랑채, 사당과 창고 등으로 구성되어 있다. 학자 허채가 고종 27년(1890) 김해에서 단장으로 이사하면서 지은 것인데, 근대 유학자 허석과 허섭 등을 낳은 유서 깊은 곳이다.","a":"밀양단장면허씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664073.jpg"},{"q":"전라남도 해남에 있는 ○○○ 천불전(千佛展)은 순조 11년(1811)에 화재로 없어진 것을 1813년에 다시 지은 것이다. 천불전에는 중앙에 나무로 만든 삼존불상과 뒤쪽에 옥돌로 만든 천불이 모셔져 있다. 천불이란 과거에도 천불·현재에도 천불·미래에도 천불이 있다는 것으로, 언제 어디서나 부처님이 존재하며 누구나 부처가 될 수 있고 부처의 은혜를 받을 수 있다는 사상을 나타낸 것이다.","a":"대흥사천불상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639887.jpg"},{"q":"○○○ 地藏幀은 현재 명부전에 봉안되어 있는 木造地藏菩薩像 및 石造十王像 등과 함께 함풍 8년 즉, 1858년 大作佛事의 일환으로 이들 彫像들과 같이 동시에 조성된 것임을 彫像 腹藏記와 이 지장탱의 畵記에서 확인된다. 따라서 ○○○ 지장탱은 ○○○의 大作佛事 내력과 조선후기 지장탱으로서의 규모뿐만 아니라 좋은 안료을 사용하여 묘사력이 뛰어난 화격이 높은 탱화 이다","a":"밀양 표충사 지장보살도","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643080.jpg"},{"q":"이곳의 ○○○○○ 화석은 약 1억년 전의 전기 백악기 시대에 살았던 공룡들의 것으로 보인다. 당시의 공룡들은 아열대 기후 아래 우기와 건기가 반복되고 열대 무역풍이 영향을 미치는 사바나 지역의 하천평야 일대에서 살았던 것으로 알려져 있다. 이 곳의 ○○○○○은 약 91㎡ 넓이의 바위에 새겨져 있는데, 초식공룡인 이구아나룡에 속하는 ○○○과 육식공룡에 속하는 ○○○ 등 80여 개가 된다. 빠른 속도로 달려가는 듯한 모양으로 남아 있어서 육식 마니랖토라공룡 한마리가 초식 이구아나룡에 속하는 고성룡 아홉마리를 추격한 것으로 해석된다.","a":"유곡동공룡발자국화석","c":"문화유산자료","nc":"","r":"울산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659794.jpg"},{"q":"○○○○에 모셔져 있는 불화로, 석가의 생애를 여덟 장면으로 나누어 묘사한 ○○○이다. ○○○의 여덟 장면은 석가모니가 도솔천에서 코끼리를 타고 사바세계로 내려오는 장면인 도솔래의상, 석가모니가 룸비니공원에서 마야부인의 옆구리를 통해 출생하는 모습을 그린 비람강생상, 태자가 성문 밖의 중생들의 고통을 관찰하고 인생무상을 느끼는 장면의 사문유관상, 부모의 반대를 무릎쓰고 출가하는 장면을 묘사한 유성출가상, 설산(雪山)에서 신선들과 수행하는 모습을 그린 설산수도상, 태자가 수행 중 온갖 유혹과 위협을 물리치는 수하항마상, 부처가 녹야원에서 최초로 설법하는 모습을 나타낸…","a":"혜원정사 팔상도","c":"문화유산자료","nc":"","r":"부산광역시","s":"연제구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019042510134700.jpg"},{"q":"고가는 대지면적 1,252㎡에 6동의 건물이 배치되어 있으며 2개 영역 으로 나누어져 있고, 안채영역에 안채, 고방채 사랑채 영역에 사랑채, 대문채, 별채가 있으며 안채와 사랑채 사이에 안대문이 있다.","a":"창녕 영산 신씨고가2","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665141.jpg"},{"q":"○○ 탄금대 남쪽의 충적지로 이어지는 매우 완만한 구릉에 입지하고 한반도 중·남부 지역에서 최대 규모의 제철 생산단지 가운데 하나로 우리나라 고대 철 생산 양상과 실태를 이해하는데 중요한 유적이다. ○○○○○에서 확인된 이중의 방습 시설은 처음 찾아진 것으로 한국 고대 제철사에서 중요한 의미를 지니고 있다. 또한 이 유적처럼 대규모의 철 생산 시설이 조사된 경우도 없고 특히 장기간 조업을 위한 제철로의 조성 방법(하․중․상층의 중층적 조성)과 그 기법은 매우 특이하고 독창적이다.","a":"충주 칠금동 제철유적","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019080616261300.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 고려 공양왕 3년(1391)에 용강산 기슭에 세웠다. 그 뒤 여러 차례 보수하여 전하다가，용담댐 건설로 인하여 1998년에 지금 있는 자리로 옮겨 지었다. ○○○은 공자를 비롯하여 여러 성현에게 제사를 지내는 곳으로, 규모는 앞면 3칸·옆면 3칸인데 왼쪽은 2칸으로 분리되어 있다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포 양식이다.","a":"용담향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661633.jpg"},{"q":"원동면 ○○○ 화제초등학교 교사 뒤쪽 낮은 구릉상의 민묘가 있는 지역 일대가 양산 ○○○○○이다. 양산 ○○○○○에서는 녹청자 가마와 도편(陶片)이 확인되었다. 채집된 도편은 모래 등 잡물이 섞인 거친 태토를 사용하여 만들었다. 또한 철분 함량에 따라 녹색, 갈색, 회색 등이 발색되었는데, 표면은 고르지 못하다. 양산 ○○○○○에서 수습된 녹청자편은 인천시 북구 경서동, 전라남도 해남군 산이면 진산리 가마에서 발견된 녹청자와 비슷한 특징이 있다. 발견된 도편은 거의 대부분 문양이 없으며, 주로 대접류와 접시류가 채집되었다.","a":"양산화제리도요지","c":"시도기념물","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656494.jpg"},{"q":"○○○○○는 만취당(晩翠堂) 김사원(金士元)의 무덤을 보호하고 제사를 위해 지어진 재사(齋舍) 건물로 건축을 고쳐지은 기록(追遠齋重修記, 2001)에 따르면 그를 기리기 위해 후손들과 마을주민들이 힘을 합쳐 1809년에 만들었다고 한다.","a":"의성 추원재","c":"문화유산자료","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019091109283000.JPG"},{"q":"독촌공 조종영의 효행을 널리 알리기 위하여 세운 정려각이다. 조종영은 조선 단종(재위 1452∼1455) 때 생육신의 한 분인 어계 선생의 후손으로 학문과 행실이 두터웠으며, 효성이 지극하여 부모가 살아계실 때는 물론이고 돌아가신 후에도 변함이 없었다. 이러한 효행이 널리 알려져 고종 29년(1892)에 ‘효감유허비’를 세웠으며, 광무 9년(1905)에 조정의 명령을 받아 정려각을 세웠다. 규모는 앞면·옆면 모두 1칸이며, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다.","a":"함안 오비각","c":"문화유산자료","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664272.jpg"},{"q":"◦ 진당산 서쪽 기슭 폐사지에 매몰 방치되었던 석탑을 1974년 발굴하여 현재의 위치에 이전하고 복원하였음. ◦ 화강암으로 되었으며, 높이는 350cm이고, 건립연대는 알 수 없음. 다면 이 탑은 체감율이 거의 없어 둔중한 느낌을 주고, 형식이 간략화되는 것 등으로 보아 고려시대의 양식으로 보임. ◦ 거칠게 다듬은 기단부에는 우주나 탱주의 모각(模刻)은 없고, 받침돌만 모각이 있으며, 탑신석에는 우주와 3단의 받침돌 모각이 있음. 맨 꼭대기 5층의 탑신석과 옥개석이 없어 현재는 4층만 남아있음.","a":"보령리오층석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661123.jpg"},{"q":"돈대는 적의 움직임을 살피거나 공격에 대비하기 위해서 영토 내 접경지역이나, 해안지역의 감시가 쉬운 곳에 마련해 두는 초소이다. 대개 높은 평지에 쌓아두는데, 밖은 성곽을 높게 하고, 안은 낮게 하여 포를 설치해 두는 시설물이다. 정포보 소속의 이 돈대는 타원형에 가까운 형태로, 포를 설치해 두기 위한 포좌를 4곳에 설치하였다. 조선 숙종 5년(1679) 윤이제가 ○○유수로 재임해 있을 때, 병조판서 김석주의 명을 받아 쌓아놓은 것이라고 전한다.","a":"강화 굴암돈대","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645645.jpg"},{"q":"조선 전기 무신인 박곤(1370∼1454) 장군과 관련된 이야기가 전하는 연못이다. 경상남도 밀양시 무안면 연상리의 ‘어변당’이라는 박곤의 생가 근처에 있다. 박곤이 어렸을 때 어머니께서 물고기가 먹고 싶다고 하였으나 마침 겨울이라 고기 잡기가 어려웠는데, 이를 잘 알면서도 마을 앞 냇가로 나가 얼음을 깨고 낚시를 하여 대접하였다고 한다. 어린 박곤은 어머니께 계속해서 고기를 대접할 방법을 생각하던 중, 집 뜰에다 조그만 연못을 파고 고기를 길렀는데 그 연못에는 유별나게 비늘이 붉은 물고기가 크게 자라고 있었다.","a":"밀양적용지","c":"시도기념물","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656040.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 조선 태조(재위 1392∼1398) 때 지은 후 효종(재위 1649∼1659) 때 지금의 위치로 옮겨지었고 1966년에 수리하였다. 지금 남아있는 건물은 중국과 우리나라 유학자의 위패를 모시고 있는 사당인 대성전과 학생들이 모여서 공부하는 강당인 명륜당이다. 조선시대에는 나라로부터 토지와 책·토비를 지급받아 운영하였으나 갑오개혁(1894) 이후 교육적 기능은 없어지고 지금은 제사의 기능만 남아있다. 소장되었던 책은 모두 흩어지고 잃어버려 거의 없는 상태이다.","a":"옥천 청산향교","c":"시도유형문화유산","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638541.jpg"},{"q":"불상의 얼굴은 방형이며 불신에 비해 얼굴이 큰 편이나 좁은 어깨와 넓은 무릎 폭으로 인해 안정감이 있어 보이고 두 귀는 크고 짧은 목에 삼도가 뚜렷하다. 오른손은 항마촉지인을 하였고 별개로 만든 왼손은 발 위에 놓아 중지와 약지를 구부렸다. 오른쪽 어깨위로 둥글게 걸친 변형 우견편단식 법의와 옷 주름을 단조롭게 표현하였다. 조선후기 불상 조성양식의 한 예를 잘 보여주고 있으며 보존상태도 양호하여 조선후기 불교미술사 연구에 귀중한 자료이다.","a":"천안 은석사 목조여래좌상","c":"시도유형문화유산","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639299.jpg"},{"q":"고려 태조 왕건을 도와 후백제를 평정하는데 공을 세운 밀양손씨의 입향조이자 중시조인 손긍훈(孫兢薰)의 ○○이다. 손긍훈은 고려 건국공신으로 태조 왕건을 도와 후백제 견훤의 아들인 신검을 황산전투에서 사조잡은 공로로 좌명공신에 선정되고, ○○○에 봉해졌으며 그가 죽은 후에 ○○○○○에 추증되었다. 1894년 갑오경정 이후 관향이 폐지되자 후손들이 춘복재의 현충사로 이봉하여 모셨으며 현재는 밀양시립박물관에 보관 중이다.","a":"삼중대광사도광리군 목상","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664351.jpg"},{"q":"‘○○○’는 삼학사[三學士 ; 홍익한洪翼漢)·윤집(尹集)·오달제(吳達濟)]의 넋을 위로하고 충성스런 절개를 기리기 위하여 세운 사당이다. 이들 삼학사는 병자호란[丙子胡亂 ; 1636년-1637년에 일어난 조선과 청나라의 전쟁] 때 중국 청나라와의 화의를 반대하여 나라를 위해 목숨 바쳐 충성했던 사람들이다. 뒷날 이들과 뜻을 같이했던 김상헌(金尙憲, 1570년-1652년)과 정온(鄭蘊, 1569년-1641년)도 추가로 사당에 모셨다. 사당은 남한산성 기슭에 세워졌으며, 1693년 왕이 내린 ‘○○○’라는 이름으로 불리게 된다.","a":"현절사","c":"시도유형문화유산","nc":"","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637318.jpg"},{"q":"‘수원시 ○○○○○’는 ○○○의 주불전인 약사전에 봉안되어 있는 ○○로, 우측벽에는 신중탱화, 좌측벽에는 현왕탱화가 걸려 있다. 신중탱화의 상단부에는 제석과 범천이 천부중(天部衆)을 거느리고 있고, 하단에는 위태천을 중심으로 팔부신장과 용왕, 금강상 등이 그려져 있어 19세기 신중탱화의 일반적인 구성을 보여준다. 화기에는 ‘1891년 2월에 수원부(水原府) 광교산 ○○○에 신중탱 한 점을 봉안하고, 금어 비구 현조(現照)·수조(須照)가 그렸다’고 쓰여 있다. 붉은 색을 주요 색상으로 원색의 청색을 사용하여 두 색감의 대비가 심하다.","a":"봉녕사 불화(신중탱화.현왕탱화)","c":"시도유형문화유산","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637662.jpg"},{"q":"1913년 소눌 노상직(1854∼1931)이 망명지인 만주에서 돌아와 저술과 후진양성을 위해 마련한 강학소이다. 소눌은 만년에 학덕이 날로 높아 사림의 자녀들이 크게 모여 천여 명에 달하는 후진을 양성하였으며, 『소눌문집』 등 많은 글을 이곳에서 썼다.","a":"밀양 자암서당","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664305.jpg"},{"q":"산불조심의 경각심을 일깨워주기 위해 세운 비로, 자연석을 다듬지 않고 그대로 사용하였다. 서쪽면에 ‘○○○○’이라는 순 한글 글자를 세로로 큼지막하게 새겨 놓았다. 조선시대에는 국경수호와 산성 등을 지키기 위해서는 일반인의 통행을 금지하고 산불을 조심하는 것이 가장 먼저 해야 할 일이었으므로 이를 서민들이 잘 알 수 있도록 한글비를 세웠던 것으로 보인다. 순수 한글비라는 점에서 큰 가치가 있는 이 표석은 ‘조심’을 ‘됴심 ’이라고 기록한 것으로 보아 조선 영·정조 시대에 세운 것으로 짐작된다.","a":"조령산불됴심표석","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662864.jpg"},{"q":"○○○에 보존되어 있는 그림으로, ○○○은 원래 인도의 방위신(方位神)이었으나, 불교에 흡수되면서 천부세계의 도상으로 수미산에 거주하면서 사방을 수호하는 호법신의 이미지가 강화된 것으로 전한다. ○○○은 동방은 지국천왕, 남방은 증장천왕, 서방은 광목천왕, 북방은 다문천왕이라 일컬으며, 이들은 수미산의 동서남북에 각각 거주하면서 사방을 지킨다. ○○○○○는 세로 350㎝가 넘는 두루마리형의 비단 4폭에 천왕상 1구씩을 그렸다.","a":"범어사 사천왕도","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636691.jpg"},{"q":"조선 중기의 무신인 안위(1563∼?) 장군의 묘이다. 선조 25년(1592) 무과에 급제하였으며, 이듬해 거제 현령이 되었다. 1594년 제2차 당포해전 때 이순신의 지휘 아래 전부장(前部將)으로 공을 세웠으며, 1597년 부산의 왜군 화약고에 불을 질러 폭파시켰다. 이후에 전라 우수사를 거쳐 전라도 병마사 등 여러 관직을 역임하였다. 선조 30년(1597) 정유재란이 일어나자 통제사 이순신의 지휘 아래 왜선 20여 척을 격파하여 선조로부터『무경칠서(武經七書)』를 상으로 받았다. 후에 임진왜란 때의 전공자로서 선무공신(宣武功臣) 20명 가운데 한 사람으로 뽑혔다.","a":"안위장군묘","c":"시도기념물","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653685.jpg"},{"q":"경상북도 봉화군 봉성면 ○○○에 있는 불상으로, 거대한 암벽바위를 조각하여 불상의 몸을 새겼으며 머리는 다른 돌로 만들어 올렸다. 머리를 다른 돌로 만든 예는 고려시대에 간혹 나타나는데 이 불상도 동일한 계열로 여겨진다. 광배(光背)를 나타내는 바위 자체의 테두리는 많이 깨져 있다. 머리 높이가 1.27m나 되는 우람한 모습이고 얼굴은 긴 편이다. 굵은 눈썹이 좁은 이마에 바싹 붙어 있고, 눈은 재미있게 웃고 있다. 코는 너무 길어 턱까지 내려와 입이 간신히 표현되었고 뺨이 유난히 팽창되는 등 토속미를 물씬 풍기고 있다.","a":"봉화봉성리석조여래입상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640519.jpg"},{"q":"현재 ○○○ 법당에 봉안되어 있는 돌로 만든 삼존불좌상으로 삼존불 가운데 본존상은 좌우의 두 상에 비해 약간 큰 편이다. 중앙에 있는 본존불은 원래는 얼굴이 동그랗고 온화한 모습의 불안(佛顔)이었던 것으로 보이나, 지금은 마멸이 심하여 이목구비를 잘 알아볼 수 없다. 목과 백호가 새겨진 부분도 손상되어 후보(後補)된 상태이다. 대의는 어깨를 드러내는 편단우견식으로 입었고 어깨와 무릎에는 넓은 띠주름이 새겨져 있다. 오른손은 올려 수인을 결하고 있다.","a":"도선사 석 삼존불상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636479.jpg"},{"q":"○○○은 조선 중기 문신인 추천 손영제가 지은 정자이다. 손영제는 이황의 제자로 학문과 정치에 대해 가르침을 받았으며, 조선 명종(재위 1545∼1567) 때 정랑을 거쳐 예안, 김재, 울산 군수 등을 지냈다. 지금 있는 건물은 1936년에 후손들이 다시 세운 것이다.","a":"밀양 오연정","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664352.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 이 고인돌은 바둑판식인데 받침돌이 없는 형태로 판석을 받침돌 겸 석관의 벽으로 삼아 매장부를 지상에 마련한 형태이다. 석관의 남동벽은 없어졌고, 북벽은 3개의 판석으로 되어 있으며, 마무리 벽인 서벽은 1개의 판석으로 이루어졌다.","a":"부곡지석묘","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660415.jpg"},{"q":"○○○는 ○○ 근교에서 가장 오래된 사찰로, 신라 진흥왕 28년(567)에 의신이 창건하였다. ○○○ 극락보전 앞에 자리한 이 탑은 1층 기단(基壇) 위에 5층의 탑신(塔身)을 올리고 머리장식을 갖춘 모습이다. 기단은 3단의 괴임돌을 크기를 줄여 쌓아올린 모습이다. 맨윗돌의 괴임 윗면에는 아래로 향한 8잎의 연꽃무늬를 조각해 놓아 통일신라 후기나 고려의 석탑양식이 엿보인다. 탑신부는 1층 몸돌의 각 모서리에 기둥모양을 새겼고, 그 사이에 사각형과 원을 조각한 뒤 범자(梵字:불교문자)를 새겨 넣었다. 지붕돌은 두껍고 네 귀퉁이는 치켜올림이 전혀 없다.","a":"청주 보살사 오층석탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638486.jpg"},{"q":"○○○ 노극복이 벼슬을 버리고 고향으로 돌아와 지내던 곳이다. 노극복은 조선 중기 학자로 어려서부터 문예가 뛰어났으며, 정온·심광세·임진무 등과 더불어 성리학을 깊게 연구하고 토론하였다. 그는 학식이 해박하여 인조(재위 1623∼1649)가 등용하였는데 벼슬이 이조정랑에까지 올랐다. 그러나 벼슬보다는 학문에 뜻을 두고 있던 선생은 벼슬을 버리고 초계에 있는 고향집으로 내려와 학문에만 전념하니, 왕이 그의 집을 ‘○○○’이라 하였다. 건물을 언제 세웠는지 기록은 없지만 숙종 21년(1695)에 후손들이 고쳐 세웠다는 기록이 있다.","a":"합천 주필각 ∙ 월화당","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664253.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 최창민과 유생들이 효종 9년(1658)에 세운 이곳은 숙종 45년(1719) 영조 5년(1729)에 수리하였으며, 그 후에도 여러 차례 고쳤다. 또한 한국전쟁으로 인해 건물의 일부가 파손된 것을 1953년에 고쳤다. 현재 남아 있는 건물은 2층 누각인 풍화루와 학생들이 공부하던 강당인 명륜당이 있고, 내삼문과 공자를 비롯하여 여러 성현들을 모시고 있는 대성전이 있다. 이 외에도 홍살문과 부속건물 3동이 있다.","a":"평창향교","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638111.jpg"},{"q":"조선 선조 34년(1601)에 문과에 급제하여 호조, 예조정랑 등의 관직을 지낸 옥봉 권위(1552∼1630) 선생이 학문을 익히고, 제자를 양성하기 위해 선조 20년(1587)에 세운 건물이다. 건물의 전체적인 구성은 ㄱ자형으로 왼쪽에는 온돌방이 있고, 오른쪽에는 옥마루를 깔았다. 원래 온돌방은 1칸으로 되어 있었는데 현재는 방 사이에 문틀이 설치되어 있다. 마루 위쪽에는 임진왜란 당시 명나라 장수 주원조와 화답한 시문이 걸려 있으며, 동생인 권오가 쓴 ‘만대헌’이란 현판이 있다.","a":"안동만대헌","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640822.jpg"},{"q":"장충사는 조선 인조 10년(1632)에 나라를 위해 목숨을 바친 이들의 순국정신을 기리고, 본받기 위해 세운 서원이다. 효종 8년(1657)에는 임금이 직접 글씨를 쓴 액자를 하사 받은 사액서원으로 고종 5년(1868) 서원철폐령으로 해체되었다가 1964년 지방 유림들에 의해 새로 지어져 오늘에 이르고 있다. 장충사에서는 임진왜란 때 힘껏 싸우다 전사한 동래부사 천곡 송상현을 비롯하여 무장공 신호, 장무공 김준의 제사를 모시고 있다.","a":"정충사지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653575.jpg"},{"q":"○○○는 대승불교에서 호법선신(護法善神)으로 봉안되어 신앙의 대상이 된 신중(神衆)을 알기 쉽게 그림으로 나타낸 예배용 불화이다. 이 ○○○는 ○○○○○ 금당에 모셔져 있는 신중탱화로서, 비단 바탕에 채색하여 그렸으며, 크기는 전체 121㎝×128㎝이다. 상·하 2단으로 된 화면의 상단에는 연꽃가지 1개를 오른손에 들고 보관을 쓴 석가여래를 가운데 모시고 그 주위에 천상중을 배치하였다. 화면의 중앙에 해당하는 하단 가운데에는 날개 달린 투구를 쓴 동진보살을 모시고 그 주위에 신중상을 배치하였다.","a":"양산 통도사 안양암 함평11년명 신중도","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642340.jpg"},{"q":"전체적으로 팔과 손은 몸체에 비하여 작게 표현되고 옷주름의소략화된 표현 등이 보이나 풍만한 상호와 눈두덩을 도독하게 표현하였다. 어깨가 약간 왜소해졌으나 당당함이 남아있고 비교적 단아한 모습이며 手印과 衣紋의 표현이 단정하고 깔끔하게 조각된 불상이다.","a":"충주 강천리 석조여래입상","c":"문화유산자료","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660814.jpg"},{"q":"본 작품은 현재 박물관 입구 정면에 있는 단독 유리 진열장내에 8각 목조대좌 위에 봉안되어 있다. 도금 후 오래서인지 가슴 위의 도금은 전체적으로 아주 미세한 갈라짐이 생겨 있고, 발목아래의 군의, 무릎 등에도 도금이 박락되어 있는 것이 군데군데 확인된다. 또한 오른쪽 발목에서 아래로 목재의 균열이 있다. 오른쪽 손의 검지, 중지, 무명지와 왼쪽 손의 무명지는 파손되어 접합·수리되었다. 손목을 끼우는 안쪽으로 한지를 씌어 손목이 헐거워 빠지는 것을 방지하였으며, 보관을 씌운 후 헐거운 빈 공간에도 한지를 가늘게 말아 고정해 세세한부분까지 정성을 기울였음이 엿보인다.","a":"밀양 표충사 목조관음보살좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643066.jpg"},{"q":"조선시대 지방의 초등교육을 담당했던 서당 건물이다. 조선 숙종 23년(1677)에 교육을 실시하는 ○○○과 제사를 지내는 용문영당을 함께 세웠으나 용문영당은 허물어져 없어졌다. ○○○의 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆면이 사람 인(人)자 모양인 맞배지붕이다. 오른쪽에는 마루, 왼쪽에는 온돌방이 있는 매우 소박한 구성의 집이다. 온돌방 북쪽 벽에는 송시열의 영정을 모시는 감실을 두었다. 그 외 당내에는『시안』,『용문서당계좌목』 2개의 문서가 보존되어 있다.","a":"옥천 경현당","c":"시도유형문화유산","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638642.jpg"},{"q":"조선 숙종 때의 대학자이자 정치가인 우암(尤庵) 송시열(宋時烈, 1607∼1689)을 제향(祭享)하기 위해 1785년(정조 9) 경기도 여주(驪州) 강변에 지은 대로사(大老祠)의 내력을 기록한 비이다. ‘대로(大老)’란 정조가 지어준 송시열의 존칭이다. 정조는 송시열이 태어난 후 3번째 맞는 회갑년(1787)에 그를 기리기 위해 총 높이 약 390㎝에 이르는 장대한 규모의 ○○○○를 건립하였다. 비신(碑身; 글씨를 새기는 부분)의 앞면 중앙에 전서(篆書)로 ‘大老祠碑(○○○○)’라고 크게 쓴 후 비신의 좌측면, 뒷면, 우측면에 해서(楷書)로 비문을 썼다.","a":"대로사비","c":"시도유형문화유산","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637482.jpg"},{"q":"중국 ○○○대가의 문장 100편을 正祖(정조)가 친히 정선해서 1786년(정조 10) 경에 간행한 판본으로, 정조 자신의 수택본(手澤本)을 생원(生員) 최명정(崔命鼎)에게 내사(內賜)한 서적(書籍)이다. 권1 권수제 아래에 정조의 사인(私印)이었던 만기(萬幾)와 홍재(弘齋)라는 장서인이 있다. 당시 선비들이 古文을 본보기로 삼지 않고 명ㆍ청의 시문과 패관잡서(稗官雜書)에 관심을 기울이자, 이를 그대로 두면 文風과 士風이 어지러워진다고 판단하여 중요하다고 생각되는 100편의 정통 고문을 편차하여 간행하였다.","a":"당송팔자백선","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637230.jpg"},{"q":"주변에 흩어져 있던 석탑의 각 부분들을 수습하여 쌓아 올린 것으로, 땅 위에 막돌과 길다란 돌 2개를 깔아 바닥돌을 삼고, 그 위에 아래층 기단(基壇) , 위층 기단, 탑신(塔身)의 1층 몸돌, 지붕돌 3개를 순서대로 올려 놓았다. 아래층 기단의 각 면에는 2개씩의 안상(眼象)을 새겨 놓았고, 위층 기단에는 기둥 모양을 조각하였다. 두툼한 지붕돌은 네 귀퉁이가 위로 뾰족하게 치켜 올라갔으며, 밑면에는 2단의 받침을 두었다. 고려시대 후기의 작품으로 추정된다.","a":"장남리삼층석탑","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660330.jpg"},{"q":"향교는 공자와 여러 성현들께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태종 3년(1403) 흑산리에 처음 지었고, 숙종 36년(1710)에 지금 있는 자리로 옮겨 세웠다. ○○○의 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 공자를 비롯한 그 제자와 우리나라 성현들의 위패를 모시고 있다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생을 가르쳤으나, 지금은 교육 기능은 없어지고 제사 기능만 남아 있다.","a":"임피향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661705.jpg"},{"q":"전북특별자치도 정읍시 영원면 장문리와 은선리의 경계를 이루는 응봉산의 금사동 골짜기를 품고 산을 둘러쌓은 산성으로, 내성과 외성의 2중성으로 되어있다. 성의 주변지역에는 옛 탑과 무덤들이 분포되어 있다. 내성은 동서 양쪽 봉우리를 감싸고 있는데, 그 사이는 길이 427m에 이르는 평평한 대지가 펼쳐져 있다. 북쪽에는 수구(水口)가 3군데에 나있으며, 남쪽에는 중앙에 문터가 남아있고, 성 안에는 건물터와 3곳의 샘터가 있으며, 백제의 것으로 보이는 그릇조각들이 흩어져 있다.","a":"금사동토성","c":"시도기념물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653511.jpg"}]);